// === ORTAK OCR YARDIMCILARI ===
const _splitIntoStrips = (srcB64, stripCount) => {
  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = "Anonymous";
    img.onload = () => {
      const strips = [];
      const stripHeight = Math.ceil(img.height / stripCount);
      for (let i = 0; i < stripCount; i++) {
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = stripHeight;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = 'white';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, i * stripHeight, img.width, stripHeight, 0, 0, img.width, stripHeight);
        strips.push(canvas.toDataURL('image/jpeg', 0.95).split(',')[1]);
      }
      resolve(strips);
    };
    img.onerror = () => resolve([srcB64]);
    img.src = 'data:image/jpeg;base64,' + srcB64;
  });
};

const _ocrCall = async (imageB64, prompt, model, imgType, apiKey) => {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
  const r = await NetworkUtils.fetchWithRetry(url, {
    method: 'POST',
    body: JSON.stringify({
      contents: [{ parts: [
        { inlineData: { mimeType: imgType, data: imageB64 } },
        { text: prompt }
      ] }],
      generationConfig: { temperature: 0.0, maxOutputTokens: 2048 }
    })
  });
  if (!r) return "";
  const data = await r.json();
  return data.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || "";
};

const _OCR_MODELS = AI_CONFIG.OCR_MODELS;
const ocrWithFallback = async (b64Data, imgType, apiKey, logPrefix = 'Görsel') => {
  const models = _OCR_MODELS;
  const strategies = [
    { strips: 3, prompt: 'Bu şeritteki yazıyı oku. Sadece metni yaz, başka bir şey yazma.', label: '3 şerit' },
    { strips: 5, prompt: 'Bu görsel şeritteki yazıyı tam olarak oku. Sadece metni ver.', label: '5 şerit' },
    { strips: 0, prompt: 'Bu resimdeki tüm yazıyı en üstten en alta, satır satır yaz. Sadece metni ver.', label: 'tam görsel' }
  ];
  for (const strategy of strategies) {
    addSystemLog(`${logPrefix}: ${strategy.label} denemesi...`, 'info');
    for (const model of models) {
      try {
        if (strategy.strips > 0) {
          const strips = await _splitIntoStrips(b64Data, strategy.strips);
          const stripTexts = [];
          for (let i = 0; i < strips.length; i++) {
            const result = await _ocrCall(strips[i], strategy.prompt, model, imgType, apiKey);
            if (result.length > 2) {
              stripTexts.push(result);
              addSystemLog(`  Şerit ${i+1}: "${result.substring(0, 40)}..."`, 'info');
            }
          }
          if (stripTexts.length > 0) {
            const text = stripTexts.join('\n');
            addSystemLog(`✓ ${model} ${strategy.label} başarılı: ${text.length} karakter`, 'success');
            return text;
          }
        } else {
          const result = await _ocrCall(b64Data, strategy.prompt, model, imgType, apiKey);
          if (result.length > 15) {
            addSystemLog(`✓ ${model} ${strategy.label} başarılı: ${result.length} karakter`, 'success');
            return result;
          }
        }
      } catch (e) {
        addSystemLog(`  ${model} ${strategy.label} hatası: ${e.message}`, 'warn');
      }
    }
  }
  return '';
};

// v1.175: Gemini, google_search aracını responseMimeType/JSON şemasıyla birlikte REDDEDİYOR
// ("Tool use with a response mime type: 'application/json' is unsupported", HTTP 400).
// Emekli öğe alerti: eski 'gemini-2.5-flash-preview-09-2025' modeli de 404 döndürüyordu.
// Çözüm: araçlı isteklerde JSON mime/şeması kaldırılır; şema METİN talimatı olarak gömülür.
// _callGeminiAndParse zaten kod çitlerini keseip {…} dilimleyerek gevşek parse ediyor.
const _stripJsonConfigForSearch = (payload) => {
  if (!payload?.tools?.length || !payload.generationConfig?.responseSchema) return payload;
  const schemaText = JSON.stringify(payload.generationConfig.responseSchema);
  delete payload.generationConfig.responseMimeType;
  delete payload.generationConfig.responseSchema;
  const jsonRule = `STRICT JSON OUTPUT: Dönüşün TAMAMI şu şemaya uyan TEK geçerli JSON olsun (markdown çiti, açıklama, ek metin YASAK). Şema: ${schemaText}`;
  if (payload.systemInstruction?.parts?.[0]?.text) payload.systemInstruction.parts[0].text += `\n\n${jsonRule}`;
  payload.contents[0].parts.push({ text: jsonRule });
  return payload;
};
// v1.179: Gemini ücretsiz metin kotası bittiğinde (HTTP 429 → fetchWithRetry deneme
// tükenmesi) istek hangi sağlayıcıdan sorusu, aynı istek ŞEKLİ kendi gateway analiz
// zincirine (OpenRouter → Groq → NVIDIA → Gemini server-side) paslanır. Sözleşme:
// POST /api/analysis/text|vision → {ok, text, provider, model}; dönen metin aynı
// gevşek parse ile JSON'a çevrilir. Yalnız yerel kurulumda (__OTONOM_GATEWAY__ define)
// aktiftir; canvas sürümünde bu yedek yoktur ve eski hata aynen yüzeye çıkar.
const _otonomAnalysisBase = () => {
  try {
    if (typeof __OTONOM_GATEWAY__ === 'string' && __OTONOM_GATEWAY__) return String(__OTONOM_GATEWAY__).replace(/\/+$/, '') + '/api/analysis';
  } catch (e) {}
  return '';
};
// v1.180: Kesik model çıktısını onaran JSON parser. Zincir sağlayıcıları
// (özellikle reasoning üreten gpt-oss ailesi) bütçeyi reasoning'e harcayıp JSON'u
// ortasında kesebiliyor; gerçek üretimde kanıt: "end of data when ',' or ']' was
// expected at line 1 column 224". Dize kaçışlarına duyarlı tarama ile açık
// parantezleri kapatıp onarmayı DENER (kesim "değer sınırında" ise çalışır,
// bir string'in ortasında kaldıysa yol yoktur); onarım kullanıldığında
// ve onarılamadığında sessiz geçiş YAPMAZ — çağıran ham çıktı başını loglar.
const _parseMaybeTruncatedJson = (rawText, label) => {
  let s = String(rawText || '').replace(/`json/gi, '').replace(/`/g, '').trim();
  const start = s.indexOf('{');
  if (start === -1) throw new Error(`${label} JSON formatında yanıt döndürmedi.`);
  const slice = s.substring(start, s.lastIndexOf('}') !== -1 ? s.lastIndexOf('}') + 1 : s.length);
  try { return { value: JSON.parse(slice), repaired: false }; } catch (strictErr) { /* kesik; onarım aşağıda */ }
  const stack = []; let inStr = false, esc = false;
  for (let i = 0; i < slice.length; i++) {
    const ch = slice[i];
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; }
    else if (ch === '"') inStr = true;
    else if (ch === '{' || ch === '[') stack.push(ch);
    else if (ch === '}' || ch === ']') stack.pop();
  }
  let out = slice;
  if (inStr) { while (out.endsWith('\\')) out = out.slice(0, -1); out += '"'; }
  out = out.replace(/[\s,:]+$/, '');
  while (stack.length) out += stack.pop() === '{' ? '}' : ']';
  try {
    const value = JSON.parse(out);
    addSystemLog(`${label}: çıktı max-token sınırında kesik geldi; JSON onarılıp kullanıldı (dikkat: yanıt eksik olabilir).`, 'warn');
    return { value, repaired: true };
  } catch (repairErr) { return null; }
};
const _callAnalysisChainAndParse = async (payload) => {
  const analysisBase = _otonomAnalysisBase();
  if (!analysisBase) throw new Error('Yerel analysis zinciri yok (gateway adresi bilinmiyor).');
  const parts = payload?.contents?.[0]?.parts || [];
  const textParts = parts.filter(p => typeof p?.text === 'string').map(p => p.text);
  const images = parts.filter(p => p?.inlineData?.data).map(p => `data:${p.inlineData.mimeType || 'image/png'};base64,${p.inlineData.data}`);
  // Sağlayıcılarda yedek betimleme niteliğiyle uyumsuz olan google_search aracı taşınmaz.
  const systemText = payload?.systemInstruction?.parts?.map(p => p?.text).filter(Boolean).join('\n');
  const endpoint = `${analysisBase}/${images.length ? 'vision' : 'text'}`;
  const r = await fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      prompt: textParts.join('\n\n'),
      system: systemText || undefined,
      ...(images.length ? { images } : {}),
      temperature: payload?.generationConfig?.temperature,
      // v1.180: maxOutputTokens gönderilmeyen isteklerde zincir default 2048'de
      // kalıyor; reasoning üreten sağlayıcı (gpt-oss-120b) bütçeyi reasoning'e
      // harcayıp JSON'u ~224. karakterde kesiyordu (gerçek üretim kanıtı).
      maxTokens: Math.max(Number(payload?.generationConfig?.maxOutputTokens) || 0, 8192),
    }),
    signal: AbortSignal.timeout(150000),
  });
  if (!r.ok) {
    let detail = '';
    try { detail = (await r.json())?.message || String(await r.text()).slice(0, 160); } catch (e) {}
    throw new Error(`Analysis zinciri HTTP ${r.status} ${detail}`.trim());
  }
  const d = await r.json();
  if (!d?.text) throw new Error('Analysis zinciri boş metin döndürdü.');
  addSystemLog(`✓ Gemini kota aşımı → kendi analysis zinciri devraldı (sağlayıcı: ${d.provider}, model: ${d.model}).`, 'success');
  const parsedChain = _parseMaybeTruncatedJson(d.text, 'Analysis zinciri');
  if (!parsedChain) {
    // v1.180: onarılamayan kesik çıktıda ham başlık loglanır — sessiz fallback yok.
    addSystemLog(`Analysis zinciri çıktısı onarılamadı; ham çıktı başı: ${String(d.text).substring(0, 200)}`, 'error');
    throw new Error('Analysis zinciri JSON\'u onarılamayacak biçimde kesik döndürdü.');
  }
  return parsedChain.value;
};
const _callGeminiAndParse = async (url, payload) => {
  payload = _stripJsonConfigForSearch(payload);
  let data;
  try {
    const r = await NetworkUtils.fetchWithRetry(url, { method: 'POST', body: JSON.stringify(payload) });
    if (!r) throw new Error('API yanıt döndürmedi');
    data = await r.json();
  } catch (geminiError) {
    // v1.179: transport/kota kırılması (429 deneme tükenmesi dahil) → sunucu zinciri yedeği.
    try { return await _callAnalysisChainAndParse(payload); }
    catch (chainError) {
      addSystemLog(`Analysis yedek zinciri de başarısız: ${String(chainError?.message || chainError)}`, 'error');
      throw geminiError; // asıl Gemini hatası kaybolmasın
    }
  }
  if (data.candidates?.[0]?.finishReason === "SAFETY") throw new Error("İçerik güvenlik filtresine takıldı.");
  if (!data.candidates?.[0]?.content) throw new Error("Yapay Zeka API boş yanıt döndürdü.");
  let responseText = data.candidates[0].content.parts[0].text;
  responseText = responseText.replace(/`json/gi, '').replace(/`/g, '').trim();
  const jsonStart = responseText.indexOf('{'); const jsonEnd = responseText.lastIndexOf('}');
  if (jsonStart !== -1 && jsonEnd !== -1) responseText = responseText.substring(jsonStart, jsonEnd + 1);
  return JSON.parse(responseText);
};

const _base64ToBlob = (b64, mimeType = 'audio/mpeg') => {
  const raw = b64.includes(',') ? b64.split(',')[1] : b64;
  const byteString = atob(raw);
  const ab = new ArrayBuffer(byteString.length);
  const ia = new Uint8Array(ab);
  for (let i = 0; i < byteString.length; i++) ia[i] = byteString.charCodeAt(i);
  return new Blob([ab], { type: mimeType });
};

const _getLangInstruction = (lang) => {
  const map = { tr: 'TÜRKÇE', en: 'İNGİLİZCE', fr: 'FRANSIZCA', de: 'ALMANCA', es: 'İSPANYOLCA', ar: 'ARAPÇA', ru: 'RUSÇA' };
  return `BÜTÜN SENARYOYU ${map[lang] || 'TÜRKÇE'} YAZACAKSIN.`;
};

const _createTimerWorker = () => {
  const frameInterval = RENDER_CONFIG.TIMER_WORKER_INTERVAL_MS;
  const code = `let interval=null,armed=false,credit=false; self.onmessage=function(e){ if(e.data==='start'){ if(interval) clearInterval(interval); armed=false; credit=false; interval=setInterval(()=>{ if(armed){ armed=false; credit=false; self.postMessage('tick'); } else { credit=true; } }, ${frameInterval}); } else if(e.data==='arm'){ if(credit){ credit=false; self.postMessage('tick'); } else { armed=true; } } else if(e.data==='stop'){ if(interval) clearInterval(interval); interval=null; armed=false; credit=false; } };`;
  return new Worker(ObjectURLManager.create(new Blob([code], { type: 'application/javascript' })));
};

const _createSilentOsc = (audioCtx, audioDest) => {
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  gain.gain.value = 0.001;
  osc.connect(gain); gain.connect(audioDest); osc.start();
  return { osc, gain };
};

const _getFontFamily = (fontStyle) => {
  if (fontStyle === 'classic') return "Georgia, 'Times New Roman', serif";
  if (fontStyle === 'typewriter') return "'Courier New', Courier, monospace";
  return "'Inter', 'Arial Black', Arial, sans-serif";
};


// === WebM → MP4 DÖNÜŞÜM (ffmpeg.wasm @0.11 — GERÇEK SINGLE THREAD) ===
let _ffmpegInstance = null;
let _ffmpegLoadingPromise = null;
let _ffmpegExclusiveTail = Promise.resolve();
let _ffmpegQueueDepth = 0;

const _withFfmpegExclusive = async (label, task) => {
  const previous = _ffmpegExclusiveTail.catch(() => {});
  let release = null;
  const gate = new Promise(resolve => { release = resolve; });
  _ffmpegExclusiveTail = previous.then(() => gate);
  _ffmpegQueueDepth += 1;
  if (_ffmpegQueueDepth > 1) addSystemLog(`FFmpeg kuyruğu: ${label} bekliyor (${_ffmpegQueueDepth - 1} iş önde).`, 'info');
  await previous;
  try {
    return await task();
  } finally {
    _ffmpegQueueDepth = Math.max(0, _ffmpegQueueDepth - 1);
    try { release(); } catch (e) { ErrorHandler.silent(e); }
  }
};

// v1.120: ffmpeg.wasm 0.11 çekirdeği ana iş parçacığında SENKRON çalışır ve tüm dönüşüm boyunca ekranı kilitler.
// Aynı çekirdeği bir Web Worker içinde çalıştırır; ana ekran akıcı kalır. Worker başlatılamazsa eski moda döner.
const _FFMPEG_WORKER_SOURCE = [
  "var ff = null;",
  "self.onmessage = async function (e) {",
  "  var m = e.data || {}; var id = m.id; var a = m.a || {};",
  "  var reply = function (ok, extra, transfer) { var out = { id: id, ok: ok }; for (var k in (extra || {})) out[k] = extra[k]; self.postMessage(out, transfer || []); };",
  "  try {",
  "    if (m.op === 'init') {",
  "      importScripts(a.wrapperUrl);",
  "      ff = self.FFmpeg.createFFmpeg({ log: false, mainName: 'main', corePath: a.corePath });",
  "      ff.setProgress(function (p) { self.postMessage({ evt: 'progress', ratio: p && p.ratio }); });",
  "      await ff.load(); reply(true);",
  "    } else if (m.op === 'writeFile') { ff.FS('writeFile', a.name, new Uint8Array(a.data)); reply(true); }",
  "    else if (m.op === 'readFile') { var d = ff.FS('readFile', a.name); var copy = d.slice(0); reply(true, { data: copy.buffer }, [copy.buffer]); }",
  "    else if (m.op === 'unlink') { ff.FS('unlink', a.name); reply(true); }",
  "    else if (m.op === 'run') { await ff.run.apply(ff, a.args); reply(true); }",
  "    else if (m.op === 'exit') { try { ff.exit(); } catch (x) {} reply(true); }",
  "    else { reply(false, { error: 'Bilinmeyen işlem: ' + m.op }); }",
  "  } catch (err) { reply(false, { error: String((err && err.message) || err) }); }",
  "};"
].join('\n');

const _createFfmpegWorkerClient = (wrapperUrl, corePath) => {
  const sourceUrl = URL.createObjectURL(new Blob([_FFMPEG_WORKER_SOURCE], { type: 'text/javascript' }));
  const worker = new Worker(sourceUrl);
  const pending = new Map();
  let nextId = 1;
  let dead = false;
  let progressCb = null;
  const rejectAll = (error) => { pending.forEach(entry => { try { entry.reject(error); } catch (e) { ErrorHandler.silent(e); } }); pending.clear(); };
  worker.onmessage = (event) => {
    const m = event.data || {};
    if (m.evt === 'progress') { try { if (progressCb) progressCb({ ratio: m.ratio }); } catch (e) { ErrorHandler.silent(e); } return; }
    const entry = pending.get(m.id);
    if (!entry) return;
    pending.delete(m.id);
    if (m.ok) entry.resolve(m); else entry.reject(new Error(m.error || 'FFmpeg worker hatası'));
  };
  worker.onerror = (event) => { dead = true; rejectAll(new Error(`FFmpeg worker hatası: ${event?.message || 'bilinmiyor'}`)); };
  const call = (op, a = {}, transfer = []) => new Promise((resolve, reject) => {
    if (dead) { reject(new Error('FFmpeg worker kapalı.')); return; }
    const id = nextId++;
    pending.set(id, { resolve, reject });
    try { worker.postMessage({ id, op, a }, transfer); } catch (e) { pending.delete(id); reject(e); }
  });
  return {
    isWorker: true,
    load: () => call('init', { wrapperUrl, corePath }),
    setProgress: (callback) => { progressCb = callback; },
    run: (...args) => call('run', { args }),
    FS: async (op, ...rest) => {
      if (op === 'writeFile') {
        const [name, data] = rest;
        const bytes = data instanceof Uint8Array ? data : new Uint8Array(data);
        const exact = (bytes.byteOffset === 0 && bytes.byteLength === bytes.buffer.byteLength) ? bytes.buffer : bytes.slice().buffer;
        await call('writeFile', { name, data: exact }, [exact]);
        return undefined;
      }
      if (op === 'readFile') { const m = await call('readFile', { name: rest[0] }); return new Uint8Array(m.data); }
      if (op === 'unlink') { await call('unlink', { name: rest[0] }); return undefined; }
      throw new Error(`Desteklenmeyen FFmpeg FS işlemi: ${op}`);
    },
    exit: () => {
      if (dead) return;
      dead = true;
      try { worker.postMessage({ id: 0, op: 'exit', a: {} }); } catch (e) { ErrorHandler.silent(e); }
      rejectAll(new Error('FFmpeg worker kapatıldı.'));
      setTimeout(() => { try { worker.terminate(); } catch (e) { ErrorHandler.silent(e); } try { URL.revokeObjectURL(sourceUrl); } catch (e) { ErrorHandler.silent(e); } }, 250);
    }
  };
};

const _readFfmpegOutputBlob = async (ffmpeg, outputName) => {
  const data = await ffmpeg.FS('readFile', outputName);
  if (!data || !data.length) throw new Error('FFmpeg çıktı dosyası boş.');
  // data.buffer yerine tam byte aralığının kopyasını kullan. MEMFS kapasite/artık byte
  // riskinin Blob içine taşınmasını kesin olarak engeller.
  const exactBytes = typeof data.slice === 'function' ? data.slice(0) : new Uint8Array(data);
  return new Blob([exactBytes], { type: 'video/mp4' });
};

const _discardFfmpegRuntime = () => {
  const current = _ffmpegInstance;
  _ffmpegInstance = null;
  _ffmpegLoadingPromise = null;
  try {
    if (current?.ffmpeg && typeof current.ffmpeg.exit === 'function') current.ffmpeg.exit();
  } catch (e) {
    ErrorHandler.silent(e);
  }
};

const _runFfmpegCommand = async (ffmpeg, outputName, ...args) => {
  try {
    await ffmpeg.run(...args);
  } catch (e) {
    // v1.107: ffmpeg.wasm 0.11 `running` bayrağını yalnız 'FFMPEG_END' logunda veya exit() içinde
    // sıfırlar. Çekirdek 'Program terminated with exit(0)' fırlatırsa bayrak true kalır ve AYNI
    // örnekteki sonraki run() "can only run one command at a time" ile reddedilir (log'daki dönüşümlü
    // hata). Bu yüzden her istisna sonrası örnek işaretlenir; bir sonraki yüklemede temiz açılır.
    if (_ffmpegInstance) _ffmpegInstance.needsFreshStart = true;
    const msg = String(e?.message || e);
    if (/Program terminated with exit\(0\)/i.test(msg)) {
      // v1.59: exit(0) artık yalnız "dosya var" diye başarı değildir.
      // Çıktı MP4 fiziksel olarak parse edilebilir değilse hata olarak ele alınır ve
      // üst katman temiz FFmpeg runtime ile yeniden encode eder.
      try {
        const probeBlob = await _readFfmpegOutputBlob(ffmpeg, outputName);
        await _inspectMp4Container(probeBlob);
        await _verifyInstagramCfrMp4(probeBlob);
        addSystemLog('FFmpeg exit(0) döndürdü; çıktı fiziksel MP4 + 30 CFR doğrulamasını geçtiği için başarı kabul edildi.', 'info');
        return;
      } catch (probeErr) {
        throw new Error(`FFmpeg exit(0) fakat çıktı geçersiz: ${probeErr.message}`);
      }
    }
    throw e;
  }
};

const _loadScript = (src) => new Promise((resolve, reject) => {
  if (document.querySelector('script[src="' + src + '"]')) return resolve();

  const s = document.createElement('script');
  s.src = src;
  s.async = true;
  s.crossOrigin = 'anonymous';
  s.onload = () => resolve();
  s.onerror = () => reject(new Error('Script yüklenemedi: ' + src));
  document.head.appendChild(s);
});

const _loadFFmpeg = async () => {
  if (_ffmpegInstance?.needsFreshStart) {
    addSystemLog('FFmpeg önceki işlemden takılı durum bırakmış olabilir; temiz çalışma zamanıyla başlatılıyor.', 'info');
    _discardFfmpegRuntime();
  }
  if (_ffmpegInstance) return _ffmpegInstance;
  if (_ffmpegLoadingPromise) return _ffmpegLoadingPromise;

  _ffmpegLoadingPromise = (async () => {
    const wrapperUrl = 'https://unpkg.com/@ffmpeg/ffmpeg@0.11.6/dist/ffmpeg.min.js';
    const singleThreadCoreUrl = 'https://unpkg.com/@ffmpeg/core-st@0.11.1/dist/ffmpeg-core.js';

    addSystemLog(
      `Instagram CFR motoru yükleniyor: ffmpeg.wasm single-thread (SharedArrayBuffer gerektirmez). crossOriginIsolated=${String(window.crossOriginIsolated === true)}`,
      'info'
    );

    // v1.120: Önce Web Worker (ekran donmaz). Başarısızsa eski ana iş parçacığı moduna dön.
    // v1.124: Worker modu gerçek tarayıcıda boş MP4 çıktısı verdi; varsayılan KAPALI. (Deneysel: localStorage otonom_ffmpeg_worker=1)
    if (typeof Worker !== 'undefined' && !window.__otonomFfmpegNoWorker && SafeStorage.getItem('otonom_ffmpeg_worker') === '1') {
      let client = null;
      try {
        client = _createFfmpegWorkerClient(wrapperUrl, singleThreadCoreUrl);
        await Promise.race([client.load(), new Promise((_, reject) => setTimeout(() => reject(new Error('worker yükleme zaman aşımı (60 sn)')), 60000))]);
        // Sağlık testi: bayt gidiş-dönüşü doğrulanmadan worker'a güvenilmez.
        await client.FS('writeFile', '__probe.bin', new Uint8Array([7, 1, 2, 3]));
        const echoed = await client.FS('readFile', '__probe.bin');
        await client.FS('unlink', '__probe.bin');
        if (!echoed || echoed.length !== 4 || echoed[0] !== 7) throw new Error('worker bayt gidiş-dönüşü başarısız');
        _ffmpegInstance = {
          ffmpeg: client,
          fetchFile: async (source) => new Uint8Array(await (source instanceof Blob ? source : new Blob([source])).arrayBuffer()),
          coreMode: 'single-thread-worker',
          coreVersion: '@ffmpeg/core-st@0.11.1 (Web Worker)'
        };
        addSystemLog('✓ v1.120: FFmpeg arka plan işçisinde çalışıyor; dönüşüm sırasında ekran donmaz.', 'success');
        return _ffmpegInstance;
      } catch (workerError) {
        try { client?.exit(); } catch (e) { ErrorHandler.silent(e); }
        window.__otonomFfmpegNoWorker = true;
        addSystemLog(`FFmpeg arka plan işçisi başlatılamadı (${String(workerError?.message || workerError)}); ana iş parçacığı moduna dönüldü, dönüşüm sırasında ekran kısa süre donabilir.`, 'warn');
      }
    }

    await _loadScript(wrapperUrl);

    const FFmpegLib = window.FFmpeg;
    if (!FFmpegLib || !FFmpegLib.createFFmpeg || !FFmpegLib.fetchFile) {
      throw new Error('ffmpeg.wasm wrapper yüklenemedi.');
    }

    // KRİTİK v1.40:
    // @ffmpeg/core-st gerçek single-thread build'dir.
    // mainName:'main' 0.11.x dokümantasyonunun single-thread kullanım şartıdır.
    // SharedArrayBuffer / COOP / COEP gerekmez.
    const ffmpeg = FFmpegLib.createFFmpeg({
      log: false,
      mainName: 'main',
      corePath: singleThreadCoreUrl
    });

    try {
      await ffmpeg.load();
    } catch (e) {
      const msg = String(e?.message || e);

      if (/SharedArrayBuffer/i.test(msg)) {
        throw new Error(
          'Single-thread FFmpeg yüklenirken beklenmeyen SharedArrayBuffer isteği oluştu. ' +
          'Multi-thread çekirdeğin cache’de kalmış olma ihtimali var; sayfayı Ctrl+Shift+R ile yenileyin. ' +
          `Asıl hata: ${msg}`
        );
      }

      throw e;
    }

    _ffmpegInstance = {
      ffmpeg,
      fetchFile: FFmpegLib.fetchFile,
      coreMode: 'single-thread',
      coreVersion: '@ffmpeg/core-st@0.11.1'
    };

    addSystemLog(
      '✓ FIX CHECKLIST v1.40: FFmpeg gerçek single-thread core-st yüklendi; SharedArrayBuffer bağımlılığı yok.',
      'success'
    );

    return _ffmpegInstance;
  })();

  try {
    return await _ffmpegLoadingPromise;
  } finally {
    _ffmpegLoadingPromise = null;
  }
};
const _readMp4Box = (view, offset, limit) => {
  if (offset + 8 > limit) return null;
  let size = view.getUint32(offset, false);
  const type = String.fromCharCode(
    view.getUint8(offset + 4),
    view.getUint8(offset + 5),
    view.getUint8(offset + 6),
    view.getUint8(offset + 7)
  );
  let headerSize = 8;

  if (size === 1) {
    if (offset + 16 > limit) return null;
    const hi = view.getUint32(offset + 8, false);
    const lo = view.getUint32(offset + 12, false);
    size = hi * 4294967296 + lo;
    headerSize = 16;
  } else if (size === 0) {
    size = limit - offset;
  }

  if (!Number.isFinite(size) || size < headerSize || offset + size > limit) return null;
  return {
    type,
    start: offset,
    size,
    dataStart: offset + headerSize,
    end: offset + size
  };
};

const _findMp4Children = (view, start, end, wantedType = null) => {
  const found = [];
  let offset = start;
  while (offset + 8 <= end) {
    const box = _readMp4Box(view, offset, end);
    if (!box) break;
    if (!wantedType || box.type === wantedType) found.push(box);
    offset = box.end;
  }
  return found;
};

const _findMp4Child = (view, parent, type) =>
  _findMp4Children(view, parent.dataStart, parent.end, type)[0] || null;

// === v1.59 MP4 FİZİKSEL KONTEYNER DOĞRULAMA ===
// Amaç: FFmpeg log/metin byte'ları MP4'ün başına veya kutuların arasına karışmışsa
// FPS tablosuna gelmeden dosyayı kesin olarak reddetmek. Canonical final dosya ilk
// byte'ta ftyp ile başlamalı; kutular sıfırdan EOF'a kesintisiz yürümeli; mdat + moov olmalı.
const _inspectMp4Container = async (blob) => {
  if (!(blob instanceof Blob) || blob.size < 32) {
    throw new Error('MP4 yapı doğrulama: dosya boş veya çok küçük.');
  }

  const buffer = await blob.arrayBuffer();
  const view = new DataView(buffer);
  const boxes = [];
  let offset = 0;

  while (offset + 8 <= buffer.byteLength) {
    const box = _readMp4Box(view, offset, buffer.byteLength);
    if (!box) {
      throw new Error(`MP4 yapı doğrulama: ${offset}. byte konumunda geçersiz/kırık kutu.`);
    }
    boxes.push({ type: box.type, start: box.start, size: box.size, end: box.end });
    offset = box.end;
  }

  if (offset !== buffer.byteLength) {
    throw new Error(`MP4 yapı doğrulama: sonda ${buffer.byteLength - offset} byte artık/veri bulundu.`);
  }
  if (!boxes.length || boxes[0].start !== 0 || boxes[0].type !== 'ftyp') {
    const first = boxes[0]?.type || 'yok';
    throw new Error(`MP4 yapı doğrulama: dosya 0. byte'ta ftyp ile başlamıyor (ilk=${first}).`);
  }

  const ftyp = boxes.find(b => b.type === 'ftyp');
  const mdat = boxes.find(b => b.type === 'mdat');
  const moov = boxes.find(b => b.type === 'moov');
  if (!ftyp) throw new Error('MP4 yapı doğrulama: ftyp bulunamadı.');
  if (!mdat || mdat.size <= 16) throw new Error('MP4 yapı doğrulama: mdat yok veya boş.');
  if (!moov || moov.size <= 16) throw new Error('MP4 yapı doğrulama: moov yok veya boş.');

  return {
    ok: true,
    size: buffer.byteLength,
    boxes,
    ftypOffset: ftyp.start,
    mdatOffset: mdat.start,
    moovOffset: moov.start
  };
};

// === v1.67 MP4 VIDEO TRACK t=0 GAP GUARD ===
// Bazı galeri/liste thumbnail üreticileri yalnız tam t=0 karesini okur.
// Video track'in başında empty edit varsa (ör. 21ms), dosyanın ilk gerçek karesi görünür
// olsa bile liste thumbnail'i siyah olabilir. Bu fonksiyon video track'in elst başlangıç
// boşluğunu fiziksel MP4 kutularından ölçer.
const _inspectMp4VideoStartGap = async (blob) => {
  if (!(blob instanceof Blob) || !blob.size) throw new Error('MP4 t=0 kontrolü: kaynak boş.');
  const buffer = await blob.arrayBuffer();
  const view = new DataView(buffer);
  const root = { dataStart: 0, end: buffer.byteLength };
  const moov = _findMp4Children(view, root.dataStart, root.end, 'moov')[0];
  if (!moov) throw new Error('MP4 t=0 kontrolü: moov bulunamadı.');

  const mvhd = _findMp4Child(view, moov, 'mvhd');
  if (!mvhd) throw new Error('MP4 t=0 kontrolü: mvhd bulunamadı.');
  const mvhdVersion = view.getUint8(mvhd.dataStart);
  const movieTimescaleOffset = mvhdVersion === 1 ? mvhd.dataStart + 20 : mvhd.dataStart + 12;
  if (movieTimescaleOffset + 4 > mvhd.end) throw new Error('MP4 t=0 kontrolü: movie timescale okunamadı.');
  const movieTimescale = view.getUint32(movieTimescaleOffset, false);
  if (!movieTimescale) throw new Error('MP4 t=0 kontrolü: movie timescale geçersiz.');

  const readInt64 = (offset) => {
    const hi = view.getInt32(offset, false);
    const lo = view.getUint32(offset + 4, false);
    return hi * 4294967296 + lo;
  };
  const readUint64 = (offset) => {
    const hi = view.getUint32(offset, false);
    const lo = view.getUint32(offset + 4, false);
    return hi * 4294967296 + lo;
  };

  const traks = _findMp4Children(view, moov.dataStart, moov.end, 'trak');
  for (const trak of traks) {
    const mdia = _findMp4Child(view, trak, 'mdia');
    if (!mdia) continue;
    const hdlr = _findMp4Child(view, mdia, 'hdlr');
    if (!hdlr || hdlr.dataStart + 12 > hdlr.end) continue;
    const handler = String.fromCharCode(
      view.getUint8(hdlr.dataStart + 8), view.getUint8(hdlr.dataStart + 9),
      view.getUint8(hdlr.dataStart + 10), view.getUint8(hdlr.dataStart + 11)
    );
    if (handler !== 'vide') continue;

    const edts = _findMp4Child(view, trak, 'edts');
    const elst = edts ? _findMp4Child(view, edts, 'elst') : null;
    if (!elst) return { ok: true, startGapSec: 0, emptyEditDurationUnits: 0, movieTimescale, hasEditList: false };

    const version = view.getUint8(elst.dataStart);
    const entryCountOffset = elst.dataStart + 4;
    if (entryCountOffset + 4 > elst.end) throw new Error('MP4 t=0 kontrolü: elst entry_count okunamadı.');
    const entryCount = view.getUint32(entryCountOffset, false);
    let cursor = elst.dataStart + 8;
    let emptyDurationUnits = 0;

    for (let i = 0; i < entryCount; i++) {
      let segmentDuration;
      let mediaTime;
      if (version === 1) {
        if (cursor + 20 > elst.end) throw new Error('MP4 t=0 kontrolü: elst v1 eksik.');
        segmentDuration = readUint64(cursor);
        mediaTime = readInt64(cursor + 8);
        cursor += 20;
      } else {
        if (cursor + 12 > elst.end) throw new Error('MP4 t=0 kontrolü: elst v0 eksik.');
        segmentDuration = view.getUint32(cursor, false);
        mediaTime = view.getInt32(cursor + 4, false);
        cursor += 12;
      }
      if (mediaTime === -1) {
        emptyDurationUnits += segmentDuration;
        continue;
      }
      break;
    }

    const startGapSec = emptyDurationUnits / movieTimescale;
    return {
      ok: startGapSec <= 0.0005,
      startGapSec,
      emptyEditDurationUnits: emptyDurationUnits,
      movieTimescale,
      hasEditList: true
    };
  }
  throw new Error('MP4 t=0 kontrolü: video track bulunamadı.');
};

const _isTransientLeadInVerifierFailure = (leadIn) => {
  const reason = String(leadIn?.reason || '').toLowerCase();
  return reason === 'first-frame-timeout' ||
    reason === 'decoder-timeout' ||
    reason === 'first-frame-decode' ||
    reason === 'decode-error';
};

const _verifyFinalMp4LeadInWithoutFalseTimeout = async (blob) => {
  let leadIn = await _inspectVideoBlobFirstFrame(blob, 10000);
  if (leadIn?.ok) return { leadIn, verifierBypass: false };

  if (!_isTransientLeadInVerifierFailure(leadIn)) {
    // Gerçek decoded dark sonucu burada korunur; asla bypass edilmez.
    return { leadIn, verifierBypass: false };
  }

  addSystemLog(
    `v1.74 MP4 LEAD-IN VERIFY: tarayıcı decoder doğrulaması ${leadIn.reason}; ana thread serbest bırakılıp bir kez daha deneniyor.`,
    'warn'
  );
  await _cooperativeMainThreadYield();
  await _sleep(180);

  const retry = await _inspectVideoBlobFirstFrame(blob, 16000);
  if (retry?.ok) return { leadIn: retry, verifierBypass: false };
  if (!_isTransientLeadInVerifierFailure(retry)) return { leadIn: retry, verifierBypass: false };

  // İki decoder denemesi de yalnız timeout/decode altyapı hatası verdiyse bunu siyah kare
  // diye yorumlamayız. Bu noktaya gelmeden MP4 konteyneri, gerçek CFR ve t=0 zaten doğrulanır.
  return { leadIn: retry, verifierBypass: true };
};

const _assertFinalMp4SafeForWrite = async (blob) => {
  const structure = await _inspectMp4Container(blob);
  const cfr = await _verifyInstagramCfrMp4(blob);
  const fps = Number(cfr?.fps || 0);
  const minFps = Number(RENDER_CONFIG.MIN_OUTPUT_FPS || 23);
  const targetFps = Number(RENDER_CONFIG.TARGET_CFR_FPS || 30);

  if (!cfr?.ok || !Number.isFinite(fps) || fps < minFps || fps > 60) {
    throw new Error(`Final MP4 güvenlik kapısı: FPS geçersiz (${fps || 0}).`);
  }
  if (Math.abs(fps - targetFps) > 0.02) {
    throw new Error(`Final MP4 güvenlik kapısı: hedef ${targetFps} CFR değil (${fps.toFixed(3)} FPS).`);
  }

  const startGap = await _inspectMp4VideoStartGap(blob);
  if (!startGap?.ok || Number(startGap.startGapSec || 0) > 0.0005) {
    throw new Error(`Final MP4 güvenlik kapısı: video track t=0'da başlamıyor (${(Number(startGap?.startGapSec || 0) * 1000).toFixed(1)}ms boşluk).`);
  }

  const leadInResult = await _verifyFinalMp4LeadInWithoutFalseTimeout(blob);
  const leadIn = leadInResult.leadIn;
  if (!leadIn?.ok && !leadInResult.verifierBypass) {
    throw new Error(`Final MP4 güvenlik kapısı: ilk ${Number(RENDER_CONFIG.BLACK_FRAME_LEADIN_SEC || 1.20).toFixed(2)}sn görünür içerik doğrulanamadı (${leadIn?.reason || 'dark'}).`);
  }

  if (leadInResult.verifierBypass) {
    addSystemLog(
      `✓ v1.74 FINAL MP4 GATE: yapı sağlam, ${fps.toFixed(3)} FPS CFR, video t=0.000sn. Görsel decoder iki kez timeout verdi; bu durum siyah kare sayılmadı ve fiziksel kapak/CFR zinciri korunarak yazma serbest bırakıldı.`,
      'warn'
    );
  } else {
    addSystemLog(
      `✓ v1.74 FINAL MP4 GATE: yapı sağlam, ${fps.toFixed(3)} FPS CFR, video t=0.000sn, ilk görünür kare ${leadIn?.firstVisibleTimeSec != null ? leadIn.firstVisibleTimeSec.toFixed(2) + 'sn' : 'anında'}; diske yazma serbest.`,
      'success'
    );
  }
  const proof = { ok: true, fps, structure, cfr, startGap, leadIn, leadInVerifierBypass: !!leadInResult.verifierBypass };
  // Yalnız gerçekten decode edilip görünür kare bulunan dosya için yeniden kullan.
  // Timeout bypass'ı sonraki kayıtta tekrar incelenir; farklı Blob hiçbir zaman geçmez.
  if (leadIn?.ok) _finalMp4ProofByBlob.set(blob, proof);
  return proof;
};

const _verifyInstagramCfrMp4 = async (blob) => {
  const buffer = await blob.arrayBuffer();
  const view = new DataView(buffer);
  const root = { dataStart: 0, end: buffer.byteLength };

  const moov = _findMp4Children(view, root.dataStart, root.end, 'moov')[0];
  if (!moov) throw new Error('CFR doğrulama: MP4 moov kutusu bulunamadı.');

  const traks = _findMp4Children(view, moov.dataStart, moov.end, 'trak');
  for (const trak of traks) {
    const mdia = _findMp4Child(view, trak, 'mdia');
    if (!mdia) continue;

    const hdlr = _findMp4Child(view, mdia, 'hdlr');
    if (!hdlr || hdlr.dataStart + 12 > hdlr.end) continue;
    const handler = String.fromCharCode(
      view.getUint8(hdlr.dataStart + 8),
      view.getUint8(hdlr.dataStart + 9),
      view.getUint8(hdlr.dataStart + 10),
      view.getUint8(hdlr.dataStart + 11)
    );
    if (handler !== 'vide') continue;

    const mdhd = _findMp4Child(view, mdia, 'mdhd');
    if (!mdhd) throw new Error('CFR doğrulama: video mdhd bulunamadı.');

    const mdhdVersion = view.getUint8(mdhd.dataStart);
    const timescaleOffset = mdhdVersion === 1 ? mdhd.dataStart + 20 : mdhd.dataStart + 12;
    if (timescaleOffset + 4 > mdhd.end) throw new Error('CFR doğrulama: timescale okunamadı.');
    const timescale = view.getUint32(timescaleOffset, false);
    if (!timescale) throw new Error('CFR doğrulama: timescale geçersiz.');

    const minf = _findMp4Child(view, mdia, 'minf');
    const stbl = minf ? _findMp4Child(view, minf, 'stbl') : null;
    const stts = stbl ? _findMp4Child(view, stbl, 'stts') : null;
    if (!stts || stts.dataStart + 8 > stts.end) {
      throw new Error('CFR doğrulama: stts zaman tablosu bulunamadı.');
    }

    const entryCount = view.getUint32(stts.dataStart + 4, false);
    if (!entryCount) throw new Error('CFR doğrulama: kare zaman tablosu boş.');

    let firstDelta = null;
    let totalSamples = 0;
    let cursor = stts.dataStart + 8;

    for (let i = 0; i < entryCount; i++) {
      if (cursor + 8 > stts.end) throw new Error('CFR doğrulama: stts tablosu eksik.');
      const sampleCount = view.getUint32(cursor, false);
      const sampleDelta = view.getUint32(cursor + 4, false);
      cursor += 8;

      if (!sampleCount || !sampleDelta) throw new Error('CFR doğrulama: geçersiz kare süresi.');
      if (firstDelta === null) firstDelta = sampleDelta;
      if (sampleDelta !== firstDelta) {
        throw new Error(`CFR doğrulama: değişken kare süresi bulundu (${firstDelta}/${sampleDelta}).`);
      }
      totalSamples += sampleCount;
    }

    const fps = timescale / firstDelta;
    if (!(fps >= 23 && fps <= 60)) {
      throw new Error(`CFR doğrulama: Instagram dışı FPS (${fps.toFixed(3)}).`);
    }

    if (Math.abs(fps - 30) > 0.02) {
      throw new Error(`CFR doğrulama: hedef 30 FPS değil (${fps.toFixed(3)}).`);
    }

    return {
      ok: true,
      fps,
      timescale,
      sampleDelta: firstDelta,
      totalSamples,
      sttsEntries: entryCount
    };
  }

  throw new Error('CFR doğrulama: video track bulunamadı.');
};

// === v1.55 HAFİF MP4 FPS İNCELEYİCİ ===
// Otomatik yerel MP4 kaydında kullanılır. Render hedefi 30 FPS olarak kalır;
// ancak Chrome native MP4 zaten efektif 23-60 FPS ise sırf 30.000'e yeniden kodlanmaz.
// Buffer/Instagram'ın mevcut exact-30 CFR guard'ına dokunulmaz.
const _inspectMp4EffectiveFps = async (blob) => {
  const buffer = await blob.arrayBuffer();
  const view = new DataView(buffer);
  const root = { dataStart: 0, end: buffer.byteLength };
  const moov = _findMp4Children(view, root.dataStart, root.end, 'moov')[0];
  if (!moov) throw new Error('MP4 FPS inceleme: moov bulunamadı.');

  const traks = _findMp4Children(view, moov.dataStart, moov.end, 'trak');
  for (const trak of traks) {
    const mdia = _findMp4Child(view, trak, 'mdia');
    if (!mdia) continue;
    const hdlr = _findMp4Child(view, mdia, 'hdlr');
    if (!hdlr || hdlr.dataStart + 12 > hdlr.end) continue;
    const handler = String.fromCharCode(
      view.getUint8(hdlr.dataStart + 8), view.getUint8(hdlr.dataStart + 9),
      view.getUint8(hdlr.dataStart + 10), view.getUint8(hdlr.dataStart + 11)
    );
    if (handler !== 'vide') continue;

    const mdhd = _findMp4Child(view, mdia, 'mdhd');
    if (!mdhd) throw new Error('MP4 FPS inceleme: mdhd bulunamadı.');
    const version = view.getUint8(mdhd.dataStart);
    const timescaleOffset = version === 1 ? mdhd.dataStart + 20 : mdhd.dataStart + 12;
    if (timescaleOffset + 4 > mdhd.end) throw new Error('MP4 FPS inceleme: timescale okunamadı.');
    const timescale = view.getUint32(timescaleOffset, false);
    if (!timescale) throw new Error('MP4 FPS inceleme: timescale geçersiz.');

    const minf = _findMp4Child(view, mdia, 'minf');
    const stbl = minf ? _findMp4Child(view, minf, 'stbl') : null;
    const stts = stbl ? _findMp4Child(view, stbl, 'stts') : null;
    if (!stts || stts.dataStart + 8 > stts.end) throw new Error('MP4 FPS inceleme: stts bulunamadı.');

    const entryCount = view.getUint32(stts.dataStart + 4, false);
    if (!entryCount) throw new Error('MP4 FPS inceleme: kare tablosu boş.');
    let cursor = stts.dataStart + 8;
    let totalSamples = 0;
    let totalDurationUnits = 0;
    let firstDelta = null;
    let isCfr = true;
    let minInstantFps = Infinity;
    let maxInstantFps = 0;

    for (let i = 0; i < entryCount; i++) {
      if (cursor + 8 > stts.end) throw new Error('MP4 FPS inceleme: stts eksik.');
      const sampleCount = view.getUint32(cursor, false);
      const sampleDelta = view.getUint32(cursor + 4, false);
      cursor += 8;
      if (!sampleCount || !sampleDelta) throw new Error('MP4 FPS inceleme: geçersiz kare süresi.');
      if (firstDelta === null) firstDelta = sampleDelta;
      else if (sampleDelta !== firstDelta) isCfr = false;
      totalSamples += sampleCount;
      totalDurationUnits += sampleCount * sampleDelta;
      const instant = timescale / sampleDelta;
      minInstantFps = Math.min(minInstantFps, instant);
      maxInstantFps = Math.max(maxInstantFps, instant);
    }

    const fps = totalDurationUnits > 0 ? (totalSamples * timescale / totalDurationUnits) : 0;
    return { ok: Number.isFinite(fps) && fps > 0, fps, isCfr, minInstantFps, maxInstantFps, timescale, totalSamples, sttsEntries: entryCount };
  }
  throw new Error('MP4 FPS inceleme: video track bulunamadı.');
};

const _convertWebMtoMP4Unlocked = async (webmBlob, onProgress, firstFrameCoverBlob = null, strategy = 1) => {
  const ffmpegRuntime = await _loadFFmpeg();
  const { ffmpeg, fetchFile } = ffmpegRuntime;
  // v1.171: strateji >= 3 kapak bindirmesini (filter_complex) kullanmaz; render zaten kapak karelerini çizmiştir.
  if (strategy >= 3) firstFrameCoverBlob = null;
  const ffmpegLogTail = [];
  try {
    if (typeof ffmpeg.setLogger === 'function') {
      ffmpeg.setLogger(({ message }) => { if (message) { ffmpegLogTail.push(String(message).slice(0, 220)); if (ffmpegLogTail.length > 14) ffmpegLogTail.shift(); } });
    }
  } catch (e) { ErrorHandler.silent(e); }

  addSystemLog(
    `CFR runtime: ${ffmpegRuntime.coreVersion || 'single-thread'} / threads=1 / SharedArrayBuffer=${typeof SharedArrayBuffer !== 'undefined' ? 'var' : 'yok-gerekmez'}`,
    'info'
  );

  if (onProgress) {
    ffmpeg.setProgress(({ ratio }) => {
      if (ratio > 0 && ratio <= 1) onProgress(Math.round(ratio * 100));
    });
  }

  const stamp = `${Date.now()}_${Math.random().toString(36).slice(2)}`;
  const inputName = `input_${stamp}.bin`;
  const outputName = `output_${stamp}.mp4`;
  const coverName = `cover_${stamp}.jpg`;

  try {
    await ffmpeg.FS('writeFile', inputName, await fetchFile(webmBlob));
    if (firstFrameCoverBlob) {
      await ffmpeg.FS('writeFile', coverName, await fetchFile(firstFrameCoverBlob));
    }

    // INSTAGRAM KALICI CFR + A/V SENKRON KURALI:
    // 1) fps=30, kaynak zaman çizelgesini koruyarak eksik kareleri çoğaltır / fazla kareleri düşürür.
    // 2) setpts=PTS-STARTPTS yalnız başlangıcı sıfırlar; video süresini yeniden hesaplamaz.
    // 3) -r 30 + -vsync cfr muxer/encoder çıkışını 30 CFR'a zorlar.
    // 4) video_track_timescale=30000 => MP4 stts delta=1000, yani tam 30.000 FPS.
    // 5) Çıktı MP4'ü JS içinde stts/mdhd üzerinden doğrulanmadan geri dönmez.
    // 6) v1.67: -avoid_negative_ts make_zero KULLANILMAZ. AAC encoder priming'in normal negatif
    //    paketini sıfırlamak tüm timeline'ı +~21ms kaydırıp video track'e empty edit ekliyordu;
    //    bazı galeri/liste thumbnail üreticileri t=0'da bu yüzden siyah gösteriyordu.
    // v1.30: N/(30*TB) KULLANILMAZ; manuel captureStream kare sayısı video süresini kısaltamaz.
    // v1.170: Render'ın ölçtüğü gerçek süre bu webm'e aitse çıktıyı o süreye kilitle.
    const pendingEnd = _pendingRenderTrueEnd;
    const hardEndSec = (strategy === 1 && pendingEnd && Number(pendingEnd.size) === Number(webmBlob?.size) && Number(pendingEnd.sec) > 3 && Number(pendingEnd.sec) < 900)
      ? Number(pendingEnd.sec) + 0.25 : null;
    if (hardEndSec) addSystemLog(`MP4 SÜRE KİLİDİ v1.170: çıktı ${hardEndSec.toFixed(2)} sn ile sınırlandı; Son Söz sonrası müzik/donmuş kare kuyruğu kesilecek.`, 'info');
    const audioFilter = strategy >= 4 ? null : 'aresample=async=1:first_pts=0,asetpts=PTS-STARTPTS' +
      (hardEndSec ? `,afade=t=out:st=${Math.max(0, hardEndSec - 0.45).toFixed(3)}:d=0.40` : '');
    const baseVideoArgs = [
      '-r', '30',
      '-vsync', 'cfr',
      '-threads', '1',
      '-c:v', 'libx264',
      '-preset', 'ultrafast',
      '-profile:v', 'high',
      '-level:v', '4.1',
      '-pix_fmt', 'yuv420p',
      '-g', '60',
      '-keyint_min', '60',
      '-sc_threshold', '0',
      '-video_track_timescale', '30000',
      ...(audioFilter ? ['-af', audioFilter] : []),
      '-c:a', 'aac',
      '-ar', '48000',
      '-ac', '2',
      '-b:a', '128k',
      // v1.162: Ses paketi/video süresi saparsa çıktı en kısa A/V akışında bitsin.
      '-shortest',
      ...(hardEndSec ? ['-t', hardEndSec.toFixed(3)] : []),
    ];

    if (firstFrameCoverBlob) {
      // BLACK-FIRST-FRAME REGRESSION GUARD:
      // Gerçek render edilmiş clickbait kapağını ilk 0.80 saniye videonun üzerine bindir.
      // Bu, MediaRecorder/decoder t=0'da siyah kare üretse bile Instagram/TikTok ilk
      // thumbnail karesinin siyah olmasını engeller.
      await _runFfmpegCommand(ffmpeg, outputName,
        '-hide_banner', '-loglevel', 'error', '-nostats',
        '-fflags', '+genpts',
        '-i', inputName,
        '-loop', '1',
        '-framerate', '30',
        '-i', coverName,
        '-filter_complex',
        "[0:v]fps=30,setpts=PTS-STARTPTS,scale=trunc(iw/2)*2:trunc(ih/2)*2[base];" +
        "[1:v]setpts=PTS-STARTPTS[cover0];" +
        "[cover0][base]scale2ref=w=main_w:h=main_h[cover][base2];" +
        "[base2][cover]overlay=0:0:enable='lte(t,1.20)':eof_action=pass[v]",
        '-map', '[v]',
        '-map', '0:a?',
        ...baseVideoArgs,
        outputName
      );
    } else {
      await _runFfmpegCommand(ffmpeg, outputName,
        '-hide_banner', '-loglevel', 'error', '-nostats',
        '-fflags', '+genpts',
        '-i', inputName,
        '-vf', 'fps=30,setpts=PTS-STARTPTS,scale=trunc(iw/2)*2:trunc(ih/2)*2',
        ...baseVideoArgs,
        outputName
      );
    }

    let mp4Blob;
    try { mp4Blob = await _readFfmpegOutputBlob(ffmpeg, outputName); }
    catch (readError) {
      const tail = ffmpegLogTail.length ? ` | FFmpeg son satırlar: ${ffmpegLogTail.slice(-6).join(' ⏎ ')}` : '';
      throw new Error(`${String(readError?.message || readError)} (strateji ${strategy})${tail}`);
    }

    // v1.59: Encode başarılı sayılsa bile çıktı önce fiziksel MP4 kutu zincirini,
    // sonra gerçek stts/mdhd 30 CFR doğrulamasını geçmek zorunda.
    const structure = await _inspectMp4Container(mp4Blob);
    const cfr = await _verifyInstagramCfrMp4(mp4Blob);
    const minFps = Number(RENDER_CONFIG.MIN_OUTPUT_FPS || 23);
    const targetFps = Number(RENDER_CONFIG.TARGET_CFR_FPS || 30);
    if (
      !cfr?.ok ||
      Number(cfr.fps || 0) < minFps || Number(cfr.fps || 0) > 60 ||
      Math.abs(Number(cfr.fps || 0) - targetFps) > 0.02
    ) {
      throw new Error(`MP4 encode doğrulama: ${Number(cfr?.fps || 0).toFixed(3)} FPS hedef dışı.`);
    }

    if (onProgress) {
      try { onProgress(100); } catch (e) { ErrorHandler.silent(e); }
    }

    addSystemLog(
      `✓ FIX CHECKLIST v1.64: MP4 konteyner sağlam + ${cfr.fps.toFixed(3)} FPS CFR; ilk ${Number(RENDER_CONFIG.BLACK_FRAME_LEADIN_SEC || 1.20).toFixed(2)}sn görünür içerik kilidi aktif. moov@${structure.moovOffset}.`,
      'success'
    );

    return mp4Blob;
  } finally {
    try { await ffmpeg.FS('unlink', inputName); } catch (e) { ErrorHandler.silent(e); }
    try { await ffmpeg.FS('unlink', coverName); } catch (e) { ErrorHandler.silent(e); }
    try { await ffmpeg.FS('unlink', outputName); } catch (e) { ErrorHandler.silent(e); }
  }
};

const convertWebMtoMP4 = async (webmBlob, onProgress, firstFrameCoverBlob = null) => {
  return await _withFfmpegExclusive('MP4/CFR dönüşümü', async () => {
    // v1.171: Otomatik onarım döngüsü — doğru MP4 çıkana kadar (en fazla 10 deneme) strateji sadeleştirilerek yeniden denenir.
    const STRATEGY_PLAN = [1, 2, 3, 4, 2, 3, 4, 2, 3, 4];
    const STRATEGY_TEXT = { 1: 'süre kilidi + fade + kapak', 2: 'süre kilidi yok', 3: 'kapak bindirme yok', 4: 'ses filtresi yok' };
    const errors = [];
    for (let attempt = 1; attempt <= STRATEGY_PLAN.length; attempt++) {
      const strategy = STRATEGY_PLAN[attempt - 1];
      try {
        if (attempt > 1) {
          addSystemLog(`MP4 OTOMATİK ONARIM ${attempt}/${STRATEGY_PLAN.length}: FFmpeg temiz runtime, strateji ${strategy} (${STRATEGY_TEXT[strategy]}) ile yeniden encode ediliyor.`, 'warn');
        }
        return await _convertWebMtoMP4Unlocked(webmBlob, onProgress, firstFrameCoverBlob, strategy);
      } catch (e) {
        const msg = String(e?.message || e);
        errors.push(msg);
        if (/can only run one command at a time/i.test(msg)) {
          addSystemLog('FFmpeg eşzamanlı çalışma koruması devreye girdi; işlem sıralı kuyruk dışında başlatılamaz.', 'error');
        }
        addSystemLog(`MP4 OTOMATİK ONARIM: ${attempt}. deneme kabul edilmedi (${msg.slice(0, 380)}). Bozuk çıktı kaydedilmeyecek; runtime sıfırlanıyor.`, 'warn');
        if (_ffmpegInstance?.ffmpeg?.isWorker && !window.__otonomFfmpegNoWorker) {
          window.__otonomFfmpegNoWorker = true;
          SafeStorage.removeItem('otonom_ffmpeg_worker');
          addSystemLog('FFmpeg arka plan işçisi bu dönüşümü başaramadı; ana iş parçacığı moduna kalıcı olarak dönüldü.', 'warn');
        }
        _discardFfmpegRuntime();
        if (attempt < STRATEGY_PLAN.length) await new Promise(resolve => setTimeout(resolve, 1200));
      }
    }
    throw new Error(`MP4 30 CFR üretimi ${STRATEGY_PLAN.length} otomatik onarım denemesinde doğrulanamadı. İlk hata: ${errors[0] || '-'} | Son hata: ${errors[errors.length - 1] || '-'}`);
  });
};


// === v1.46 MP4 MINIMUM 23 FPS HARD GATE ===
// Kural: Kullanıcı MP4 istediğinde diske yazılan dosya mutlaka 23-60 FPS aralığında
// sabit kare hızlı (CFR) olmalıdır. Proje hedefi 30 CFR'dir.
// Kaynak tarayıcı tarafından doğrudan MP4 üretilmiş olsa bile doğrulama atlanmaz.
// Zaten 30 CFR olan MP4 yeniden encode edilmez; WebM/VFR/uygunsuz MP4 otomatik 30 CFR yapılır.
const ensureMinimumFpsMp4 = async (sourceBlob, onProgress = null, firstFrameCoverBlob = null) => {
  if (!(sourceBlob instanceof Blob) || !sourceBlob.size) {
    throw new Error('MP4 FPS guard: kaynak video boş veya geçersiz.');
  }

  const minFps = Number(RENDER_CONFIG.MIN_OUTPUT_FPS || 23);
  const targetFps = Number(RENDER_CONFIG.TARGET_CFR_FPS || 30);
  const sourceType = String(sourceBlob.type || '').toLowerCase();
  const hasFirstFrameCover = firstFrameCoverBlob instanceof Blob && firstFrameCoverBlob.size > 0;

  // v1.57 KALICI KURAL:
  // "Render 30 FPS idi" veya başka metadata HİÇBİR ZAMAN kanıt sayılmaz.
  // Sadece final MP4'ün gerçek byte-level stts/mdhd tablosu 30 CFR doğrularsa bypass vardır.
  // Okunamayan, VFR, 23 FPS altı veya 30 CFR olmayan kaynak MUTLAKA normalize edilir.
  if (sourceType.includes('mp4')) {
    try {
      const directCheck = await _verifyInstagramCfrMp4(sourceBlob);
      const directFps = Number(directCheck?.fps || 0);
      const directStartGap = await _inspectMp4VideoStartGap(sourceBlob);
      const directIsValid = !!directCheck?.ok &&
        !!directStartGap?.ok && Number(directStartGap.startGapSec || 0) <= 0.0005 &&
        directFps >= minFps && directFps <= 60 &&
        Math.abs(directFps - targetFps) <= 0.02;
      if (directCheck?.ok && Number(directStartGap?.startGapSec || 0) > 0.0005) {
        addSystemLog(`v1.67 t=0 GUARD: kaynak MP4 ${(directStartGap.startGapSec * 1000).toFixed(1)}ms video başlangıç boşluğu içeriyor; liste thumbnail siyah olmasın diye normalize edilecek.`, 'warn');
      }

      if (directIsValid) {
        if (hasFirstFrameCover) {
          const firstFrame = await _inspectVideoBlobFirstFrame(sourceBlob);
          if (!firstFrame?.ok) {
            addSystemLog(
              `MP4 ${directFps.toFixed(3)} FPS CFR fakat ilk kare şüpheli/siyah; kapak mühürü için yeniden normalize edilecek.`,
              'warn'
            );
          } else {
            addSystemLog(
              `✓ v1.57 STRICT FPS: kaynak gerçek ${directFps.toFixed(3)} FPS CFR ve ilk kare görünür; yeniden kodlama yok.`,
              'success'
            );
            return { blob: sourceBlob, fps: directFps, converted: false, strictVerified: true };
          }
        } else {
          addSystemLog(
            `✓ v1.57 STRICT FPS: kaynak gerçek ${directFps.toFixed(3)} FPS CFR; yeniden kodlama yok.`,
            'success'
          );
          return { blob: sourceBlob, fps: directFps, converted: false, strictVerified: true };
        }
      }
    } catch (directErr) {
      addSystemLog(
        `v1.57 STRICT FPS: kaynak FPS kesin doğrulanamadı; güven fast-path YASAK. ${targetFps} CFR normalize edilecek (${directErr.message}).`,
        'info'
      );
    }
  }

  if (hasFirstFrameCover) {
    addSystemLog(`✓ v1.64 siyah-kare kilidi: final MP4 clickbait kapağıyla ilk ${Number(RENDER_CONFIG.BLACK_FRAME_LEADIN_SEC || 1.20).toFixed(2)}sn fiziksel olarak mühürleniyor.`, 'info');
  }

  // FFmpeg dönüşümü v1.56 global FIFO kilidi üzerinden tek tek çalışır.
  const normalizedBlob = await convertWebMtoMP4(sourceBlob, onProgress, firstFrameCoverBlob);

  // v1.59: Final MP4 mutlaka fiziksel konteyner + gerçek CFR doğrulamasını geçer.
  // Doğrulama başarısızsa convertWebMtoMP4 zaten temiz runtime ile ikinci kez dener;
  // iki deneme de başarısızsa bozuk dosya üretmek yerine açık hata döner.
  const finalGate = await _assertFinalMp4SafeForWrite(normalizedBlob);
  const finalFps = Number(finalGate.fps || 0);
  if (finalFps < minFps || Math.abs(finalFps - targetFps) > 0.02) {
    throw new Error(`Final MP4 FPS kapısı başarısız: ${finalFps.toFixed(3)} FPS.`);
  }

  addSystemLog(
    `✓ FIX CHECKLIST v1.59: Final MP4 ${finalFps.toFixed(3)} FPS CFR + sağlam konteyner; minimum ${minFps} FPS garantisi geçti.`,
    'success'
  );

  return {
    blob: normalizedBlob,
    fps: finalFps,
    converted: true,
    strictVerified: true,
    forcedCfr: true
  };
};

