    if (renderAudioBus && audioDest) { renderAudioBus.gain.value = 1; renderAudioBus.connect(audioDest); }
    const audioOutput = renderAudioBus || audioDest;
    const { osc: silentOsc, gain: silentGain } = _createSilentOsc(audioCtx, audioOutput);
    const keepAliveOsc = audioCtx.createOscillator(); const keepAliveGain = audioCtx.createGain(); keepAliveGain.gain.value = 0.00001; keepAliveOsc.connect(keepAliveGain); keepAliveGain.connect(audioCtx.destination); keepAliveGain.connect(audioOutput); keepAliveOsc.start();
    const fontFamily = _getFontFamily(jobData.config.fontStyle);
    const FPS = 30;

