      if (OUTRO_ENABLED) { const bridgeFrames = Math.round(0.12 * FPS); for (let bi = 0; bi < bridgeFrames; bi++) { globalRenderedSec += 1 / FPS; requestCanvasFrame(); await nextFrame(); } }
      if (OUTRO_ENABLED) { const fixedOutroDur = (jobData.config.tip === 'iddia_analizi' || jobData.script._muteNarration) ? (rawOutroDur / Math.max(scaleFactor, 0.01)) : rawOutroDur; sysEventBus.emit('PROGRESS', { step: 'RENDER', percent: 90, text: 'Kapanış Render Ediliyor...' }); await renderScene(outroImg, jobData.script.lastQuote, jobData.assets.outroAudio, fixedOutroDur, false, true, null, 99, null, jobData.config.transition); }
      // v1.162 HARD AUDIO END: Son Söz görsel/ses zaman çizelgesi tamamlandıktan hemen sonra
