  // Üretilen videonun 1. saniyesini poster olarak çıkar. Bu kare clickbait kapağının
  // içindedir; tarayıcı autoplay'i engellese bile önizleme siyah görünmez.
  useEffect(() => {
    if (!uiState.videoUrl || config.outputType !== 'video') { setVideoPreviewPoster(''); setVideoPreviewReady(false); setVideoPreviewError(false); return; }
    setVideoPreviewReady(false);
    setVideoPreviewError(false);
    const renderedCover = workflowRef.current?.state?.assets?._renderedClickbaitFrame;
    if (typeof renderedCover === 'string' && renderedCover.startsWith('data:image/')) {
      setVideoPreviewPoster(renderedCover);
    }
    let cancelled = false;
    const previewVideo = document.createElement('video');
    previewVideo.muted = true;
    previewVideo.playsInline = true;
    previewVideo.preload = 'auto';
    previewVideo.src = uiState.videoUrl;
    const cleanup = () => {
      previewVideo.onloadedmetadata = null;
      previewVideo.onloadeddata = null;
      previewVideo.onseeked = null;
      previewVideo.onerror = null;
      try { previewVideo.removeAttribute('src'); previewVideo.load(); } catch(e) {}
    };
    previewVideo.onloadeddata = () => {
      if (!cancelled) setVideoPreviewReady(true);
    };
    previewVideo.onloadedmetadata = async () => {
      try {
        const duration = Number.isFinite(previewVideo.duration) ? Math.max(0, previewVideo.duration) : 0;
        const seekPoints = Array.from(new Set([
          Math.max(0.03, Math.min(0.05, Math.max(0.03, duration - 0.03))),
          Math.max(0.05, Math.min(0.12, Math.max(0.05, duration - 0.03))),
          Math.max(0.10, Math.min(0.30, Math.max(0.10, duration - 0.03))),
          Math.max(0.15, Math.min(0.60, Math.max(0.15, duration - 0.03))),
          Math.max(0.20, Math.min(1.00, Math.max(0.20, duration - 0.03)))
        ])).sort((a, b) => a - b);
        let seekIndex = 0;
        previewVideo.onseeked = () => {
          if (cancelled) return cleanup();
          try {
            const c = document.createElement('canvas');
            c.width = previewVideo.videoWidth || 720;
            c.height = previewVideo.videoHeight || 1280;
            const cctx = c.getContext('2d', { willReadFrequently: true });
            cctx.drawImage(previewVideo, 0, 0, c.width, c.height);
            const frameCheck = _inspectCanvasFrame(c);
            if (frameCheck.ok || seekIndex >= seekPoints.length - 1) {
              const poster = c.toDataURL('image/jpeg', 0.9);
              if (!cancelled) setVideoPreviewPoster(poster);
              return cleanup();
            }
          } catch(e) { ErrorHandler.silent(e); }
          seekIndex += 1;
          try { previewVideo.currentTime = seekPoints[seekIndex]; } catch(e) { cleanup(); }
        };
        previewVideo.currentTime = seekPoints[seekIndex];
      } catch(e) { cleanup(); }
    };
    previewVideo.onerror = () => { if (!cancelled) setVideoPreviewError(true); cleanup(); };
    return () => { cancelled = true; cleanup(); };
  }, [uiState.videoUrl, config.outputType]);

  useEffect(() => {
    const prevent = (e) => { e.preventDefault(); e.stopPropagation(); };
    window.addEventListener('dragover', prevent);
    window.addEventListener('drop', prevent);
    return () => { window.removeEventListener('dragover', prevent); window.removeEventListener('drop', prevent); ObjectURLManager.revokeAll(); };
  }, []);

