  const isGazeteHardRetryTarget = (name = '') => GAZETE_HARD_RETRY_NAMES.includes(name);
  const waitGazeteMs = (ms, signal) => new Promise((resolve, reject) => {
    const safeMs = Math.max(0, Number(ms) || 0);
    if (!safeMs) return resolve();
    const timer = setTimeout(() => {
      cleanup();
      resolve();
    }, safeMs);
    const onAbort = () => {
      cleanup();
      reject(new DOMException('Aborted', 'AbortError'));
    };
    const cleanup = () => {
      clearTimeout(timer);
      try { signal?.removeEventListener('abort', onAbort); } catch (e) { ErrorHandler.silent(e); }
    };
    if (signal?.aborted) return onAbort();
    try { signal?.addEventListener('abort', onAbort, { once: true }); } catch (e) { ErrorHandler.silent(e); }
  });
  const uniqueGazeteUrls = (urls = []) => urls.filter(Boolean).filter((url, index, list) => list.indexOf(url) === index);
  const weservGazeteUrl = (url, width = 900, quality = 90) => {
    if (!url || url.startsWith('data:')) return url;
    const cacheToken = gazeteRefreshNonceRef.current || `${_getTurkeyDateISO()}-${Date.now()}`;
    return `https://images.weserv.nl/?url=${encodeURIComponent(url)}&w=${width}&fit=contain&output=jpg&q=${quality}&cb=${encodeURIComponent(cacheToken)}`;
  };
  const createGazeteVariants = (rawUrls = [], cached = null) => {
    const cleanedRaw = uniqueGazeteUrls(rawUrls.map(url => cleanGazeteImageUrl(url)).filter(isLikelyGazeteImage));

    // ÇALIŞAN KURAL:
    // Görseli boyut/aspect oranına göre REDDETME.
    // Önce orijinal kaynak, sonra yüksek kaliteli proxy yedekleri.
    const fullCandidates = uniqueGazeteUrls([
      cached?.full,
      ...cleanedRaw,
      ...cleanedRaw.map(url => weservGazeteUrl(url, 1400, 94)),
      ...cleanedRaw.map(url => weservGazeteUrl(url, 1100, 92))
    ]);
    const thumbCandidates = uniqueGazeteUrls([
      cached?.thumb,
      ...cleanedRaw,
      ...cleanedRaw.map(url => weservGazeteUrl(url, 720, 90)),
      ...cleanedRaw.map(url => weservGazeteUrl(url, 540, 88)),
      ...fullCandidates
    ]);
    return { rawCandidates: cleanedRaw, fullCandidates, thumbCandidates };
  };
  const getGazeteCache = () => {
    if (gazeteResolvedCacheRef.current) return gazeteResolvedCacheRef.current;
    try { gazeteResolvedCacheRef.current = JSON.parse(SafeStorage.getItem(GAZETE_CACHE_KEY) || '{}') || {}; } catch (e) { gazeteResolvedCacheRef.current = {}; }
    return gazeteResolvedCacheRef.current;
  };
  const persistGazeteResolution = (date, name, kind, url) => {
    if (!url || url.startsWith('data:image/')) return;
    if (date === _getTurkeyDateISO()) return;
    const cache = getGazeteCache(); const key = `${date}|${name}`;
    cache[key] = { ...(cache[key] || {}), [kind]: url, updatedAt: Date.now() };
    const entries = Object.entries(cache).sort((a, b) => (b[1]?.updatedAt || 0) - (a[1]?.updatedAt || 0)).slice(0, 240);
    gazeteResolvedCacheRef.current = Object.fromEntries(entries);
    SafeStorage.setItem(GAZETE_CACHE_KEY, JSON.stringify(gazeteResolvedCacheRef.current));
  };
  const buildGazeteCards = (date, names = GAZETE_MASTER_LIST) => {
    const cache = getGazeteCache();
    const isToday = date === _getTurkeyDateISO();
    return names.map(name => {
      // v1.85 FAIL-CLOSED:
      // Kart açılırken "muhtemelen bu gazetedir" diye CDN URL tahmin etmiyoruz.
      // Özellikle Aydınlık storage/newspapers kalıbı bazı günlerde başka asset/person/reklam
      // döndürebildiği için yanlış bilgi üretiyordu.
      const cached = isToday ? null : (cache[`${date}|${name}`] || null);
      const variants = createGazeteVariants([], cached);
      const placeholder = makeGazetePlaceholder(name);
      return {
        name,
        requestedDate: date,
        ...variants,
        fullCandidates: [...variants.fullCandidates, placeholder],
        thumbCandidates: [...variants.thumbCandidates, placeholder],
        fullSrc: variants.fullCandidates[0] || placeholder,
        thumbSrc: variants.thumbCandidates[0] || placeholder,
        resolvedFull: cached?.full || '',
        resolvedThumb: cached?.thumb || '',
        sources: cached ? ['Doğrulanmış geçmiş cache'] : [],
        loaded: false,
        verified: false,
        placeholder,
        revision: 0
      };
    });
  };

  const fetchWithGazeteTimeout = async (url, externalSignal, timeoutMs = 6500) => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    const abortFromParent = () => controller.abort();
    if (externalSignal) { if (externalSignal.aborted) controller.abort(); else externalSignal.addEventListener('abort', abortFromParent, { once: true }); }
    try { return await fetch(url, { signal: controller.signal, cache: 'no-store' }); }
    finally { clearTimeout(timer); if (externalSignal) externalSignal.removeEventListener('abort', abortFromParent); }
  };

  const _gazeteBackendResponseToText = async (response) => {
    const raw = await response.text();
    if (!raw) return '';
    const contentType = String(response.headers?.get?.('content-type') || '').toLowerCase();
    if (contentType.includes('json') || /^[\s]*[\[{]/.test(raw)) {
      try {
        const data = JSON.parse(raw);
        const direct = [data?.body, data?.html, data?.text, data?.content, data?.result, data?.data]
          .find(value => typeof value === 'string' && value.length >= 20);
        if (direct) return direct;
        return JSON.stringify(data);
      } catch (e) { ErrorHandler.silent(e); }
    }
    return raw;
  };

  const fetchViaOtonomGazeteBackend = async (pageUrl, signal, timeoutMs = 6500) => {
    const backendBases = _readOtonomRuntimeBackendCandidates();
    if (!backendBases.length) {
      if (!gazeteBackendWarnedRef.current) {
        gazeteBackendWarnedRef.current = true;
        addSystemLog('Gazete backend adayı bulunamadı; Extension/Jina fallback kullanılacak.', 'warn');
      }
      return [];
    }

    if (!gazeteBackendLoggedRef.current) {
      gazeteBackendLoggedRef.current = true;
      addSystemLog(`✓ OTONOM gazete backend çözümleyici aktif: ${backendBases.length} aday güvenli biçimde probe edilecek.`, 'success');
    }

    const encoded = encodeURIComponent(pageUrl);
    const routes = [];
    const push = (url, label) => {
      if (!url || routes.some(item => item.url === url)) return;
      routes.push({ url, label });
    };

    const lower = String(pageUrl || '').toLowerCase();
    backendBases.forEach((base, baseIndex) => {
      const endpoints = _gazeteProxyEndpointsForBase(base);
      push(`${endpoints.proxy}?url=${encoded}`, `backend${baseIndex + 1}/proxy`);
      push(`${endpoints.apiProxy}?url=${encoded}`, `backend${baseIndex + 1}/api-proxy`);
      push(`${endpoints.apiGazeteProxy}?url=${encoded}`, `backend${baseIndex + 1}/api-gazete-proxy`);
      if (lower.includes('gazetemanset.gzt.com') || lower.includes('gzt.com')) push(`${endpoints.gzt}?url=${encoded}`, `backend${baseIndex + 1}/gzt`);
      if (lower.includes('gazeteoku.com')) push(`${endpoints.gazeteoku}?url=${encoded}`, `backend${baseIndex + 1}/gazeteoku`);
      if (lower.includes('aydinlik.com.tr')) push(`${endpoints.aydinlik}?url=${encoded}`, `backend${baseIndex + 1}/aydinlik`);
      if (lower.includes('yenimesaj')) push(`${endpoints.yenimesaj}?url=${encoded}`, `backend${baseIndex + 1}/yenimesaj`);
    });

    const bodies = [];
    for (const route of routes) {
      if (signal?.aborted) break;
      try {
        const response = await fetchWithGazeteTimeout(route.url, signal, timeoutMs);
        if (!response.ok) {
          // Yerel köprü aynı URL'yi diğer takma yollarda tekrar denemez.
          if (response.headers?.get?.('x-otonom-bridge') === '1') break;
          continue;
        }
        const body = await _gazeteBackendResponseToText(response);
        if (typeof body === 'string' && body.length >= 120) {
          bodies.push(body);
          addSystemLog(`✓ Gazete backend cevap verdi: ${route.label}`, 'success');
          break;
        }
      } catch (e) {
        if (e?.name === 'AbortError' && signal?.aborted) throw e;
        ErrorHandler.silent(e);
      }
    }
    return bodies;
  };
  const _gazeteProxyPayloadToText = async (response, proxyDef) => {
    if (!response?.ok) return '';
    try {
      if (proxyDef?.json) {
        const data = await response.json();
        const body = [
          data?.contents, data?.content, data?.body, data?.html, data?.text,
          typeof data?.data === 'string' ? data.data : '',
          data?.data?.contents, data?.data?.html, data?.data?.body
        ].find(value => typeof value === 'string' && value.length >= 120);
        return body || '';
      }
      const body = await response.text();
      return typeof body === 'string' ? body : '';
    } catch (e) {
      ErrorHandler.silent(e);
      return '';
    }
  };

  const fetchViaGazetePublicTransports = async (targetUrl, signal, timeoutMs = 4500) => {
    if (!targetUrl) return [];
    const bodies = [];
    const add = (body) => {
      if (typeof body !== 'string' || body.length < 120) return;
      const fp = body.slice(0, 1200);
      if (bodies.some(existing => existing.slice(0, 1200) === fp)) return;
      bodies.push(body);
    };

    // 1) Site CORS izin veriyorsa en temiz yol doğrudan fetch.
    try {
      const response = await fetchWithGazeteTimeout(targetUrl, signal, Math.min(timeoutMs, 3200));
      if (response.ok) {
        const body = await response.text();
        add(body);
        if (body?.length >= 120) return bodies;
      }
    } catch (e) {
      if (e?.name === 'AbortError' && signal?.aborted) throw e;
      ErrorHandler.silent(e);
    }

    // 2) Eski çalışan CORS proxy havuzu. Hepsini paralel dener; ilk başarılı
    // gövdeyi kullanır. Böylece tek proxy'nin çökmesi gazete akışını kesmez.
    const proxyTasks = CORS_PROXIES
      .filter(proxy => !proxy.local)
      .map(async proxy => {
        try {
          const response = await fetchWithGazeteTimeout(proxy.url(targetUrl), signal, timeoutMs);
          if (!response.ok) return '';
          return await _gazeteProxyPayloadToText(response, proxy);
        } catch (e) {
          if (e?.name === 'AbortError' && signal?.aborted) throw e;
          return '';
        }
      });

    if (proxyTasks.length) {
      const settled = await Promise.allSettled(proxyTasks);
      for (const result of settled) {
        if (result.status === 'fulfilled') add(result.value);
      }
    }

    return bodies;
  };

  const postGazeteExtensionRequest = (request) => {
    // Gemini Canvas farklı kökenli bir iframe içinde çalışabildiği için
    // aynı isteği ilgili frame'lere yolla; uzantı cevapta aynı id'yi döndürür.
    const targets = [];
    try { targets.push(window); } catch (e) {}
    try { if (window.parent && window.parent !== window) targets.push(window.parent); } catch (e) {}
    try { if (window.top && window.top !== window && window.top !== window.parent) targets.push(window.top); } catch (e) {}
    let sent = 0;
    targets.forEach(target => {
      try { target.postMessage(request, '*'); sent++; }
      catch (e) { ErrorHandler.silent(e); }
    });
    return sent;
  };

  const probeGazeteExtension = (signal) => new Promise((resolve, reject) => {
    if (gazeteExtensionAvailableRef.current === true) return resolve(true);
    if (gazeteExtensionAvailableRef.current === false && Date.now() - gazeteExtensionProbeAtRef.current < 15000) return resolve(false);
    gazeteExtensionProbeAtRef.current = Date.now();
    const id = `gn_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    const cleanup = () => {
      window.removeEventListener('message', onMessage);
      signal?.removeEventListener('abort', onAbort);
      clearTimeout(timer);
    };
    const finish = (fn, value) => { cleanup(); fn(value); };
    const onMessage = (event) => {
      if (event.data?.source !== 'OTONOM_GAZETE_EXTENSION' || event.data?.id !== id || event.data?.type !== 'PONG') return;
      gazeteExtensionAvailableRef.current = true;
      finish(resolve, true);
    };
    const onAbort = () => finish(reject, new DOMException('Aborted', 'AbortError'));
    const timer = setTimeout(() => {
      gazeteExtensionAvailableRef.current = false;
      finish(resolve, false);
    }, 700);
    window.addEventListener('message', onMessage);
    if (signal?.aborted) return onAbort();
    signal?.addEventListener('abort', onAbort, { once: true });
    if (!postGazeteExtensionRequest({ source: 'OTONOM_APP', type: 'GAZETE_PING', id })) {
      gazeteExtensionAvailableRef.current = false;
      finish(resolve, false);
    }
  });

  const fetchViaGazeteExtension = (url, signal, timeoutMs = 9000) => new Promise((resolve, reject) => {
    const requestId = `gn_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    let settled = false;

    const cleanup = () => {
      window.removeEventListener('message', onMessage);
      if (signal) signal.removeEventListener('abort', onAbort);
      clearTimeout(timer);
    };

    const finish = (fn, value) => {
      if (settled) return;
      settled = true;
      cleanup();
      fn(value);
    };

    const onAbort = () => finish(reject, new DOMException('Aborted', 'AbortError'));

    const onMessage = (event) => {
      const data = event.data;
      if (!data || data.source !== 'OTONOM_GAZETE_EXTENSION' || data.id !== requestId) return;

      if (data.type === 'FETCH_RESULT') {
        gazeteExtensionAvailableRef.current = true;
        finish(resolve, data);
      }
    };

    const timer = setTimeout(() => {
      gazeteExtensionAvailableRef.current = false;
      finish(resolve, null);
    }, timeoutMs);

    window.addEventListener('message', onMessage);

    if (signal) {
      if (signal.aborted) return onAbort();
      signal.addEventListener('abort', onAbort, { once: true });
    }

    const request = {
      source: 'OTONOM_APP',
      type: 'GAZETE_FETCH',
      id: requestId,
      url
    };

    if (!postGazeteExtensionRequest(request)) {
      gazeteExtensionAvailableRef.current = false;
      finish(resolve, null);
    }
  });

  const fetchGazeteSourceTextsFast = async (pageUrl, signal, passIndex = 0, options = {}) => {
    let cleanTargetUrl = pageUrl;
    try {
      const u = new URL(pageUrl);
      u.searchParams.delete('_gn_refresh');
      u.searchParams.delete('_gazete_refresh');
      if (passIndex > 0) {
        u.searchParams.set('_gn_refresh', `${Date.now()}_${passIndex}`);
        u.searchParams.set('_gn_pass', String(passIndex));
      }
      cleanTargetUrl = u.href;
    } catch (e) {}

    const bodies = [];
    const addBody = (body) => {
      if (typeof body !== 'string' || body.length < 120) return;
      const fingerprint = body.slice(0, 1200);
      if (bodies.some(existing => existing.slice(0, 1200) === fingerprint)) return;
      bodies.push(body);
    };

    // v1.87: Chrome uzantısı varsa CORS proxy/yerel backend beklemeden
    // izinli kaynağın gerçek HTML'ini al. Başarısızsa eski yollar açık kalır.
    let extensionTried = false;
    try {
      if (await probeGazeteExtension(signal)) {
        extensionTried = true;
        const extResult = await fetchViaGazeteExtension(cleanTargetUrl, signal, options?.fastRetry ? 14000 : 22000);
        if (extResult?.ok && typeof extResult.body === 'string') {
          gazeteExtensionWarnedRef.current = false;
          addBody(extResult.body);
        }
      }
    } catch (e) {
      if (e?.name === 'AbortError' && signal?.aborted) throw e;
      ErrorHandler.silent(e);
    }
    if (bodies.length && !options?.forceFallbacks) return bodies;

    // v1.77: Kritik üç gazete backend'i varsa önce onu kullanır; ama backend yoksa
    // bütün gazete sistemi ona bağımlı değildir.
    if (options?.backendFirst) {
      try {
        const backendBodies = await fetchViaOtonomGazeteBackend(
          cleanTargetUrl,
          signal,
          options?.backendTimeoutMs || (options?.fastRetry ? 1800 : 2800)
        );
        backendBodies.forEach(addBody);
      } catch (e) {
        if (e?.name === 'AbortError' && signal?.aborted) throw e;
        ErrorHandler.silent(e);
      }
    }

    if (bodies.length && options?.backendFirst && !options?.forceFallbacks) return bodies;

    // v1.77 KÖK DÜZELTME: direct + public CORS proxy taşıma yolu yeniden aktif.
    // v1.76'da CORS_PROXIES tanımlıydı ama gazete HTML okumada hiç kullanılmıyordu.
    try {
      const publicBodies = await fetchViaGazetePublicTransports(
        cleanTargetUrl,
        signal,
        options?.fastRetry ? 2800 : 4500
      );
      publicBodies.forEach(addBody);
    } catch (e) {
      if (e?.name === 'AbortError' && signal?.aborted) throw e;
      ErrorHandler.silent(e);
    }

    // Public taşıma gövde bulduysa uzaktaki extension/Jina gecikmesini zorunlu kılma.
    // Ham HTML yeterli değilse aşağıdaki fallback'ler yine devreye girer.
    if ((!bodies.length || options?.forceFallbacks) && !extensionTried) {
      try {
        const extResult = await fetchViaGazeteExtension(cleanTargetUrl, signal, options?.fastRetry ? 2600 : 5000);
        if (extResult?.ok && typeof extResult.body === 'string') {
          gazeteExtensionWarnedRef.current = false;
          addBody(extResult.body);
        }
      } catch (e) {
        if (e?.name === 'AbortError' && signal?.aborted) throw e;
        ErrorHandler.silent(e);
      }
    }

    if (!bodies.length || options?.forceFallbacks) {
      const targetNoScheme = cleanTargetUrl.replace(/^https?:\/\//i, '');
      for (const jinaUrl of [
        `https://r.jina.ai/https://${targetNoScheme}`,
        `https://r.jina.ai/http://${targetNoScheme}`
      ]) {
        if (signal?.aborted) break;
        try {
          const response = await fetchWithGazeteTimeout(jinaUrl, signal, options?.fastRetry ? 3000 : 5000);
          if (!response.ok) continue;
          const body = await response.text();
          addBody(body);
          if (typeof body === 'string' && body.length >= 120) break;
        } catch (e) {
          if (e?.name === 'AbortError' && signal?.aborted) throw e;
          ErrorHandler.silent(e);
        }
      }
    }

    // Backend-first olmayan genel kaynaklarda backend en son kurtarma yolu olabilir.
    // v1.192: backendTimeoutMs seçenekten okunur; BİK gibi yavaş (8-9 sn) kaynaklar
    // bu pencereye sığar. Sabit 1600, yavaş kaynakları matematiksel olarak yetişemez kılmıştı.
    if (!bodies.length && !options?.backendFirst) {
      try {
        const backendBodies = await fetchViaOtonomGazeteBackend(cleanTargetUrl, signal, options?.backendTimeoutMs || 1600);
        backendBodies.forEach(addBody);
      } catch (e) {
        if (e?.name === 'AbortError' && signal?.aborted) throw e;
        ErrorHandler.silent(e);
      }
    }

    return bodies;
  };
  const gazeteCandidateMatchesForcedName = (src = '', forcedName = '', meta = {}) => {
    if (!forcedName) return true;

    const context = `${meta.alt || ''} ${meta.title || ''} ${meta.hint || ''}`;
    const contextName = resolveGazeteNameFromText(context);
    if (contextName) return contextName === forcedName;

    // Bağlam ad vermiyorsa URL'nin kendisinde gazetenin slug'ı bulunmalı.
    // Böylece Aydınlık sitesinin genel og:image/logo görseli başka gazete diye kabul edilmez.
    const targetMeta = GAZETE_META[forcedName] || {};
    const urlNorm = normalizeGazeteText(decodeGazeteUrl(src));
    const tokens = [
      forcedName,
      targetMeta.ayd,
      targetMeta.go,
      targetMeta.gzt
    ]
      .filter(Boolean)
      .map(normalizeGazeteText)
      .filter(token => token.length >= 4);

    return tokens.some(token => urlNorm.includes(token));
  };

  const extractGazeteCandidates = (payload, pageUrl, sourceLabel, forcedName = '') => {
    const text = String(payload || ''); const out = []; const seen = new Set();
    const add = (url, meta = {}) => {
      const src = cleanGazeteImageUrl(url, pageUrl);
      if (!src || !isLikelyGazeteImage(src) || seen.has(src)) return;

      // v1.84 GAZETE ESLESTIRME KILIDI:
      // Parent container metni birden cok kart/gazete adi tasiyabilir. Bu nedenle hint tek basina
      // gazete kimligi sayilmaz. Once img alt/title/aria benzeri acik metadata ve URL slug kaniti.
      const explicitName = resolveGazeteNameFromText(`${meta.alt || ''} ${meta.title || ''}`);
      const hintName = resolveGazeteNameFromText(`${meta.hint || ''}`);
      const urlName = resolveGazeteNameFromText(decodeGazeteUrl(src));

      if (forcedName && !gazeteCandidateMatchesForcedName(src, forcedName, meta)) return;

      if (!forcedName) {
        // URL baska gazeteyi, alt/title baska gazeteyi soyluyorsa bu aday guvenilmez.
        if (explicitName && urlName && explicitName !== urlName) return;

        // Sadece genis parent/hint metninden bulunan isim; portre, yazar fotografi veya komsu
        // gazete kartini yanlis gazeteye baglamasin. Guclu kapak URL ipucu yoksa adayi atla.
        if (!explicitName && !urlName && hintName && !/manset|gazete|newspaper|cover|storage\/newspapers/i.test(src)) return;
      }

      const resolvedName = forcedName || explicitName || urlName || hintName || meta.name || '';
      if (!resolvedName) return;

      seen.add(src);
      const identityBoost = forcedName
        ? ((explicitName === forcedName || urlName === forcedName) ? 80 : 0)
        : (explicitName ? 70 : (urlName ? 55 : 0));
      const portraitHint = /manset|gazete|newspaper|cover|storage\/newspapers/i.test(src) ? 12 : 0;

      out.push({
        name: resolvedName,
        src,
        source: sourceLabel,
        alt: meta.alt || '',
        title: meta.title || '',
        hint: meta.hint || '',
        score: (meta.score || 10) + identityBoost + portraitHint
      });
    };
    try {
      const doc = new DOMParser().parseFromString(text, 'text/html');

      // Detay sayfasında hedef gazetenin adını taşıyan görselleri önce ve yüksek puanla al.
      if (forcedName) {
        doc.querySelectorAll('img,source').forEach(el => {
          const alt = el.getAttribute('alt') || '';
          const title = el.getAttribute('title') || '';
          const aria = el.getAttribute('aria-label') || '';
          const nearby = `${alt} ${title} ${aria} ${el.parentElement?.innerText || ''}`.slice(0, 700);
          const detected = resolveGazeteNameFromText(nearby);
          if (detected === forcedName) {
            ['data-src', 'data-original', 'data-lazy-src', 'data-image', 'data-url', 'data-fallback-src', 'src'].forEach(attr => {
              const value = el.getAttribute(attr);
              if (value) add(value, { alt, title, hint: nearby, score: 180 });
            });
            const srcset = el.getAttribute('srcset') || el.getAttribute('data-srcset') || '';
            srcset.split(',').forEach(part => {
              const value = part.trim().split(/\s+/)[0];
              if (value) add(value, { alt, title, hint: nearby, score: 175 });
            });
          }
        });
      }

      // Site logosu / sosyal paylaşım görseli gazete kapağı sanılmasın.
      // OG image yalnız URL veya kendi metadata'sı gazete adını kanıtlıyorsa isim kazanır.
      doc.querySelectorAll('meta[property="og:image"],meta[name="twitter:image"],meta[property="twitter:image"]').forEach(el =>
        add(el.getAttribute('content'), { hint: '', score: 25 })
      );
      doc.querySelectorAll('img,source').forEach(el => {
        const alt = el.getAttribute('alt') || ''; const title = el.getAttribute('title') || '';
        const hint = `${el.parentElement?.innerText || ''} ${el.closest('a')?.getAttribute('href') || ''}`.slice(0, 500);
        ['data-src', 'data-original', 'data-lazy-src', 'data-image', 'data-url', 'data-fallback-src', 'src'].forEach(attr => { const value = el.getAttribute(attr); if (value) add(value, { alt, title, hint, score: attr === 'src' ? 45 : 55 }); });
        const srcset = el.getAttribute('srcset') || el.getAttribute('data-srcset') || '';
        srcset.split(',').forEach(part => add(part.trim().split(/\s+/)[0], { alt, title, hint, score: 50 }));
      });
    } catch (e) { ErrorHandler.silent(e); }
    let match;
    const mdImage = /!\[([^\]]*)\]\((https?:\/\/[^\s)]+)(?:\s+["'][^"']*["'])?\)/gi;
    while ((match = mdImage.exec(text))) add(match[2], { alt: match[1], hint: text.slice(Math.max(0, match.index - 180), mdImage.lastIndex + 180), score: 65 });
    const metaRegex = /(?:property|name)=["'](?:og:image|twitter:image)["'][^>]*content=["']([^"']+)["']|content=["']([^"']+)["'][^>]*(?:property|name)=["'](?:og:image|twitter:image)["']/gi;
    while ((match = metaRegex.exec(text))) add(match[1] || match[2], { score: 25 });
    const jsonImage = /["'](?:image|imageUrl|image_url|manset|cover|src)["']\s*:\s*["'](https?:\\?\/\\?\/[^"']+)["']/gi;
    while ((match = jsonImage.exec(text))) add(match[1], { hint: text.slice(Math.max(0, match.index - 120), match.index + 240), score: 60 });
    const directImage = /https?:\\?\/\\?\/[A-Za-z0-9._~:/?#\[\]@!$&'()*+,;=%-]+?\.(?:jpe?g|png|webp|avif)(?:\?[A-Za-z0-9._~:/?#\[\]@!$&'()*+,;=%-]*)?/gi;
    while ((match = directImage.exec(text))) add(match[0], { hint: text.slice(Math.max(0, match.index - 200), directImage.lastIndex + 200), score: 50 });
    return out;
  };
  const gazeteManifestDateNeedle = (selectedDate) => {
    const [year, month, day] = String(selectedDate || '').split('-');
    const monthName = GAZETE_MONTHS_TR[Math.max(0, Number(month) - 1)] || '';
    return normalizeGazeteText(`${Number(day)} ${monthName} ${year}`);
  };

  const gazeteAliasesForCanonical = (name) => {
    const aliases = [name];
    Object.entries(GAZETE_ALIAS_MAP).forEach(([alias, canonical]) => {
      if (canonical === name) aliases.push(alias);
    });
    return [...new Set(aliases.map(v => String(v || '').trim()).filter(Boolean))];
  };

  // Yalnızca kaynak tarafından tarih ile ilişkilendirilmiş gazete kartlarını kabul et.
  // Tarih kart metninde veya arşiv URL'sinde bulunabilir; site şablonları iki biçimi de kullanır.
  const gazeteValueMatchesDate = (value, selectedDate) => {
    if (!value || !selectedDate) return false;
    const [year, month, day] = String(selectedDate).split('-');
    const monthName = GAZETE_MONTHS_TR[Math.max(0, Number(month) - 1)] || '';
    const dayNum = String(Number(day));
    const normalized = normalizeGazeteText(decodeGazeteUrl(String(value)));
    const variants = [
      selectedDate, `${year}-${month}-${day}`, `${day}.${month}.${year}`,
      `${day}/${month}/${year}`, `${day}-${month}-${year}`,
      `${dayNum} ${monthName} ${year}`, `${day} ${monthName} ${year}`
    ].map(normalizeGazeteText).filter(Boolean);
    return variants.some(v => normalized.includes(v));
  };

  const resolveGazeteNameFromSourceHref = (href, sourceKey = '') => {
    const decoded = decodeGazeteUrl(String(href || '')).toLocaleLowerCase('tr-TR');
    if (!decoded) return null;
    for (const [canonical, meta] of Object.entries(GAZETE_META)) {
      const slugs = sourceKey === 'GZT' ? [meta.gzt] :
        sourceKey === 'GazeteOku' ? [meta.go] :
        sourceKey === 'Aydınlık' ? [meta.ayd] : [meta.gzt, meta.go, meta.ayd];
      for (const slugValue of slugs) {
        const slug = String(slugValue || '').trim().toLocaleLowerCase('tr-TR');
        if (!slug) continue;
        // URL'de slug tam bir yol bileşeni olmalı; kısa adların yanlış eşleşmesini önle.
        if (decoded.includes(`/${slug}/`) || decoded.endsWith(`/${slug}`) || decoded.includes(`/${slug}?`) || decoded.includes(`/${slug}#`)) {
          return GAZETE_EXCLUDED.includes(canonical) ? null : canonical;
        }
      }
    }
    return null;
  };

  const extractExactDailyManifestNames = (payload, selectedDate, sourceKey = '') => {
    if (!payload || !gazetePayloadMatchesDate(payload, selectedDate)) return [];
    // v1.189: evrensel.net kendi arşiv sayfası (?date=YYYY-MM-DD) — yalnız kendi adını
    // üretir; tarihle SSR'li sayfada "EVRENSEL'İN MANŞETİ" bölümü + kendi dosya görseli
    // zorunlu. Tarih eşleşmezse FAIL-CLOSED aynen: hiçbir ad verilmez.
    if (sourceKey === 'Evrensel/kendi') {
      const body = String(payload);
      const hasManset = /EVRENSEL.{0,24}MANŞETİ/i.test(body) || /manşet['\u2019]{0,2}i/i.test(body.slice(0, 60000));
      const hasOwnImage = /\/images\/\d+\/upload\/dosya\/\d+\.(?:jpe?g|png|webp)/i.test(body);
      return (hasManset && hasOwnImage) ? ['Evrensel'] : [];
    }
    // v1.191: BİK İlk Sayfalar — kaynaktan tarih ile ilişkilendirilmiş kart zorunludur:
    // kart alt metni "26 Ekim 2026 - ... tarihli <ad> gazetesi ilk sayfası" biçiminde
    // tarih kanıtını taşır; yalnız tarihli altı çözümlenen ad kabul edilir.
    if (sourceKey === 'BİK') {
      try {
        const doc = new DOMParser().parseFromString(String(payload), 'text/html');
        const hits = [];
        doc.querySelectorAll('a[href*="/first_pages/"]').forEach((link, index) => {
          const image = link.querySelector('img');
          const alt = image?.getAttribute('alt') || '';
          const figureName = link.closest('figure')?.querySelector('.figcaption span')?.textContent || '';
          if (!gazeteValueMatchesDate(`${alt} ${figureName}`, selectedDate)) return;
          const name = resolveGazeteNameFromText(`${alt} ${figureName}`);
          if (name) hits.push({ name, index });
        });
        return [...new Set(hits.sort((a, b) => a.index - b.index).map(hit => hit.name))];
      } catch (e) { ErrorHandler.silent(e); return []; }
    }
    // v1.191: dijitalbasin Read sayfaları — tek gazetenin kendi edition sayfası;
    // SSR publication-name + publication-date birebir doğrulanır, eşleşmezse [].
    if (typeof sourceKey === 'string' && sourceKey.startsWith('DijitalBasin/')) {
      try {
        const doc = new DOMParser().parseFromString(String(payload), 'text/html');
        const nameText = (doc.querySelector('.publication-name')?.textContent || '').trim();
        const dateText = (doc.querySelector('.publication-date')?.textContent || '').trim();
        const needle = gazeteManifestDateNeedle(selectedDate);
        if (!needle || normalizeGazeteText(dateText) !== normalizeGazeteText(needle)) return [];
        const name = resolveGazeteNameFromText(nameText);
        return name ? [name] : [];
      } catch (e) { ErrorHandler.silent(e); return []; }
    }
    const cardHits = [];
    const seenNames = new Set();
    const record = (name, index) => {
      if (!name || GAZETE_EXCLUDED.includes(name) || seenNames.has(name)) return;
      seenNames.add(name);
      cardHits.push({ name, index });
    };
    try {
      const doc = new DOMParser().parseFromString(String(payload), 'text/html');
      if (sourceKey === 'Aydınlık') {
        doc.querySelectorAll('.newspaper-item a[title]').forEach((link, index) => {
          const image = link.querySelector('img');
          const imageUrl = decodeGazeteUrl(image?.getAttribute('src') || image?.getAttribute('data-src') || image?.getAttribute('data-original') || '');
          if (!imageUrl.includes(`/storage/newspapers/${selectedDate}/`)) return;
          const name = resolveGazeteNameFromText(`${link.getAttribute('title') || ''} ${link.textContent || ''}`) || resolveGazeteNameFromSourceHref(link.getAttribute('href') || '', sourceKey);
          if (name) record(name, index);
        });
      } else {
        // Önce link kartları: GZT tarihli arşiv bağlantısını href'te tutabilir,
        // img[alt] ise yalnızca gazetenin adını içerir. Önceki ayrıştırıcı bunu kaçırıyordu.
        const anchors = sourceKey === 'GZT'
          ? doc.querySelectorAll('a[href]')
          : doc.querySelectorAll('a[href*="/gazeteler/"]');
        anchors.forEach((link, index) => {
          const href = decodeGazeteUrl(link.getAttribute('href') || '');
          const image = link.querySelector('img');
          const cardText = [
            link.textContent || '', link.getAttribute('aria-label') || '', link.getAttribute('title') || '',
            image?.getAttribute('alt') || '', image?.getAttribute('title') || '',
            link.parentElement?.innerText || '', href
          ].join(' ').slice(0, 1200);
          const dateProvenByHref = gazeteValueMatchesDate(href, selectedDate);
          const dateProvenByCard = gazeteValueMatchesDate(cardText, selectedDate);
          if (!dateProvenByHref && !dateProvenByCard) return;
          const name = resolveGazeteNameFromText([
            link.getAttribute('aria-label') || '', link.getAttribute('title') || '', link.textContent || '',
            image?.getAttribute('alt') || '', image?.getAttribute('title') || ''
          ].join(' ')) || resolveGazeteNameFromSourceHref(href, sourceKey);
          if (name) record(name, index);
        });

        // Bazı kaynaklar gazeteyi img[alt] olarak listelerken tarihi kartın dışındaki
        // metinde gösterir; yalnız yakın kapsayıcıdaki tarih kanıtına izin ver.
        doc.querySelectorAll('img[alt],img[title]').forEach((image, index) => {
          const link = image.closest('a');
          const href = decodeGazeteUrl(link?.getAttribute('href') || '');
          const nearbyText = [
            image.getAttribute('alt') || '', image.getAttribute('title') || '',
            link?.textContent || '', link?.parentElement?.innerText || '', href
          ].join(' ').slice(0, 1200);
          if (!gazeteValueMatchesDate(href, selectedDate) && !gazeteValueMatchesDate(nearbyText, selectedDate)) return;
          const name = resolveGazeteNameFromText(`${image.getAttribute('alt') || ''} ${image.getAttribute('title') || ''} ${link?.textContent || ''}`) || resolveGazeteNameFromSourceHref(href, sourceKey);
          if (name) record(name, index + 100000);
        });
      }
    } catch (e) { ErrorHandler.silent(e); }

    if (!cardHits.length && sourceKey === 'Aydınlık') {
      const markdownImage = /!\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/gi;
      let match;
      while ((match = markdownImage.exec(String(payload)))) {
        if (!decodeGazeteUrl(match[2]).includes(`/storage/newspapers/${selectedDate}/`)) continue;
        const name = resolveGazeteNameFromText(match[1]);
        if (name) record(name, match.index);
      }
    }
    if (cardHits.length) return cardHits.sort((a, b) => a.index - b.index).map(hit => hit.name);

    // HTML yerine Markdown dönen taşımalarda yalnız açık ad+tarih eşleşmeleri alınır.
    const haystack = normalizeGazeteText(String(payload));
    const dateNeedle = gazeteManifestDateNeedle(selectedDate);
    if (!dateNeedle) return [];
    const hits = [];
    for (const name of GAZETE_MASTER_LIST) {
      let bestIndex = Number.POSITIVE_INFINITY;
      for (const alias of gazeteAliasesForCanonical(name)) {
        const a = normalizeGazeteText(alias);
        if (!a) continue;
        for (const pattern of [`${a} ${dateNeedle}`, `${a} gazetesi ${dateNeedle}`, `${a} gazete ${dateNeedle}`]) {
          const pos = haystack.indexOf(pattern);
          if (pos >= 0 && pos < bestIndex) bestIndex = pos;
        }
      }
      if (Number.isFinite(bestIndex)) hits.push({ name, index: bestIndex });
    }
    hits.sort((a, b) => a.index - b.index);
    return [...new Set(hits.map(hit => hit.name))];
  };

  // v1.191: dijitalbasin Read sayfası doğrulayıcı — SSR'de publication-name gazetenin
  // KENDİ adının çözümlenmiş karşılığı ve publication-date seçili tarihle birebir
  // eşleşmek zorundadır; aksi halde kapak/ad verilmez (fail-closed).
  const dijitalBasinReadVerified = (payload, forcedName, selectedDate) => {
    if (!payload || !forcedName) return false;
    try {
      const doc = new DOMParser().parseFromString(String(payload), 'text/html');
      const nameText = (doc.querySelector('.publication-name')?.textContent || '').trim();
      const dateText = (doc.querySelector('.publication-date')?.textContent || '').trim();
      if (resolveGazeteNameFromText(nameText) !== forcedName) return false;
      const needle = gazeteManifestDateNeedle(selectedDate);
      if (!needle || normalizeGazeteText(dateText) !== normalizeGazeteText(needle)) return false;
      return true;
    } catch (e) { ErrorHandler.silent(e); return false; }
  };

  const gazeteDateFromPayload = (payload) => {
    const text = normalizeGazeteText(String(payload || '').slice(0, 350000));
    const dates = new Set();
    const monthMap = Object.fromEntries(GAZETE_MONTHS_TR.map((name, i) => [normalizeGazeteText(name), i + 1]));
    let match;
    const iso = /\b(20\d{2})[-/.](\d{1,2})[-/.](\d{1,2})\b/g;
    while ((match = iso.exec(text))) {
      const y = Number(match[1]), m = Number(match[2]), d = Number(match[3]);
      if (m >= 1 && m <= 12 && d >= 1 && d <= 31) dates.add(`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`);
    }
    const numeric = /\b(\d{1,2})[./-](\d{1,2})[./-](20\d{2})\b/g;
    while ((match = numeric.exec(text))) {
      const d = Number(match[1]), m = Number(match[2]), y = Number(match[3]);
      if (m >= 1 && m <= 12 && d >= 1 && d <= 31) dates.add(`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`);
    }
    const textual = /\b(\d{1,2})\s+(ocak|subat|mart|nisan|mayis|haziran|temmuz|agustos|eylul|ekim|kasim|aralik)\s+(20\d{2})\b/g;
    while ((match = textual.exec(text))) {
      const d = Number(match[1]), m = monthMap[match[2]], y = Number(match[3]);
      if (m && d >= 1 && d <= 31) dates.add(`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`);
    }
    return [...dates].sort().at(-1) || null;
  };

  const formatGazeteDateForMessage = (isoDate) => {
    if (!isoDate || !/^\d{4}-\d{2}-\d{2}$/.test(isoDate)) return '';
    return new Date(`${isoDate}T12:00:00+03:00`).toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Istanbul' });
  };

  const fetchVerifiedGazeteManifest = async (selectedDate, signal) => {
    const sources = [
      { key: 'GazeteOku', url: 'https://www.gazeteoku.com/gazeteler', label: 'GazeteOku/Ana', minCount: 20 },
      { key: 'GZT', url: 'https://gazetemanset.gzt.com/', label: 'GZT/Ana', minCount: 20 },
      { key: 'Aydınlık', url: 'https://www.aydinlik.com.tr/gazete-mansetleri', label: 'Aydınlık/Ana', minCount: 15 },
      // v1.189: evrensel.net kendi arşivi — toplama sitelerinin CF/Turnstile engeline
      // karşı Evrensel'in KENDİ sayfası (?date= seçili tarih) kanıt kaynağı olarak
      // eklenir; yalnız kendi adını, seçili tarihlenmiş SSR ile verir (minCount: 1).
      { key: 'Evrensel/kendi', url: `https://www.evrensel.net/gazete?date=${selectedDate}`, label: 'Evrensel/kendi', minCount: 1 },
      // v1.191: BİK İlk Sayfalar — diğer kaynakların CF engeline karşı 20+ gazetenin
      // adı+tarihı SSR'de doyurulan 4. ana kaynak; alt kanıt kart-başına zorunlu.
      { key: 'BİK', url: 'https://gazete.bik.gov.tr/Uygulamalar/GazeteIlkSayfalar?kapsam=yaygin', label: 'BİK/İlkSayfalar', minCount: 15 },
      // v1.191: dijitalbasin — edition-id sabit gazete sayfaları (SSR'de publication-date
      // seçili tarih eşleşmezse ad verilmez); Pencere/Diriliş/Evrensel kapak desteği.
      { key: 'DijitalBasin/Evrensel', url: 'https://www.dijitalbasin.com/Read/331/istanbul-bahcelievler-evrensel', label: 'DijitalBasin/Evrensel', minCount: 1 },
      { key: 'DijitalBasin/Pencere', url: 'https://www.dijitalbasin.com/Read/504/istanbul-besiktas-gazete-pencere', label: 'DijitalBasin/Pencere', minCount: 1 },
      { key: 'DijitalBasin/Diriliş', url: 'https://www.dijitalbasin.com/Read/321/dirilis-postasi', label: 'DijitalBasin/Diriliş', minCount: 1 }
    ];

    // v1.188: gün-önbelleği köprüsü — doğrulama başarılıysa gateway diske yazar (POST);
    // kaynaklar sonradan bot korumasına düşerse AYNI günün kanıtlı listesi okunur (GET).
    const gatewayBase = (() => {
      try { if (typeof __OTONOM_GATEWAY__ === 'string' && __OTONOM_GATEWAY__) return String(__OTONOM_GATEWAY__).replace(/\/+$/, ''); } catch (e) {}
      return 'http://127.0.0.1:4100';
    })();
    const loadGazeteManifestCache = async (date) => {
      try {
        const res = await fetch(`${gatewayBase}/api/gazete-manifest?date=${encodeURIComponent(date)}`, { signal });
        if (!res.ok) return null;
        const data = await res.json();
        const manifest = data?.manifest;
        if (manifest?.date !== date || !Array.isArray(manifest?.names) || !manifest.names.length) return null;
        return manifest;
      } catch (e) { ErrorHandler.silent(e); return null; }
    };

    const sourceLists = new Map();
    const sourceDiagnostics = [];
    const status = [];
    const results = await Promise.allSettled(sources.map(async source => {
      const bodies = await fetchGazeteSourceTextsFast(source.url, signal, 0, {
        backendFirst: true, backendTimeoutMs: 16000
      });
      let best = [];
      let latestDate = null;
      // v1.188: Cloudflare/bot meydan okuma sayfaları gövde sayılır; gerçek
      // nedeni mesajda taşıyabilmek için ayrıca işaretlenir.
      let botBlocked = false;
      for (const body of bodies) {
        if (/just a moment|challenges\.cloudflare|attention required|cf-chl/i.test(String(body).slice(0, 4096))) botBlocked = true;
        const names = extractExactDailyManifestNames(body, selectedDate, source.key);
        if (names.length > best.length) best = names;
        const bodyDate = gazeteDateFromPayload(body);
        if (bodyDate && (!latestDate || bodyDate > latestDate)) latestDate = bodyDate;
      }
      let bodyCount = bodies.length;
      if (best.length < source.minCount && bodies.length) {
        const alternatives = await fetchGazeteSourceTextsFast(source.url, signal, 0, {
          fastRetry: true, forceFallbacks: true
        });
        bodyCount += alternatives.length;
        for (const body of alternatives) {
          if (/just a moment|challenges\.cloudflare|attention required|cf-chl/i.test(String(body).slice(0, 4096))) botBlocked = true;
          const names = extractExactDailyManifestNames(body, selectedDate, source.key);
          if (names.length > best.length) best = names;
          const bodyDate = gazeteDateFromPayload(body);
          if (bodyDate && (!latestDate || bodyDate > latestDate)) latestDate = bodyDate;
        }
      }
      return { source, names: best, bodyCount, latestDate, botBlocked };
    }));

    for (const [index, result] of results.entries()) {
      if (result.status !== 'fulfilled') {
        if (signal?.aborted) throw new DOMException('Aborted', 'AbortError');
        status.push(`${sources[index].label}:fetch-hatası`);
        sourceDiagnostics.push({ source: sources[index], bodyCount: 0, names: [], latestDate: null });
        continue;
      }
      const { source, names, bodyCount, latestDate, botBlocked } = result.value;
      sourceLists.set(source.key, names);
      sourceDiagnostics.push(result.value);
      const newestLabel = latestDate ? `;son-tarih=${latestDate}` : '';
      const botLabel = botBlocked ? '/bot-koruma' : '';
      status.push(`${source.label}:${names.length}${bodyCount ? '' : '/gövde-alınamadı'}${botLabel}${newestLabel}`);
    }

    // v1.187: Çapak (anchor) korundu — en az BIR bağımsız kaynak kendi
    // eşiğini (20/20/15) tutturur; tutturamayan kaynak VARSA süreç durur
    // (aşağıdaki hata yolu fail-closed aynen). Eşiği tutturan kaynaklarda
    // eksik kalan gazeteler ise eşiğini tutturamayan ama 3+ adı+tarih
    // kanıtlı ad üreten kısmi kaynaklardan TAMAMLANIR: her kaynak yalnız
    // kendi sayfasında kanıtlı adlarıyla katılır, kısmi kaynak artik yok
    // olmaz. Rastgele tek görsel yine kanıt sayılmaz.
    // v1.188: matine esnetmesi — bugün (TR takvimi) saat 08:00 ve sonrasında
    // tamamlama eşiği 1'e iner; geçmiş tarihlerde ve gecede yine 3 kalır. Her
    // katılan ad yine seçili tarihte kaynak sayfasında adı+tarihla kanıtlıdır.
    const GAZETE_PARTIAL_MIN_NAMES = (selectedDate === _getTurkeyDateISO() && _getTurkeyHour() >= 8) ? 1 : 3;
    const anchorSources = sources.filter(item => (sourceLists.get(item.key) || []).length >= item.minCount);
    const partialSources = sources.filter(item => {
      const count = (sourceLists.get(item.key) || []).length;
      return count > 0 && count < item.minCount && count >= GAZETE_PARTIAL_MIN_NAMES;
    });
    const contributingSources = [...anchorSources, ...partialSources];
    const names = [...new Set(contributingSources.flatMap(item => sourceLists.get(item.key) || []))].filter(name => name !== 'Yeni Akit');
    const source = contributingSources.map(item => item.key).join(' + ');

    if (!names.length) {
      const bodiesAvailable = sourceDiagnostics.filter(item => item.bodyCount > 0);
      const latestKnownDate = sourceDiagnostics.map(item => item.latestDate).filter(Boolean).sort().at(-1) || null;
      const latestLabel = latestKnownDate ? formatGazeteDateForMessage(latestKnownDate) : '';
      let cause;
      const missingSourceLabels = sourceDiagnostics.filter(item => item.bodyCount === 0).map(item => item.source.label);
      if (!bodiesAvailable.length) {
        cause = 'Hiçbir kaynaktan okunabilir sayfa gövdesi alınamadı. Gazete uzantısı etkin mi ve uzantı ayarlarında CANVAS BAĞLANTISINI ONAR çalıştırıldı mı kontrol edin.';
      } else if (sourceDiagnostics.some(item => item.botBlocked)) {
        // v1.188: gerçek neden — kaynaklar bot koruması meydan okuması döndürdü;
        // bu "yayım yok" değildir, mesaj çarpıtmasın.
        cause = `Kaynak sunucuları bot koruması (Cloudflare) meydan okuma sayfası döndürdü; ${formatGazeteDateForMessage(selectedDate)} tarihli liste bu koşuda çekilemedi. Gündüz saatlerinde engel genellikle geçicidir; kaynak sayfalarını tarayıcıda bir kez açıp doğrulamayı geçirmek bu makinenin erişimini geri getirebilir. Yanlış veya eski liste gösterilmedi.`;
      } else if (latestKnownDate && latestKnownDate < selectedDate && missingSourceLabels.length) {
        cause = `Seçilen ${formatGazeteDateForMessage(selectedDate)} tarihli sayı doğrulanamadı. Erişilebilen kaynaktaki en yeni tarih ${latestLabel}; ayrıca şu kaynakların gövdesi alınamadı: ${missingSourceLabels.join(', ')}. Bağlantıyı onarın ve yeni sayı yayımlandıktan sonra yenileyin; eski tarihli liste gösterilmedi.`;
      } else if (latestKnownDate && latestKnownDate < selectedDate) {
        cause = `Kaynakların gövdesi alındı ancak seçilen ${formatGazeteDateForMessage(selectedDate)} tarihli sayı bulunamadı. En yeni görülen kaynak tarihi ${latestLabel}. Yeni sayılar yayımlanana kadar yenileyin; eski tarihli liste gösterilmedi.`;
      } else {
        // v1.186: "Sayfalar alındı ama eşleşme yok" dalı artık kaynak başına en güncel
        // görülen tarihi açıkça raporlar: hangi kaynak seçilen tarihi yalnız başlıkta
        // taşıyıp listeyi JS ile yüklediyse, hangisi daha eski sayı gösteriyorsa net
        // ayrışır; süreç yalnız bilgilendirir ve DURUR (eski liste gösterilmez).
        const perSource = sourceDiagnostics.map(item => {
          const label = item.source?.label || item.source?.key || '?';
          const d = item.latestDate;
          if (!d) return `${label} sayfasında okunur tarih bilgisi yok`;
          if (d >= selectedDate) return `${label} ${formatGazeteDateForMessage(d)} başlıklı sayfayı sundu ancak günün gazete listesi HTML içinde adı+tarihla doğrulanamadı (liste muhtemelen JS ile yükleniyor)`;
          return `${label} en fazla ${formatGazeteDateForMessage(d)} tarihli içerik sundu`;
        }).join('; ');
        cause = `Kaynakların sayfaları alındı ancak ${formatGazeteDateForMessage(selectedDate)} tarihli sayılara henüz ulaşılamadı. Durum: ${perSource}. Gazeteler bu tarih için henüz yayımlanmamış olabilir; yayımlanır yayımlanmaz (genel olarak sabah saatleri) yenileyin. Eski veya yarım liste gösterilmedi.`;
      }
      // v1.188: canlı doğrulama başarısızsa AYNI günün önceden doğrulanmış
      // gateway önbelleği devreye girer (yalnız o tarihin kendi kanıtı; eski tarih yok).
      const cached = await loadGazeteManifestCache(selectedDate);
      if (cached?.names?.length) {
        addSystemLog(`v1.188 kaynaklardan doğrulanamadı (${status.join(' | ')}); AYNI günün önceden doğrulanmış gün-önbelleği kullanıldı: ${cached.names.length} gazete.`, 'warn');
        return { names: cached.names, source: cached.source || 'gün-önbelleği', status: [...status, 'gün-önbelleği:KULLANILDI'], sourceLists: new Map() };
      }
      throw new Error(
        `GAZETE_MANIFEST_VERIFY: ${selectedDate} günlük gazete listesi doğrulanamadı. ${cause} Kaynak durumları: ${status.join(' | ')}.`
      );
    }

    addSystemLog(`v1.138 günlük manifest (${selectedDate}): ${status.join(' | ')}; birleşim=${names.length}.`, 'info');
    // v1.188: doğrulanmış liste gateway gün-önbelleğine kaydedilir (en iyi çaba;
    // hata sessiz geçer — önbellek isteğe bağlı güçlendirme, kapı değil).
    try {
      const cacheRes = await fetch(`${gatewayBase}/api/gazete-manifest`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ date: selectedDate, names, source, status }),
      });
      if (cacheRes.ok) addSystemLog(`v1.188 gün-önbelleğine kaydedildi (${names.length} gazete; bot koruması günlerinde aynı günün kanıtıyla devam sağlanacak).`, 'info');
    } catch (e) { ErrorHandler.silent(e); }
    return { names, source, status, sourceLists };
  };

  const escapeGazeteRegExp = (value = '') => String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const extractGztDetailUrls = (payload, slug, selectedDate) => {
    const text = decodeGazeteUrl(payload);
    const urls = [];
    const [year, month, dayNum] = selectedDate.split('-');
    const exactPath = `/${slug}/${dayNum}-${month}-${year}`;
    const exactUrl = `https://gazetemanset.gzt.com${exactPath}`;

    // Yalnız seçilen tarihle eşleşen linkleri kabul et.
    const escapedPath = escapeGazeteRegExp(exactPath);
    const absolute = new RegExp(`https?:\\/\\/gazetemanset\\.gzt\\.com${escapedPath}(?:[?#][^\\s"'<>]*)?`, 'gi');
    const relative = new RegExp(`${escapedPath}(?:[?#][^\\s"'<>]*)?`, 'gi');

    for (const found of text.match(absolute) || []) if (!urls.includes(found)) urls.push(found);
    for (const found of text.match(relative) || []) {
      const full = found.startsWith('http') ? found : `https://gazetemanset.gzt.com${found}`;
      if (!urls.includes(full)) urls.push(full);
    }
    if (!urls.includes(exactUrl)) urls.push(exactUrl);
    return urls.slice(0, 3);
  };
  const extractExactGazeteHeroCandidate = (payload, pageUrl, forcedName) => {
    if (!payload || !forcedName) return null;

    const text = String(payload);
    const targetMeta = GAZETE_META[forcedName] || {};
    const aliases = [
      forcedName,
      forcedName === 'Gazete Pencere' ? 'Gazete Pencere (Online Gazete)' : '',
      forcedName === 'Analiz' ? 'Analiz Gazetesi' : ''
    ].filter(Boolean);

    const isExactName = (value = '') => {
      const detected = resolveGazeteNameFromText(value);

      // v1.78: Bilinen başka bir gazete tespit edildiyse substring fallback'e düşme.
      // Örnek: forcedName="Posta", value="Diriliş Postası" kesinlikle false olmalı.
      if (detected) return detected === forcedName;

      const norm = normalizeGazeteText(value);
      return aliases.some(alias => {
        const a = normalizeGazeteText(alias);
        return a && norm === a;
      });
    };

    const candidates = [];
    const addExact = (url, label = '') => {
      const src = cleanGazeteImageUrl(url, pageUrl);
      if (!src || !isLikelyGazeteImage(src)) return;
      if (candidates.some(c => c.src === src)) return;
      candidates.push({
        name: forcedName,
        src,
        source: label || 'ExactHero',
        alt: forcedName,
        title: forcedName,
        hint: forcedName,
        score: 1000
      });
    };

    // HTML: Aydınlık detail sayfasındaki gerçek hero image alt/title üzerinden.
    try {
      const doc = new DOMParser().parseFromString(text, 'text/html');
      doc.querySelectorAll('img,source').forEach(el => {
        const alt = el.getAttribute('alt') || '';
        const title = el.getAttribute('title') || '';
        const aria = el.getAttribute('aria-label') || '';
        if (!isExactName(`${alt} ${title} ${aria}`)) return;

        ['data-src', 'data-original', 'data-lazy-src', 'data-image', 'data-url', 'src'].forEach(attr => {
          const value = el.getAttribute(attr);
          if (value) addExact(value, 'ExactHero/HTML');
        });

        const srcset = el.getAttribute('srcset') || el.getAttribute('data-srcset') || '';
        srcset.split(',').forEach(part => {
          const value = part.trim().split(/\s+/)[0];
          if (value) addExact(value, 'ExactHero/HTML');
        });
      });
    } catch (e) {
      ErrorHandler.silent(e);
    }

    // v1.191 BİK: a.newspaper-list-item href'indeki YYN-*.jpg TAM çözünürlük kapaktır
    // (thumb img'in solundaki büyük sayfa); alt'ın "… tarihli <ad> gazetesi ilk sayfası"
    // biçimli ad+tarih kanıtı zorunlu. Aksi bir dokunuş yok.
    try {
      doc.querySelectorAll('a[href*="/first_pages/"]').forEach(link => {
        const image = link.querySelector('img');
        const alt = image?.getAttribute('alt') || '';
        if (!alt || !/tarihli/i.test(alt) || !isExactName(alt)) return;
        const href = link.getAttribute('href') || '';
        if (/gazete\.bik\.gov\.tr\/first_pages\/YYN-\d+\.jpg/i.test(href)) addExact(href, 'ExactHero/BIK');
      });
    } catch (e) { ErrorHandler.silent(e); }

    // Jina/Markdown: ![Analiz Gazetesi Manşeti](https://...)
    let match;
    const mdImage = /!\[([^\]]*)\]\((https?:\/\/[^\s)]+)(?:\s+["'][^"']*["'])?\)/gi;
    while ((match = mdImage.exec(text))) {
      if (isExactName(match[1])) addExact(match[2], 'ExactHero/Markdown');
    }

    // Last resort: storage/newspapers URL with exact newspaper slug.
    const slugTokens = [targetMeta.ayd, targetMeta.gzt, targetMeta.go]
      .filter(Boolean)
      .map(v => String(v).toLowerCase());

    const directImages = text.match(/https?:\\?\/\\?\/[A-Za-z0-9._~:/?#\[\]@!$&'()*+,;=%-]+?\.(?:jpe?g|png|webp|avif)(?:\?[A-Za-z0-9._~:/?#\[\]@!$&'()*+,;=%-]*)?/gi) || [];
    for (const raw of directImages) {
      const decoded = decodeGazeteUrl(raw).toLowerCase();
      if (slugTokens.some(slug => decoded.includes(slug)) && /newspaper|gazete|manset|storage/i.test(decoded)) {
        addExact(raw, 'ExactHero/Slug');
      }
    }

    return candidates.sort((a, b) => b.score - a.score)[0] || null;
  };

  const fetchIndividualGazeteCandidates = async (name, selectedDate, signal, options = {}) => {
    const meta = GAZETE_META[name] || {};
    const passIndex = Math.max(0, Number(options?.passIndex || 0));
    const sources = [];
    const already = new Set();

    const pushSource = (url, label, fetchOptions) => {
      if (!url || already.has(url)) return;
      already.add(url);
      sources.push({ url, label, fetchOptions });
    };

    // v1.85 STRICT SOURCE POLICY:
    // Yalnız kullanıcının verdiği üç manşet kaynağı. Önce GZT'nin tarihli detail URL'si:
    // URL'nin kendisi hem gazete slug'ını hem tarihi taşır ve en güçlü bağdır.
    if (meta.gzt) {
      pushSource(
        `https://gazetemanset.gzt.com/${meta.gzt}/${selectedDate.split('-').reverse().join('-')}`,
        'GZT/Detay'
      );
    }
    if (meta.go) {
      pushSource(`https://www.gazeteoku.com/gazeteler/${meta.go}`, 'GazeteOku/Detay');
    }
    if (meta.ayd) {
      pushSource(`https://www.aydinlik.com.tr/gazete-mansetleri/${meta.ayd}`, 'Aydınlık/Detay');
    }
    // v1.191: BİK İlk Sayfalar — kapsam=yaygin günün kartlarını SSR ile verir;
    // alt metni "GG Ay Yıl - ... tarihli <ad> gazetesi ilk sayfası" = ad+tarih kesin kanıt.
    // v1.192: BİK gövdesi yalnız gateway /proxy'den 8-9 sn'de gelir; backendFirst +
    // 16 sn penceresi olmadan rescue yolları da boşa düşer (must zaaf).
    if (meta.bik) pushSource('https://gazete.bik.gov.tr/Uygulamalar/GazeteIlkSayfalar?kapsam=yaygin', 'BİK/İlkSayfalar', { backendFirst: true, backendTimeoutMs: 16000 });
    // v1.191: dijitalbasin — Read sayfası SSR'de publication-name + publication-date
    // taşır; tarih seçili tarihe eşleşmezse kapak kurulmaz (fail-closed aynen).
    // v1.192: backendFirst ile SSR HTML en hızlı yoldan gelir (1-2 sn); markdown
    // taşımalara düşme riski kalır.
    if (meta.db) pushSource(`https://www.dijitalbasin.com/Read/${meta.db}`, 'DijitalBasin/Read', { backendFirst: true, backendTimeoutMs: 16000 });

    const candidates = [];
    for (const source of sources) {
      if (signal?.aborted) break;

      const texts = await fetchGazeteSourceTextsFast(source.url, signal, passIndex, {
        fastRetry: !!options?.fastRetry,
        forceFallbacks: source.label === 'GZT/Detay',
        // v1.192: BİK/DijitalBasin kaynakları backend'i ÖNCE kullanır (hızlı ve
        // gerçek SSR HTML); diğer kaynaklar eski davranışı korur.
        backendFirst: source.fetchOptions?.backendFirst === true,
        backendTimeoutMs: source.fetchOptions?.backendTimeoutMs || undefined
      });

      for (const body of texts) {
        // URL tarihli olsa bile 404/fallback sayfası başka güne dönebilir.
        // Bu nedenle gövde de aynı tarihi açıkça doğrulamak zorunda.
        if (!gazetePayloadMatchesDate(body, selectedDate)) continue;

        // v1.191: dijitalbasin Read sayfası HTML img etiketi taşımaz; bugünün kapak
        // görseli GetPublicationDisplay endpoint'indendir. SSR'de publication-name
        // (gazete adı) + publication-date (seçili tarih) kesin doğrulanırsa kur.
        if (meta.db && source.label === 'DijitalBasin/Read' && dijitalBasinReadVerified(body, name, selectedDate)) {
          const publicationId = String(meta.db).split('/')[0];
          candidates.push({
            name,
            src: `https://www.dijitalbasin.com/PublicationsDocument/GetPublicationDisplay?publicationId=${publicationId}`,
            source: source.label,
            alt: name,
            title: name,
            hint: name,
            score: 1000,
            verifiedDate: selectedDate,
            verifiedName: name
          });
          addSystemLog(`✓ ${name}: ${selectedDate} gerçek kapak ${source.label} ile AD+TARİH kesin doğrulandı.`, 'success');
          break;
        }

        const exactHero = extractExactGazeteHeroCandidate(body, source.url, name);
        if (exactHero) {
          candidates.push({ ...exactHero, verifiedDate: selectedDate, verifiedName: name });
          addSystemLog(`✓ ${name}: ${selectedDate} gerçek kapak ${source.label} ile AD+TARİH kesin doğrulandı.`, 'success');
          break;
        }

        // Exact hero markup değişmişse yalnız forcedName güçlü bağ filtresini geçen adaylar.
        const extracted = extractGazeteCandidates(body, source.url, source.label, name)
          .map(candidate => ({ ...candidate, verifiedDate: selectedDate, verifiedName: name }));
        candidates.push(...extracted);
      }

      if (candidates.length) break;
    }

    const seen = new Set();
    return candidates
      .filter(candidate =>
        candidate.src &&
        candidate.verifiedName === name &&
        candidate.verifiedDate === selectedDate &&
        !seen.has(candidate.src) &&
        seen.add(candidate.src)
      )
      .sort((a, b) => (b.score || 0) - (a.score || 0));
  };

  const prependLiveGazeteCandidates = (item, candidates) => {
    const rawUrls = candidates.map(candidate => candidate.src).filter(Boolean);
    if (!rawUrls.length) return item;

    const variants = createGazeteVariants([...rawUrls, ...(item.rawCandidates || [])]);
    const sources = uniqueGazeteUrls([...(item.sources || []), ...candidates.map(candidate => candidate.source)]);

    // KRİTİK:
    // Eski kartta yüklenmiş beyaz "Aydınlık" fallback'i resolvedThumb/resolvedFull
    // olarak kalmış olabilir. Yeni DOĞRULANMIŞ kapak geldiğinde onu kesin temizle.
    // JSX resolvedThumb || thumbSrc kullandığı için temizlenmezse gerçek kapak
    // bulunmasına rağmen ekranda eski yanlış görsel kalıyordu.
    return {
      ...item,
      ...variants,
      resolvedFull: '',
      resolvedThumb: '',
      fullCandidates: [...variants.fullCandidates, item.placeholder],
      thumbCandidates: [...variants.thumbCandidates, item.placeholder],
      fullSrc: variants.fullCandidates[0] || item.fullSrc,
      thumbSrc: variants.thumbCandidates[0] || item.thumbSrc,
      sources,
      loaded: false,
      verified: true,
      verifiedDate: item.requestedDate,
      revision: (item.revision || 0) + 1
    };
  };

  // ===== v1.193: ELLE KAPAK YÜKLEME =====
  // Kullanıcı, sistemin çekemediği gazeteye kendi kapak görselini yükler; kart
  // diğerleri gibi akış/karşılaştırma/crop kullanır. Kapak IndexedDB'ye
  // AssetManagerService.saveMedia ile kalıcı yazılır (localStorage dataURL yasağı
  // aynen: GAZETE_CACHE yalnız uzak URL'ler tutar). Fail-closed dürüstlüğü:
  // source etiketi 'Elle/Yükleme' — sistem bu kapağı "kaynakta doğrulanmış" demez.
  const gazeteManualMediaId = (date, name) => `GAZETE_MANUAL_${String(date || '').replace(/[^0-9-]/g, '')}_${normalizeGazeteText(name)}`;
  const applyManualGazeteCover = (item, dataUrl) => ({
    ...item,
    fullCandidates: [dataUrl, ...uniqueGazeteUrls(item.fullCandidates || []).filter(url => url !== dataUrl)],
    thumbCandidates: [dataUrl, ...uniqueGazeteUrls(item.thumbCandidates || []).filter(url => url !== dataUrl)],
    rawCandidates: [dataUrl, ...uniqueGazeteUrls(item.rawCandidates || []).filter(url => url !== dataUrl)],
    fullSrc: dataUrl,
    thumbSrc: dataUrl,
    resolvedFull: '',
    resolvedThumb: '',
    sources: uniqueGazeteUrls([...(item.sources || []), 'Elle/Yükleme']),
    manualCover: true,
    loaded: false,
    verified: true,
    verifiedDate: item.requestedDate,
    revision: (item.revision || 0) + 1
  });
  const hydrateManualGazeteCovers = async (items) => {
    if (!Array.isArray(items) || !items.length) return;
    for (const item of items) {
      try {
        const stored = await AssetManagerService.loadMedia(gazeteManualMediaId(item.requestedDate, item.name));
        if (!stored) continue;
        setGazeteItems(prev => prev.map(it => (
          it.name === item.name && it.requestedDate === item.requestedDate && !(it.manualCover && it.thumbSrc === stored)
            ? applyManualGazeteCover(it, stored)
            : it
        )));
      } catch (e) { ErrorHandler.silent(e); }
    }
  };
  const handleManualGazeteCoverUpload = async (name) => {
    if (!name) return;
    const item = (gazeteItemsRef.current || []).find(entry => entry.name === name);
    if (!item) { addSystemLog(`✗ ${name}: kart bulunamadı; kapak yüklenmedi.`, 'error'); return; }
    const input = gazeteManualCoverInputRef.current;
    if (!input) return;
    gazeteManualUploadTargetRef.current = name;
    input.value = '';
    input.click();
  };
  const handleGazeteManualCoverFile = async (event) => {
    const name = gazeteManualUploadTargetRef.current;
    const file = event.target.files?.[0];
    if (!name || !file) return;
    if (!file.type || !file.type.startsWith('image/')) {
      addSystemLog(`✗ ${name}: kapak yüklemesi reddedildi — dosya görsel değil (${file.type || 'bilinmiyor'}).`, 'error');
      return;
    }
    if (file.size < 8 * 1024) {
      addSystemLog(`✗ ${name}: kapak yüklemesi reddedildi — görsel okunamayacak kadar küçük (${Math.round(file.size / 1024)} KB).`, 'error');
      return;
    }
    if (file.size > 12 * 1024 * 1024) {
      addSystemLog(`✗ ${name}: kapak yüklemesi reddedildi — dosya 12 MB sınırını aşıyor (${Math.round(file.size / 1024 / 1024)} MB).`, 'error');
      return;
    }
    try {
      const dataUrl = await NetworkUtils.compressImage(file);
      if (!dataUrl || !dataUrl.startsWith('data:image/')) throw new Error('görsel dataURL üretilemedi');
      const item = (gazeteItemsRef.current || []).find(entry => entry.name === name);
      const date = item?.requestedDate || gazeteDate || _getTurkeyDateISO();
      await AssetManagerService.saveMedia(gazeteManualMediaId(date, name), dataUrl);
      setGazeteItems(prev => prev.map(entry => entry.name === name ? applyManualGazeteCover(entry, dataUrl) : entry));
      addSystemLog(`✓ ${gazeteDisplayName(name)}: kapak elle yüklendi (${formatGazeteDateForMessage(date)}) ve IndexedDB'ye saklandı; akış/karşılaştırma bu kapağı kullanacak.`, 'success');
    } catch (e) {
      ErrorHandler.log(e, `${name} elle kapak yükleme`);
      addSystemLog(`✗ ${name}: kapak yüklenemedi (${e?.message || e}).`, 'error');
    }
  };
  const stopGazeteBackgroundRetry = () => {
    const state = gazeteBackgroundRetryRef.current;
    if (state?.timer) {
      clearTimeout(state.timer);
    }
    gazeteBackgroundRetryRef.current = { timer: null, running: false, requestId: 0, date: '', pending: [], pass: 0 };
  };

  const scheduleGazeteBackgroundRetry = (names, selectedDate, requestId, initialDelayMs = 0) => {
    const incoming = [...new Set((names || []).filter(isGazeteHardRetryTarget))];
    if (!incoming.length) return;

    const current = gazeteBackgroundRetryRef.current;
    const sameJob = current.requestId === requestId && current.date === selectedDate;
    const mergedPending = [...new Set([...(sameJob ? current.pending : []), ...incoming])];

    if (!sameJob && current?.timer) clearTimeout(current.timer);
    gazeteBackgroundRetryRef.current = {
      timer: sameJob ? current.timer : null,
      running: sameJob ? current.running : false,
      requestId,
      date: selectedDate,
      pending: mergedPending,
      pass: sameJob ? current.pass : 0
    };

    const arm = (delayMs) => {
      const state = gazeteBackgroundRetryRef.current;
      if (state.requestId !== requestId || state.date !== selectedDate || !state.pending.length) return;
      if (state.timer || state.running) return;
      state.timer = setTimeout(async () => {
        const live = gazeteBackgroundRetryRef.current;
        live.timer = null;
        if (live.requestId !== requestId || live.date !== selectedDate || live.running || !live.pending.length) return;
        if (requestId !== gazeteRequestIdRef.current || gazeteAbortRef.current?.signal?.aborted) return;

        live.running = true;
        live.pass += 1;
        const pass = live.pass;
        const pendingNow = [...live.pending];
        addSystemLog(`Gazete arka plan kontrolü ${pass}: ${pendingNow.join(', ')}`, 'info');

        try {
          const results = await Promise.allSettled(
            pendingNow.map(async name => ({
              name,
              candidates: await fetchIndividualGazeteCandidates(
                name,
                selectedDate,
                gazeteAbortRef.current?.signal,
                { passIndex: pass, fastRetry: true }
              )
            }))
          );

          if (requestId !== gazeteRequestIdRef.current || gazeteAbortRef.current?.signal?.aborted) return;

          const newlyFound = new Map();
          for (const result of results) {
            if (result.status === 'fulfilled' && result.value?.candidates?.length) {
              newlyFound.set(result.value.name, result.value.candidates);
            }
          }

          if (newlyFound.size) {
            setGazeteItems(prev => prev.map(item =>
              newlyFound.has(item.name) ? prependLiveGazeteCandidates(item, newlyFound.get(item.name)) : item
            ));
            live.pending = live.pending.filter(name => !newlyFound.has(name));
            addSystemLog(`✓ Gazete arka planında bulunanlar: ${[...newlyFound.keys()].join(', ')}`, 'success');
          }
        } catch (e) {
          if (e?.name !== 'AbortError') ErrorHandler.silent(e);
        } finally {
          const latest = gazeteBackgroundRetryRef.current;
          if (latest.requestId !== requestId || latest.date !== selectedDate) return;
          latest.running = false;
          if (!latest.pending.length) {
            addSystemLog('✓ Kritik gazete arka plan kontrolü tamamlandı; eksik kritik gazete kalmadı.', 'success');
            return;
          }
          const delayIndex = Math.min(latest.pass, GAZETE_BACKGROUND_RETRY_DELAYS_MS.length - 1);
          const nextDelay = GAZETE_BACKGROUND_RETRY_DELAYS_MS[delayIndex];
          addSystemLog(`Gazete arka planı bekliyor: ${latest.pending.join(', ')} → ${Math.round(nextDelay / 1000)} sn sonra tekrar kontrol.`, 'info');
          arm(nextDelay);
        }
      }, Math.max(0, Number(delayMs) || 0));
    };

    arm(initialDelayMs);
  };

  const rescueGazeteItem = async (name) => {
    const key = `${gazeteDate}|${name}`;
    if (gazeteRescueInFlightRef.current.has(key)) return gazeteRescueInFlightRef.current.get(key);
    const requestId = gazeteRequestIdRef.current;
    const signal = gazeteAbortRef.current?.signal;
    const promise = (async () => {
      try {
        const candidates = await fetchIndividualGazeteCandidates(name, gazeteDate, signal, { passIndex: 1, fastRetry: true });
        if (candidates.length && requestId === gazeteRequestIdRef.current && !signal?.aborted) {
          setGazeteItems(prev => prev.map(item => item.name === name ? prependLiveGazeteCandidates(item, candidates) : item));
          addSystemLog(`✓ ${name}: hızlı rescue ile kapak bulundu.`, 'success');
          return true;
        }
        if (isGazeteHardRetryTarget(name) && requestId === gazeteRequestIdRef.current && !signal?.aborted) {
          scheduleGazeteBackgroundRetry([name], gazeteDate, requestId, 15000);
        }
        return false;
      } catch (e) {
        if (e?.name !== 'AbortError') ErrorHandler.silent(e);
        return false;
      } finally {
        gazeteRescueInFlightRef.current.delete(key);
      }
    })();
    gazeteRescueInFlightRef.current.set(key, promise);
    return promise;
  };

  const fetchGazeteManşetleri = async (forcedDate = null) => {
    stopGazeteBackgroundRetry();
    const requestId = ++gazeteRequestIdRef.current;
    gazeteRefreshNonceRef.current = `${_getTurkeyDateISO()}-${Date.now()}-${requestId}`;
    gazeteResolvedCacheRef.current = null;
    gazeteCentralReadyRef.current = false;

    if (gazeteAbortRef.current) gazeteAbortRef.current.abort();
    const controller = new AbortController();
    gazeteAbortRef.current = controller;
    gazeteRescueInFlightRef.current.clear();

    setGazeteLoading(true);
    setGazeteError('');
    setGazeteCurrentIdx(0);

    const selectedDate = forcedDate || gazeteDate || _getTurkeyDateISO();

    try {
      // 1) Önce BUGÜN HANGİ GAZETELER VAR sorusunu kaynaktan doğrula.
      // Sabit master listeyi ekrana basmak YASAK.
      const manifest = await fetchVerifiedGazeteManifest(selectedDate, controller.signal);
      if (requestId !== gazeteRequestIdRef.current || controller.signal.aborted) return;

      const activeNames = stableGazeteOrder(manifest.names);
      addSystemLog(`Gazete sırası sabitlendi: doğrulanan kaynak listesi ${activeNames.length} gazeteyi ana sıralama listesine göre dizdi.`, 'info');
      const cards = buildGazeteCards(selectedDate, activeNames);
      setGazeteItems(cards);
      // v1.193: kullanıcının daha önce elle yüklediği kapaklar (IndexedDB'den)
      // kartlara geri yüklenir — yenilemeden sonra da sürdürülmüş olur.
      hydrateManualGazeteCovers(cards);

      addSystemLog(
        `✓ v1.87 EXACT MANIFEST: ${selectedDate} için ${activeNames.length} gazete ${manifest.source} günlük listelerinden doğrulandı. ` +
        `Kartlar önce placeholder açıldı; yanlış/tahmini kapak gösterilmeyecek.`,
        'success'
      );

      // Manifest tamamlandıktan sonra rescue çalışabilir.
      gazeteCentralReadyRef.current = true;

      // 2) Her gazetenin kapağını yalnız exact detail sayfasından doğrula.
      // 30 isteği tek anda patlatmak yerine 6'lı batch: doğru ve daha kararlı.
      const found = new Map();
      const BATCH_SIZE = 6;

      for (let offset = 0; offset < activeNames.length; offset += BATCH_SIZE) {
        if (controller.signal.aborted || requestId !== gazeteRequestIdRef.current) return;
        const batch = activeNames.slice(offset, offset + BATCH_SIZE);
        const results = await Promise.allSettled(batch.map(async name => ({
          name,
          candidates: await fetchIndividualGazeteCandidates(name, selectedDate, controller.signal)
        })));

        for (const result of results) {
          if (result.status === 'fulfilled' && result.value.candidates.length) {
            found.set(result.value.name, result.value.candidates);
          }
        }

        if (found.size) {
          setGazeteItems(prev => prev.map(item =>
            found.has(item.name) ? prependLiveGazeteCandidates(item, found.get(item.name)) : item
          ));
        }

        addSystemLog(
          `Gazete doğrulama: ${Math.min(offset + batch.length, activeNames.length)}/${activeNames.length} kontrol edildi, ` +
          `${found.size} kapak AD+TARİH doğrulandı.`,
          'info'
        );
      }

      if (requestId !== gazeteRequestIdRef.current || controller.signal.aborted) return;

      const unresolved = activeNames.filter(name => !found.has(name));
      const hardRetryNames = unresolved.filter(isGazeteHardRetryTarget);
      if (hardRetryNames.length) {
        scheduleGazeteBackgroundRetry(hardRetryNames, selectedDate, requestId, 15000);
      }

      if (unresolved.length) {
        unresolved.forEach(name => {
          addSystemLog(
            `DOĞRULANMADI: ${name} — ${selectedDate}. Yanlış/eski kapak yerine placeholder bırakıldı.`,
            'warn'
          );
        });
        addSystemLog(
          `Gazete sonucu: ${found.size}/${activeNames.length} kapak kesin doğrulandı. ` +
          `Doğrulanamayanlar ekranda yanlış görselle doldurulmadı: ${unresolved.join(', ')}.`,
          'warn'
        );
      } else {
        addSystemLog(
          `✓ Gazete sonucu: ${found.size}/${activeNames.length} gazetenin adı+tarihi+kapağı kesin doğrulandı.`,
          'success'
        );
      }
    } catch (e) {
      if (e?.name !== 'AbortError') {
        setGazeteItems([]);
        setGazeteError(
          `Gazete listesi doğrulanamadı: ${e?.message || e}. Yanlış liste göstermemek için sonuçlar temizlendi.`
        );
        addSystemLog('Gazete doğrulama hatası: ' + (e?.message || e), 'error');
      }
    } finally {
      if (requestId === gazeteRequestIdRef.current) setGazeteLoading(false);
    }
  };

  const handleGazeteImageError = (event, item, kind = 'thumb') => {
    const image = event.currentTarget;
    const list = kind === 'full' ? (item?.fullCandidates || []) : (item?.thumbCandidates || []);
    const indexKey = kind === 'full' ? 'gazeteFullIndex' : 'gazeteThumbIndex';
    const nextIndex = Number(image.dataset[indexKey] || 0) + 1;
    if (nextIndex < list.length) { image.dataset[indexKey] = String(nextIndex); image.src = list[nextIndex]; return; }
    image.src = item?.placeholder || makeGazetePlaceholder(item?.name || 'Gazete');
    image.style.opacity = '0.65';
    if (gazeteCentralReadyRef.current && image.dataset.gazeteRescue !== '1') {
      image.dataset.gazeteRescue = '1';
      rescueGazeteItem(item?.name);
    }
  };
  const handleGazeteImageLoad = (event, item, kind = 'thumb') => {
    const image = event.currentTarget;
    const current = image.currentSrc || image.src;
    if (!item || !current) return;

    // Placeholder HTTP 200 gibi "başarıyla" yüklenebilir.
    // Gerçek kapak sayma; yalnız bu gazeteyi hedefli kurtar.
    if (current.startsWith('data:image/') || current === item.placeholder) {
      image.style.opacity = '0.62';

      // İlk merkez taraması devam ederken rescue başlatma.
      // Merkez tarama zaten bütün gazeteleri tek seferde çözmeye çalışıyor.
      if (gazeteCentralReadyRef.current && image.dataset.gazeteRescue !== '1') {
        image.dataset.gazeteRescue = '1';
        rescueGazeteItem(item.name);
      }
      return;
    }

    // 1.14 regresyonundaki gibi boyut/aspect kontrolü YOK.
    // Görüntü yüklendiyse çalışana dokunma.
    image.style.opacity = '1';
    const cacheField = kind === 'full' ? 'full' : 'thumb';
    persistGazeteResolution(gazeteDate, item.name, cacheField, current);

    // React state nesnesini burada doğrudan MUTATE ETME.
    // Önceki sürümde bu, sonradan gelen gerçek kapağın stale resolvedThumb
    // tarafından ezilmesine yol açıyordu.
  };
  const addGazeteToCustomSceneImages = async (dataUrl, gazeteName) => {
    try {
      const updatedImages = [...(studioMedia.customSceneImages || []), dataUrl].slice(0, RENDER_CONFIG.MAX_CUSTOM_SCENE_IMAGES);
      for (let i = 0; i < updatedImages.length; i++) await AssetManagerService.saveMedia("CUSTOM_SCENE_IMG_" + i, updatedImages[i]);
      setStudioMedia(s => ({ ...s, customSceneImages: updatedImages }));
      addSystemLog(`✓ Sabit Görsel'e yüklendi: ${gazeteName}`, 'success');
    } catch (e) { addSystemLog('Sabit Görsel ekleme uyarısı: ' + e.message, 'warn'); }
  };
  const matchOrFormatGazeteName = (rawName) => {
    if (!rawName) return '';

    // v1.78: Gazete adı eşleştirmesinde substring kullanma.
    // "Posta" ile "Diriliş Postası" ayrı gazetelerdir; kısa ad uzun adın içinde
    // geçiyor diye eşleşme yapılmamalıdır.
    const rawText = String(rawName).trim();
    const rawNormalized = normalizeGazeteText(rawText);
    if (rawNormalized) {
      const exact = GAZETE_MASTER_LIST.find(name => normalizeGazeteText(name) === rawNormalized);
      if (exact) return exact;

      const resolved = resolveGazeteNameFromText(rawText);
      if (resolved) return resolved;
    }

    const cleaned = rawText
      .replace(/(_crop|\.png|\.jpg|\.jpeg|gazetesi|manşet)/gi, ' ')
      .replace(/[0-9_-]+/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    if (cleaned) {
      const cleanedNormalized = normalizeGazeteText(cleaned);
      const exactCleaned = GAZETE_MASTER_LIST.find(name => normalizeGazeteText(name) === cleanedNormalized);
      if (exactCleaned) return exactCleaned;

      const resolvedCleaned = resolveGazeteNameFromText(cleaned);
      if (resolvedCleaned) return resolvedCleaned;
    }

    if (!cleaned) return rawText;
    return cleaned.split(/\s+/).map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
  };
  const openCropModal = useCallback((src, name) => {
    const finalName = matchOrFormatGazeteName(name) || name;
    setConfig(prev => ({ ...prev, sourceName: finalName }));
    setGazeteCropModal({ src, name: finalName });
  }, []);
  const applyCrop = useCallback(async (cropDataUrl, gazeteName) => {
    const finalName = matchOrFormatGazeteName(gazeteName) || gazeteName;
    const newFile = { name: finalName + '_crop.png', type: 'image/png', data: cropDataUrl };
    setUiState(prev => ({ ...prev, selectedMediaFiles: [...(prev.selectedMediaFiles || []), newFile] }));
    setConfig(prev => ({ ...prev, sourceName: finalName }));
    await addGazeteToCustomSceneImages(cropDataUrl, finalName);
    setGazeteCropModal(null);
    setActiveTab('media');
    addSystemLog(`✓ Gazete crop eklendi, Kaynak otomatik seçildi: ${finalName}`, 'success');
  }, [studioMedia]);
  const gazeteBlobToDataUrl = (blob) => new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error || new Error('Gazete görseli DataURL dönüşümü başarısız.'));
    reader.readAsDataURL(blob);
  });

  const gazeteLoadBitmap = async (blob) => {
    if (typeof createImageBitmap === 'function') {
      try {
        const bitmap = await createImageBitmap(blob);
        return {
          image: bitmap,
          width: bitmap.width,
          height: bitmap.height,
          close: () => { try { bitmap.close(); } catch (e) {} }
        };
      } catch (e) { ErrorHandler.silent(e); }
    }

    const objectUrl = URL.createObjectURL(blob);
    try {
      const img = await new Promise((resolve, reject) => {
        const el = new Image();
        el.onload = () => resolve(el);
        el.onerror = () => reject(new Error('Gazete görsel ölçüsü okunamadı.'));
        el.src = objectUrl;
      });
      return {
        image: img,
        width: img.naturalWidth || img.width,
        height: img.naturalHeight || img.height,
        close: () => {}
      };
    } finally {
      URL.revokeObjectURL(objectUrl);
    }
  };

  const gazeteIsPortraitPage = (width, height) => {
    if (!width || !height) return false;
    const ratio = width / height;
    // Türkiye gazete kapaklarında güvenli portre aralığı.
    return height > width && ratio >= 0.38 && ratio <= 0.88;
  };

  const gazeteAutoCropPortrait = async (blob, gazeteName = 'Gazete') => {
    let loaded = null;
    try {
      loaded = await gazeteLoadBitmap(blob);
      const sw = loaded.width;
      const sh = loaded.height;
      if (!sw || !sh) return null;

      const analysisMax = 420;
      const scale = Math.min(1, analysisMax / Math.max(sw, sh));
      const aw = Math.max(40, Math.round(sw * scale));
      const ah = Math.max(40, Math.round(sh * scale));

      const analysisCanvas = document.createElement('canvas');
      analysisCanvas.width = aw;
      analysisCanvas.height = ah;
      const actx = analysisCanvas.getContext('2d', { willReadFrequently: true });
      actx.drawImage(loaded.image, 0, 0, aw, ah);

      const pixels = actx.getImageData(0, 0, aw, ah).data;
      const sampleSize = Math.max(3, Math.round(Math.min(aw, ah) * 0.035));

      const sampleCorner = (sx, sy) => {
        let r = 0, g = 0, b = 0, n = 0;
        for (let y = sy; y < Math.min(ah, sy + sampleSize); y++) {
          for (let x = sx; x < Math.min(aw, sx + sampleSize); x++) {
            const i = (y * aw + x) * 4;
            r += pixels[i]; g += pixels[i + 1]; b += pixels[i + 2]; n++;
          }
        }
        return n ? [r / n, g / n, b / n] : [0, 0, 0];
      };

      const corners = [
        sampleCorner(0, 0),
        sampleCorner(Math.max(0, aw - sampleSize), 0),
        sampleCorner(0, Math.max(0, ah - sampleSize)),
        sampleCorner(Math.max(0, aw - sampleSize), Math.max(0, ah - sampleSize))
      ];

      const bg = [
        corners.reduce((s, c) => s + c[0], 0) / corners.length,
        corners.reduce((s, c) => s + c[1], 0) / corners.length,
        corners.reduce((s, c) => s + c[2], 0) / corners.length
      ];

      const bgLum = (bg[0] + bg[1] + bg[2]) / 3;
      const colorThreshold = bgLum < 75 ? 48 : (bgLum > 185 ? 56 : 64);

      const colHits = new Uint32Array(aw);
      const rowHits = new Uint32Array(ah);

      for (let y = 0; y < ah; y++) {
        for (let x = 0; x < aw; x++) {
          const i = (y * aw + x) * 4;
          if (pixels[i + 3] < 40) continue;

          const dr = pixels[i] - bg[0];
          const dg = pixels[i + 1] - bg[1];
          const db = pixels[i + 2] - bg[2];
          const dist = Math.sqrt(dr * dr + dg * dg + db * db);

          if (dist > colorThreshold) {
            colHits[x]++;
            rowHits[y]++;
          }
        }
      }

      const minColHits = Math.max(2, Math.round(ah * 0.018));
      const minRowHits = Math.max(2, Math.round(aw * 0.018));

      let left = 0, right = aw - 1, top = 0, bottom = ah - 1;

      while (left < right && colHits[left] < minColHits) left++;
      while (right > left && colHits[right] < minColHits) right--;
      while (top < bottom && rowHits[top] < minRowHits) top++;
      while (bottom > top && rowHits[bottom] < minRowHits) bottom--;

      let bw = right - left + 1;
      let bh = bottom - top + 1;

      if (bw < aw * 0.05 || bh < ah * 0.12) return null;

      // Biraz güvenli pay bırak.
      const padX = Math.round(bw * 0.04);
      const padY = Math.round(bh * 0.025);
      left = Math.max(0, left - padX);
      right = Math.min(aw - 1, right + padX);
      top = Math.max(0, top - padY);
      bottom = Math.min(ah - 1, bottom + padY);

      bw = right - left + 1;
      bh = bottom - top + 1;

      // Otomatik bulunan alan gazete gibi portre değilse kırpma yapma.
      if (!gazeteIsPortraitPage(bw, bh)) return null;

      const sx = Math.max(0, Math.round((left / aw) * sw));
      const sy = Math.max(0, Math.round((top / ah) * sh));
      const cropW = Math.min(sw - sx, Math.max(1, Math.round((bw / aw) * sw)));
      const cropH = Math.min(sh - sy, Math.max(1, Math.round((bh / ah) * sh)));

      const outCanvas = document.createElement('canvas');
      // Orijinal çözünürlüğü koru; aşırı büyükse 1800 yüksekliğe sınırla.
      const maxH = 1800;
      const outScale = Math.min(1, maxH / cropH);
      outCanvas.width = Math.max(1, Math.round(cropW * outScale));
      outCanvas.height = Math.max(1, Math.round(cropH * outScale));

      const octx = outCanvas.getContext('2d');
      octx.imageSmoothingEnabled = true;
      octx.imageSmoothingQuality = 'high';
      octx.drawImage(
        loaded.image,
        sx, sy, cropW, cropH,
        0, 0, outCanvas.width, outCanvas.height
      );

      const result = outCanvas.toDataURL('image/jpeg', 0.97);
      addSystemLog(
        `✓ ${gazeteName}: yatay/boşluklu kaynak içinden gazete sayfası otomatik kırpıldı (${cropW}x${cropH} → ${outCanvas.width}x${outCanvas.height}).`,
        'success'
      );
      return result;
    } catch (e) {
      ErrorHandler.silent(e);
      return null;
    } finally {
      try { loaded?.close?.(); } catch (e) {}
    }
  };

  const gazeteCorsSafeImageUrl = (src, width = 1800, quality = 96) => {
    if (!src) return '';
    if (String(src).startsWith('data:image/') || String(src).startsWith('blob:')) return src;

    // Zaten weserv ise tekrar proxy içine sarma.
    try {
      const u = new URL(src);
      if (u.hostname === 'images.weserv.nl') return src;
    } catch (e) {}

    const clean = decodeGazeteUrl(src);
    return `https://images.weserv.nl/?url=${encodeURIComponent(clean)}&w=${width}&fit=contain&we=1&output=jpg&q=${quality}&sharp=1`;
  };

  const gazeteImageToDataUrl = async (srcOrList, gazeteName = 'Gazete', externalSignal = null, options = {}) => {
    const inputList = Array.isArray(srcOrList) ? srcOrList : [srcOrList];
    const rawList = uniqueGazeteUrls(inputList.filter(Boolean));

    if (!rawList.length) throw new Error(`Gerçek gazete kapağı bulunamadı: ${gazeteName}`);

    const candidates = [];
    for (const raw of rawList) {
      if (!raw) continue;

      if (String(raw).startsWith('data:image/')) {
        candidates.push({ url: raw, kind: 'data' });
        continue;
      }

      if (String(raw).startsWith('blob:')) {
        candidates.push({ url: raw, kind: 'blob' });
        continue;
      }

      candidates.push({ url: gazeteCorsSafeImageUrl(raw, 1800, 96), kind: 'weserv-1800' });
      candidates.push({ url: gazeteCorsSafeImageUrl(raw, 1400, 94), kind: 'weserv-1400' });
      candidates.push({ url: raw, kind: 'raw' });
    }

    const deduped = [];
    const seen = new Set();
    for (const c of candidates) {
      if (!c.url || seen.has(c.url)) continue;
      seen.add(c.url);
      deduped.push(c);
    }

    let lastError = null;
    let bestFallback = null;

    for (const candidate of deduped) {
      if (externalSignal?.aborted) throw new Error(`${gazeteName}: görsel toplama zaman aşımına uğradı/iptal edildi.`);
      const url = candidate.url;

      try {
        let blob;

        if (String(url).startsWith('data:image/')) {
          const response = await fetch(url, { signal: externalSignal || undefined });
          blob = await response.blob();
        } else if (String(url).startsWith('blob:')) {
          const response = await fetch(url, { signal: externalSignal || undefined });
          blob = await response.blob();
        } else {
          const controller = new AbortController();
          const abortFromParent = () => controller.abort();
          if (externalSignal?.aborted) controller.abort();
          else externalSignal?.addEventListener('abort', abortFromParent, { once: true });
          // v1.152: Yorumla için daha kısa aday zaman aşımı; diğer mevcut akışların 15 sn davranışı korunur.
          // Uzun bir proxy adayı süreyi tüketmeden sonraki doğrulanmış kaynak yedeğine geçilebilir.
          const candidateTimeoutMs = options?.fastCandidateFallback
            ? (candidate.kind.startsWith('weserv') ? 9000 : 11000)
            : 15000;
          const timer = setTimeout(() => controller.abort(), candidateTimeoutMs);
          let response;
          try {
            response = await fetch(url, {
              method: 'GET',
              cache: 'no-store',
              mode: 'cors',
              credentials: 'omit',
              signal: controller.signal
            });
          } finally {
            clearTimeout(timer);
            try { externalSignal?.removeEventListener('abort', abortFromParent); } catch (_) {}
          }

          if (!response.ok) {
            lastError = new Error(`${candidate.kind}: HTTP ${response.status}`);
            continue;
          }

          const contentType = (response.headers.get('content-type') || '').toLowerCase();
          blob = await response.blob();

          if (!(contentType.startsWith('image/') || String(blob.type || '').startsWith('image/'))) {
            lastError = new Error(`${candidate.kind}: görsel olmayan yanıt (${contentType || blob.type || 'bilinmiyor'})`);
            continue;
          }
        }

        if (!blob || !blob.size) {
          lastError = new Error(`${candidate.kind}: boş görsel`);
          continue;
        }

        let loaded = null;
        try {
          loaded = await gazeteLoadBitmap(blob);
          const iw = loaded.width;
          const ih = loaded.height;
          const ratio = iw && ih ? (iw / ih) : 0;

          addSystemLog(
            `${gazeteName}: video kapak adayı ${candidate.kind} ${iw}x${ih}${ratio ? ` (oran ${ratio.toFixed(2)})` : ''}.`,
            'info'
          );

          // GERÇEK gazete sayfası: portre aday doğrudan kabul edilir.
          if (gazeteIsPortraitPage(iw, ih)) {
            const dataUrl = await gazeteBlobToDataUrl(blob);
            addSystemLog(
              `✓ ${gazeteName}: gerçek portre gazete kapağı videoya seçildi (${candidate.kind}, ${iw}x${ih}, ${(blob.size / 1024).toFixed(0)}KB).`,
              'success'
            );
            return dataUrl;
          }

          // Yatay/preview görseli doğrudan kabul ETME.
          // Daha iyi portre aday olabilir; yedek olarak sakla.
          const area = iw * ih;
          const closeness = ratio > 0 ? Math.abs(ratio - 0.62) : 99;
          const score = (area / 1000000) - (closeness * 2.5);

          if (!bestFallback || score > bestFallback.score) {
            bestFallback = { blob, kind: candidate.kind, width: iw, height: ih, score };
          }
        } finally {
          try { loaded?.close?.(); } catch (e) {}
        }
      } catch (e) {
        lastError = e;
        ErrorHandler.silent(e);
      }
    }

    // Hiç portre kaynak bulunamazsa, en iyi yatay kaynaktaki gazete sayfasını
    // otomatik bulup kırp. Böylece videoda küçücük gazete kalmaz.
    if (bestFallback?.blob) {
      const cropped = await gazeteAutoCropPortrait(bestFallback.blob, gazeteName);
      if (cropped) return cropped;

      addSystemLog(
        `${gazeteName}: portre kapak bulunamadı; son yatay aday (${bestFallback.width}x${bestFallback.height}) video için reddedildi.`,
        'warn'
      );
    }

    throw new Error(
      `Gazete kapağı videoya aktarılamadı: ${gazeteName}. Portre/tam-boy gerçek kapak bulunamadı.` +
      (lastError?.message ? ` (${lastError.message})` : '')
    );
  };

  const startGazeteVideoFromCard = async (item, idx, visibleImageSrc = '', queueId = null) => {
    if (gazeteQueueRef.current.getState().active && !gazeteQueueRef.current.isCurrent(queueId)) {
      addSystemLog('Gazete sırası çalışıyor; yeni bir seçim için İPTAL ET düğmesini kullanın.', 'warn'); return false;
    }
    if (!item) return false;
    if (finalMp4BusyRef.current) {
      addSystemLog('Mevcut MP4 yerel hazırlığı henüz tamamlanmadı; gönderim kuyruğu üretimi bloke etmez.', 'warn');
      return false;
    }

    if (gazeteStartLockRef.current.locked || gazeteAutoVideoRef.current.active || uiProcessingRef.current) {
      const runningName = gazeteStartLockRef.current.name || gazeteAutoVideoRef.current.name || 'başka bir gazete';
      addSystemLog(`Gazete video zaten başlatıldı (${runningName}). İkinci tıklama yok sayıldı.`, 'warn');
      return false;
    }

    const finalName = matchOrFormatGazeteName(item.name) || item.name || 'Gazete';
    const token = `gazete_${Date.now()}_${Math.random().toString(36).slice(2)}`;

    // Lock immediately, BEFORE any await/fetch/rescue.
    gazeteStartLockRef.current = { locked: true, token, name: finalName };
    gazeteAutoVideoRef.current = { active: true, name: finalName };
    uiProcessingRef.current = true;

    const releaseIfMine = () => {
      if (gazeteStartLockRef.current.token === token) {
        gazeteStartLockRef.current = { locked: false, token: '', name: '' };
      }
    };

    try {
      setGazeteCurrentIdx(idx);
      setActiveTab('gazete');
      setGazeteGalleryView('grid');
      setConfig(prev => ({
        ...prev,
        tip: 'haber',
        outputType: 'video',
        sourceName: finalName
      }));
      setUiState(prev => ({
        ...prev,
        error: '',
        isProcessing: true,
        statusText: `${finalName} gazete okuma videosu hazırlanıyor...`
      }));

      let workingItem = item;
      const collectCandidates = (target) => {
        // EN ÖNEMLİ KURAL:
        // Kullanıcının tıkladığı anda DOM'da gerçekten görünen <img>.currentSrc
        // videoya giden 1 numaralı kaynaktır. React item içindeki eski/stale URL
        // artık bunun önüne geçemez.
        const actualVisibleCover = visibleImageSrc || null;

        return uniqueGazeteUrls([
          actualVisibleCover,
          target?.resolvedThumb,
          target?.thumbSrc,
          ...(target?.thumbCandidates || []),
          target?.resolvedFull,
          target?.fullSrc,
          ...(target?.fullCandidates || [])
        ]).filter(url =>
          url &&
          url !== target?.placeholder &&
          !String(url).startsWith('data:image/svg+xml')
        );
      };

      let videoImageCandidates = collectCandidates(workingItem);

      if (!videoImageCandidates.length) {
        addSystemLog(`${finalName}: gerçek kapak hazır değil, kaynak bir kez tekrar aranıyor...`, 'warn');
        const rescued = await rescueGazeteItem(finalName);

        if (gazeteStartLockRef.current.token !== token) {
          throw new Error('Gazete başlangıç kilidi değişti; karışık işlem engellendi.');
        }

        if (rescued) {
          await new Promise(r => setTimeout(r, 280));
          workingItem = gazeteItems.find(g => g.name === finalName) || workingItem;
          videoImageCandidates = collectCandidates(workingItem);
        }
      }

      if (!videoImageCandidates.length) throw new Error(`${finalName} için gerçek kapak bulunamadı.`);

      addSystemLog(`▶ ${finalName}: tek-job kilidi aktif; eski gazete okuma modu korunuyor.`, 'success');

      addSystemLog(`📰 ${finalName}: video başlamadan önce gerçek PORTRE gazete kapağı doğrulanacak; yatay preview kabul edilmeyecek.`, 'info');
      const dataUrl = await gazeteImageToDataUrl(videoImageCandidates, finalName);

      if (gazeteStartLockRef.current.token !== token) {
        throw new Error('Gazete başlangıç kilidi değişti; karışık işlem engellendi.');
      }

      const newFile = { name: `${finalName}.jpg`, type: 'image/jpeg', data: dataUrl };
      setUiState(prev => ({ ...prev, selectedMediaFiles: [newFile] }));

      const completed = await handleExecuteStart(
        [newFile],
        'video',
        {
          tip: 'haber',
          sourceName: finalName,
          customSceneImages: [dataUrl],
          forceGazeteImageOnly: true,
          _gazeteDirectClick: true,
          _gazeteSourceLock: finalName,
          _gazeteImageLock: dataUrl,
          _gazeteGoldenMaster: true,
          _gazeteStartToken: token,
          ...(queueId ? { _gazeteQueueId: queueId, videoFormat: 'mp4' } : {})
        }
      );

      if (!completed) {
        const workflowState = workflowRef.current?.state || {};
        const queueWasCancelled = !!queueId && !gazeteQueueRef.current.isCurrent(queueId);
        if (cancelRequestedRef.current || queueWasCancelled) {
          addSystemLog(`${finalName}: işlem DURDUR/iptal nedeniyle tamamlanmadı; bu bir üretim hatası olarak etiketlenmedi.`, 'warn');
          gazeteAutoVideoRef.current = { active: false, name: '' };
          uiProcessingRef.current = false;
          releaseIfMine();
          return false;
        }
        const detail = String(workflowState.error || workflowState.statusText || '').trim();
        const stage = String(workflowState.currentStage || workflowState.stage || workflowState.status || 'durum bilinmiyor');
        throw new Error(detail
          ? `Gazete videosu tamamlanamadı. Workflow aşaması/durumu: ${stage}. Ayrıntı: ${detail}`
          : `Gazete videosu tamamlanamadı. Workflow durumu: ${stage}; workflow içindeki son hata veya aşama bilgisi boş.`);
      }
      return true;
    } catch (e) {
      gazeteAutoVideoRef.current = { active: false, name: '' };
      uiProcessingRef.current = false;
      releaseIfMine();
      addSystemLog(`${finalName} otomatik video hatası: ${e.message}`, 'error');
      setUiState(prev => ({ ...prev, isProcessing: false, error: e.message }));
      return false;
    }
  };

  const runGazeteQueueEntryOnce = async (entry, queueId) => {
    if (!gazeteQueueRef.current.isCurrent(queueId)) return { phase: 'cancelled' };
    const isComparisonStep = entry.kind === 'comparison';
    if (!isComparisonStep && !entry.item) {
      addSystemLog(`✗ ${entry.label || entry.key}: gazete kartı listede yok; adım hata olarak kaydedildi, sıradaki adıma geçiliyor.`, 'error');
      return { phase: 'blocked', message: 'Gazete bugünkü listede bulunamadı.' };
    }
    const ok = isComparisonStep
      ? await startGazeteComparison(queueId, entry.names)
      : await startGazeteVideoFromCard(entry.item, entry.index, entry.visibleSrc, queueId);
    if (!gazeteQueueRef.current.isCurrent(queueId)) return { phase: 'cancelled' };
    if (!ok) return { phase: 'blocked', message: workflowRef.current?.state?.error || 'Video oluşturulamadı; bu gazete hata olarak kaydedildi.' };

    // Sıkı sıra: MP4 kayıt/indirme başarılı olur ve önizleme gerçekten sona erer; sonra sonraki gazete başlar.
    const finalization = finalMp4TaskRef.current;
    let localSaveResult = null;
    let finalizationError = '';
    if (finalization && finalization.jobId === workflowRef.current?.state?.jobId) {
      try { localSaveResult = await finalization.promise; }
      catch (error) { finalizationError = String(error?.message || error); }
    } else {
      finalizationError = 'MP4 sonlandırma görevi bulunamadı.';
    }
    if (!gazeteQueueRef.current.isCurrent(queueId)) return { phase: 'cancelled' };
    const title = workflowRef.current?.state?.script?.thumbnailText || entry.label || entry.item?.name || 'Gazete';
    if (!localSaveResult?.ok || !localSaveResult?.videoUrl) {
      const reason = finalizationError || localSaveResult?.reason || 'MP4 kayıt/indirme veya önizleme URL’si hazır değil.';
      addSystemLog(`✗ ${title}: sıradaki gazete DURDU. Mevcut videonun MP4 kaydı/önizlemesi tamamlanmadı: ${reason}`, 'error');
      const previewResult = await waitForGazetePreviewToFinish('', title, queueId, reason);
      if (!gazeteQueueRef.current.isCurrent(queueId) || previewResult?.phase === 'cancelled') return { phase: 'cancelled' };
      return { phase: 'blocked', message: reason };
    }

    const previewResult = await waitForGazetePreviewToFinish(localSaveResult.videoUrl, title, queueId);
    if (!gazeteQueueRef.current.isCurrent(queueId) || previewResult?.phase === 'cancelled') return { phase: 'cancelled' };
    addSystemLog(`✓ ${title}: MP4 indirildi ve önizlemenin sonuna kadar izlendi. Şimdi sıradaki gazete başlayabilir.`, 'success');
    if (entry.loopStepKey) _markPairLoopStepDone(entry.loopDate, entry.loopStepKey);
    return { phase: 'done', message: 'MP4 indirildi ve önizleme sona erdi. Sıradaki gazete başlıyor.' };
  };
  // v1.171: Çift döngüsü adımı MP4/FFmpeg hatasıyla biterse video baştan üretilip en fazla 2 kez daha denenir.
  gazeteQueueRunItemRef.current = async (entry, queueId) => {
    const maxJobRetries = entry.loopStepKey ? 2 : 0;
    let result = await runGazeteQueueEntryOnce(entry, queueId);
    for (let retry = 1; retry <= maxJobRetries; retry++) {
      const reason = String(result?.message || '');
      if (result?.phase !== 'blocked' || !/mp4|ffmpeg|cfr|encode|mediarecorder|finaliz|blob|çıktı dosyası|onarım/i.test(reason)) break;
      if (!gazeteQueueRef.current.isCurrent(queueId)) return { phase: 'cancelled' };
      addSystemLog(`↻ ${entry.label || entry.key}: MP4 hatası (${reason.slice(0, 200)}). Video sıfırdan üretilip ${retry}/${maxJobRetries} yeniden denenecek; doğru MP4 çıkmadan sıradaki adıma geçilmiyor.`, 'warn');
      await new Promise(resolve => setTimeout(resolve, 2500));
      if (!gazeteQueueRef.current.isCurrent(queueId)) return { phase: 'cancelled' };
      result = await runGazeteQueueEntryOnce(entry, queueId);
    }
    return result;
  };
  const startGazeteYorumla = async () => {
    if (gazeteQueueRef.current.getState().active || uiProcessingRef.current || gazeteStartLockRef.current.locked || gazeteAuto0700Ref.current.active || finalMp4BusyRef.current) {
      addSystemLog('YORUMLA başlatılamadı: devam eden bir işlem var; tamamlanmasını bekleyin.', 'warn'); return false;
    }
    const todayIso = _getTurkeyDateISO();
    if (gazeteDate !== todayIso) {
      addSystemLog(`YORUMLA yalnız Türkiye saatine göre bugünün ilk sayfalarını kullanır. Tarihi ${todayIso} yapıp gazeteleri yenileyin.`, 'warn');
      setGazeteDate(todayIso); return false;
    }
    const selectedTodayNames = stableGazeteOrder(gazeteItems.filter(item => item && item.requestedDate === todayIso).map(item => item.name));
    const selectedToday = selectedTodayNames.map(name => gazeteItems.find(item => item.name === name && item.requestedDate === todayIso)).filter(Boolean);
    const allSelected = selectedToday.length > 0 && selectedToday.every(item => gazeteSelectedNames.includes(item.name)) && gazeteSelectedNames.length === selectedToday.length;
    if (!allSelected) {
      addSystemLog(`YORUMLA için bugünün doğrulanmış gazetelerinin tamamını seçmelisiniz (${gazeteSelectedNames.length}/${selectedToday.length}).`, 'warn'); return false;
    }
    setActiveTab('gazete'); setGazeteSelectMode(false); setGazeteGalleryView('grid');
    setUiState(prev => ({ ...prev, selectedMediaFiles: [], error: '', isProcessing: true, statusText: 'Bugünün tüm gazete ilk sayfaları araştırmaya hazırlanıyor...' }));
    const files = [];
    const names = [];
    const token = `gazete_yorumla_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    gazeteStartLockRef.current = { locked: true, token, name: `Günün Gazete Yorumlaması (${selectedToday.length} gazete)` };
    uiProcessingRef.current = true;
    const yorumlaRunStartedAt = Date.now();
    GazeteYorumlaTrace.begin(token, todayIso, selectedToday.map(item => item.name));
    addSystemLog(`YORUMLA İŞ AKIŞI BAŞLATILDI: ${todayIso}; ${selectedToday.length} gazete. Kalıcı takip kimliği=${token}.`, 'info');
    try {
      GazeteYorumlaTrace.stageStart('Gazete ilk sayfalarının toplanması', `${selectedToday.length} gazete; 4'lü paralel gruplar; her sayfa için 45 sn + tek tarih doğrulamalı rescue/yeniden deneme`);
      const IMAGE_BATCH_SIZE = 4;
      for (let offset = 0; offset < selectedToday.length; offset += IMAGE_BATCH_SIZE) {
        const batch = selectedToday.slice(offset, offset + IMAGE_BATCH_SIZE);
        const batchStartedAt = Date.now();
        addSystemLog(`YORUMLA AŞAMA BAŞLADI: ilk sayfa görselleri ${offset + 1}-${offset + batch.length}/${selectedToday.length} alınıyor (paralel).`, 'info');
        const batchResults = await Promise.all(batch.map(async (item, localIndex) => {
          const index = offset + localIndex;
          const imageStartedAt = Date.now();
          const card = Array.from(gazeteGridRef.current?.querySelectorAll('[data-gazete-name]') || []).find(element => element.getAttribute('data-gazete-name') === item.name);
          const visible = card?.querySelector('img');
          const candidates = uniqueGazeteUrls([
            visible?.currentSrc, visible?.src, item.resolvedFull, item.fullSrc, ...(item.fullCandidates || []),
            item.resolvedThumb, item.thumbSrc, ...(item.thumbCandidates || [])
          ]).filter(candidate => candidate && candidate !== item.placeholder && !String(candidate).startsWith('data:image/svg+xml'));
          if (!candidates.length) throw new Error(`${item.name}: bugünün gerçek ilk sayfa görseli bulunamadı; eksik gazete ile toplu analiz başlatılmadı.`);
          addSystemLog(`YORUMLA GÖRSEL BAŞLADI: ${index + 1}/${selectedToday.length} — ${item.name}; aday=${Math.min(candidates.length, 6)}; timeout olursa kaynak yenilenip 1 kez tekrar denenecek.`, 'info');
          let retryCandidates = candidates;
          let lastImageError = null;
          let data = '';
          for (let attempt = 1; attempt <= 2; attempt++) {
            const imageController = new AbortController();
            let imageTimeout;
            try {
              const timeoutPromise = new Promise((_, reject) => {
                imageTimeout = setTimeout(() => {
                  imageController.abort();
                  reject(new Error(`${item.name}: ilk sayfa görseli 45 sn içinde alınamadı (timeout, deneme ${attempt}/2).`));
                }, 45000);
              });
              // İlk denemede hızlı ve güvenilir üç aday; retry'da tazelenmiş kaynakları önceleyip altı adaya kadar genişlet.
              const imagePromise = gazeteImageToDataUrl(retryCandidates.slice(0, attempt === 1 ? 3 : 6), item.name, imageController.signal, { fastCandidateFallback: true });
              data = await Promise.race([imagePromise, timeoutPromise]);
              if (!/^data:image\//i.test(String(data || ''))) throw new Error(`${item.name}: gerçek ilk sayfa görseli çözülemedi.`);
              addSystemLog(`YORUMLA GÖRSEL TAMAMLANDI: ${index + 1}/${selectedToday.length} — ${item.name} (${Math.round((Date.now() - imageStartedAt) / 1000)} sn; deneme ${attempt}/2).`, 'success');
              break;
            } catch (imageError) {
              lastImageError = imageError;
              if (attempt >= 2) break;
              addSystemLog(`YORUMLA GÖRSEL RETRY: ${item.name} ilk denemesi başarısız (${imageError?.message || imageError}); yalnız bu gazetenin bugüne ait kaynak adayları yenileniyor.`, 'warn');
              // Yeni kaynaklar aynı gazete + aynı gün filtresinden geçer; başka/stale gazeteye fallback yapılmaz.
              const refreshController = new AbortController();
              let refreshTimer;
              try {
                const refreshTimeout = new Promise((_, reject) => {
                  refreshTimer = setTimeout(() => { refreshController.abort(); reject(new Error(`${item.name}: kaynak yenileme 18 sn içinde tamamlanmadı.`)); }, 18000);
                });
                const refreshed = await Promise.race([
                  fetchIndividualGazeteCandidates(item.name, todayIso, refreshController.signal, { passIndex: 1, fastRetry: true }),
                  refreshTimeout
                ]);
                const refreshedUrls = (Array.isArray(refreshed) ? refreshed : []).map(candidate => candidate?.src).filter(Boolean);
                retryCandidates = uniqueGazeteUrls([...refreshedUrls, ...retryCandidates]);
                addSystemLog(`YORUMLA GÖRSEL KAYNAK YENİLEME: ${item.name}; yeni doğrulanmış aday=${refreshedUrls.length}; retry toplam aday=${retryCandidates.length}.`, refreshedUrls.length ? 'success' : 'warn');
              } catch (refreshError) {
                addSystemLog(`YORUMLA GÖRSEL KAYNAK YENİLEME UYARISI: ${item.name}: ${refreshError?.message || refreshError}. İlk adaylar ikinci kez denenecek.`, 'warn');
              } finally {
                if (refreshTimer) clearTimeout(refreshTimer);
                refreshController.abort();
              }
            } finally {
              if (imageTimeout) clearTimeout(imageTimeout);
              imageController.abort();
            }
          }
          if (!/^data:image\//i.test(String(data || ''))) {
            throw new Error(`${item.name}: ilk sayfa görseli iki denemede de alınamadı; kaynak doğrulaması nedeniyle bu gazete sessizce atlanmadı. Son hata: ${lastImageError?.message || 'bilinmeyen görsel hatası'}`);
          }
          return { name: item.name, file: { name: `${String(item.name).replace(/[^\p{L}\p{N}_-]+/gu, '_')}.jpg`, type: (String(data).match(/^data:([^;]+);/) || [])[1] || 'image/jpeg', data } };
        }));
        files.push(...batchResults.map(result => result.file));
        names.push(...batchResults.map(result => result.name));
        addSystemLog(`YORUMLA görsel grubu tamamlandı: ${offset + batch.length}/${selectedToday.length}; grup süresi ${Math.round((Date.now() - batchStartedAt) / 1000)} sn.`, 'success');
      }
      const imageCollectionMs = GazeteYorumlaTrace.stageEnd('Gazete ilk sayfalarının toplanması', `${files.length}/${selectedToday.length} sayfa hazır; ${Math.round((Date.now() - yorumlaRunStartedAt) / 1000)} sn toplam başlangıç süresi`);
      addSystemLog(`YORUMLA AŞAMA TAMAMLANDI: tüm ilk sayfa görselleri ${Math.round((imageCollectionMs || 0) / 1000)} sn; sabit sıra korundu.`, 'success');
      const todayLabel = new Date(`${todayIso}T12:00:00+03:00`).toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', year: 'numeric', weekday: 'long', timeZone: 'Europe/Istanbul' });
      const overrides = {
        tip: 'yorumla', outputType: 'video', videoFormat: 'mp4', aspectRatio: '16:9', duration: 'unlimited',
        language: 'tr', videoStyle: 'cinematic', analysisMode: 'deep_analysis', sourceName: 'Günün Gazete İlk Sayfaları',
        yorum: '', customSceneImages: [],
        _gazeteYorumla: { names, date: todayIso, dateLabel: todayLabel, minDurationSeconds: 420, minWords: 1250, narratorVoice: 'Aoede' }
      };
      setConfig(prev => ({ ...prev, tip: 'yorumla', outputType: 'video', videoFormat: 'mp4', aspectRatio: '16:9', duration: 'unlimited', language: 'tr', videoStyle: 'cinematic', analysisMode: 'deep_analysis' }));
      addSystemLog(`▶ YORUMLA başlıyor: ${todayLabel}; ${names.length} gazete. Tek 16:9 video, en az 7 dakika, kadın spiker Aoede, kaynaklı Google Search analizi.`, 'info');
      GazeteYorumlaTrace.stageStart('Gemini araştırması, uzun anlatı, ses ve video üretimi', 'Kalıcılık açık; aşama değişimleri ve hatalar tarihçeye yazılır');
      const completed = await handleExecuteStart(files, 'video', overrides);
      if (!completed) throw new Error(workflowRef.current?.state?.error || 'Günün gazete analizi videosu tamamlanamadı.');
      GazeteYorumlaTrace.finish('COMPLETED');
      addSystemLog(`YORUMLA TAMAMLANDI: toplam süre ${Math.round((Date.now() - yorumlaRunStartedAt) / 1000)} sn; ${names.length} gazete. Kalıcı iz kaydı=${token}.`, 'success');
      return true;
    } catch (e) {
      GazeteYorumlaTrace.finish('FAILED', String(e?.message || e));
      addSystemLog(`YORUMLA HATASI (${Math.round((Date.now() - yorumlaRunStartedAt) / 1000)} sn sonra): ${e.message}. Kalıcı iz kaydı=${token}; son aşama korunmuştur.`, 'error');
      setUiState(prev => ({ ...prev, isProcessing: false, error: e.message, statusText: '' }));
      return false;
    } finally {
      if (gazeteStartLockRef.current.token === token) gazeteStartLockRef.current = { locked: false, token: '', name: '' };
      uiProcessingRef.current = false;
      setGazeteSelectMode(true); setGazeteGalleryView('grid');
    }
  };

  const toggleGazeteSelection = name => {
    if (gazeteQueueRef.current.getState().active) return;
    setGazeteSelectedNames(names => names.includes(name) ? names.filter(value => value !== name) : ((config.tip === 'karsilastirma' && names.length >= 2) ? [names[names.length - 1], name] : [...names, name]));
  };
  // v1.122: Listelenen TÜM gazeteleri seç; hepsi seçiliyse seçimi temizle. Seçim modu kapalıysa açar.
  const toggleAllGazeteSelection = () => {
    if (gazeteQueueRef.current.getState().active) return;
    const todayIso = _getTurkeyDateISO();
    const allNames = stableGazeteOrder((config.tip === 'yorumla' ? gazeteItems.filter(item => item.requestedDate === todayIso) : gazeteItems).map(item => item.name));
    if (!allNames.length) return;
    setGazeteGalleryView('grid');
    setGazeteSelectMode(true);
    setGazeteSelectedNames(names => (names.length === allNames.length && allNames.every(name => names.includes(name))) ? [] : allNames);
  };
  const startSelectedGazeteQueue = async () => {
    if (gazeteQueueRef.current.getState().active || uiProcessingRef.current || gazeteStartLockRef.current.locked ||
        gazeteAuto0700Ref.current.active || finalMp4BusyRef.current) return;
    const stableSelectedNames = stableGazeteOrder(gazeteSelectedNames);
    addSystemLog(`Seçili gazete sırası sabitlendi: ${stableSelectedNames.join(' → ')}.`, 'info');
    const entries = stableSelectedNames.map(name => {
      const index = gazeteItems.findIndex(item => item.name === name);
      const item = gazeteItems[index];
      const card = Array.from(gazeteGridRef.current?.querySelectorAll('[data-gazete-name]') || [])
        .find(element => element.getAttribute('data-gazete-name') === name);
      const image = card?.querySelector('img');
      return item ? { key: name, item: { ...item }, index,
        visibleSrc: image?.currentSrc || image?.src || _gazeteAutoVisibleSource(item) } : null;
    }).filter(Boolean);
    if (!entries.length) return;
    setGazeteSelectMode(false); setGazeteSelectedNames([]); setGazeteGalleryView('grid');
    addSystemLog(`Gazete sırası başladı: ${entries.map(entry => entry.key).join(' → ')}.`, 'info');
    const finished = await gazeteQueueRef.current.start(entries);
    if (finished) {
      addSystemLog('Seçilen gazetelerin işlemleri bitti; sıra durdu.', 'info');
      setActiveTab('gazete');
      setTimeout(() => gazeteGridRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 80);
    }
  };

  // v1.164: ÇİFT DÖNGÜSÜ — 14 çift × (1. haber → 2. haber → karşılaştırma) = 42 video, sırayla, atlamadan.
  const startGazetePairLoop = async () => {
    if (gazeteQueueRef.current.getState().active || uiProcessingRef.current || gazeteStartLockRef.current.locked ||
        gazeteAuto0700Ref.current.active || finalMp4BusyRef.current) {
      addSystemLog('Çift döngüsü başlatılamadı: devam eden bir işlem var; tamamlanmasını bekleyin.', 'warn'); return;
    }
    const normalize = _gazeteOrderNormalize;
    const buildSingle = ([name, label], videoNo) => {
      const index = gazeteItems.findIndex(item => normalize(item.name) === normalize(name));
      const item = index >= 0 ? gazeteItems[index] : null;
      const card = item ? Array.from(gazeteGridRef.current?.querySelectorAll('[data-gazete-name]') || [])
        .find(element => element.getAttribute('data-gazete-name') === item.name) : null;
      const image = card?.querySelector('img');
      return { key: item?.name || name, kind: 'single', label: `${videoNo}. Video: ${label} Haber`, index,
        item: item ? { ...item } : null,
        visibleSrc: item ? (image?.currentSrc || image?.src || _gazeteAutoVisibleSource(item)) : '' };
    };
    const entries = [];
    GAZETE_PAIR_LOOP_PLAN.forEach(([first, second], pairIndex) => {
      const base = pairIndex * 3;
      const firstEntry = buildSingle(first, base + 1);
      const secondEntry = buildSingle(second, base + 2);
      entries.push(firstEntry, secondEntry, {
        key: `karsilastirma:${firstEntry.key}|${secondEntry.key}`, kind: 'comparison', index: -1, item: null,
        names: [firstEntry.key, secondEntry.key], label: `${base + 3}. Video: ${first[1]} vs ${second[1]} Karşılaştırma`
      });
    });
    // v1.166: Planda olmayan kalan gazeteler çiftlerden sonra tek tek sıraya eklenir.
    const plannedKeys = new Set(entries.filter(entry => entry.kind === 'single').map(entry => normalize(entry.key)));
    let nextVideoNo = entries.length + 1;
    gazeteItems.forEach(item => {
      if (plannedKeys.has(normalize(item.name))) return;
      plannedKeys.add(normalize(item.name));
      entries.push(buildSingle([item.name, gazeteDisplayName(item.name)], nextVideoNo));
      nextVideoNo += 1;
    });
    // v1.167: Kaldığı yerden devam — aynı tarihte tamamlanan adımlar atlanır.
    entries.forEach(entry => { entry.loopStepKey = entry.key; entry.loopDate = gazeteDate; });
    const loopTotal = entries.length;
    let progress = _readPairLoopProgress(gazeteDate);
    // v1.169: Önceki süreç loglarını incele; COMPLETED biten adımları bul ve ilerleme defteriyle birleştir.
    const recoverDoneFromLogs = (loopEntries, sinceMs) => {
      const found = [];
      let runs = [];
      try { runs = _processLogManager?.listRuns?.() || []; } catch (e) { ErrorHandler.silent(e); }
      const aliasesOf = (name) => {
        const set = new Set([normalize(name)]);
        try { const formatted = matchOrFormatGazeteName(name); if (formatted) set.add(normalize(formatted)); } catch (e) { ErrorHandler.silent(e); }
        return set;
      };
      const singles = loopEntries.filter(entry => entry.kind === 'single').map(entry => ({ entry, aliases: aliasesOf(entry.key) }));
      const comparisons = loopEntries.filter(entry => entry.kind === 'comparison').map(entry => ({ entry, a: aliasesOf(entry.names[0]), b: aliasesOf(entry.names[1]) }));
      runs.forEach(run => {
        if (run.status !== 'COMPLETED' || run.startedAt < sinceMs) return;
        if (_getTurkeyDateISO(new Date(run.startedAt)) !== gazeteDate) return;
        const cmpMatch = run.texts.map(text => text.match(/Karşılaştırma:\s*(.+?)\s+[×x]\s+(.+?)\s+kapakları hazır/i)).find(Boolean);
        if (cmpMatch) {
          const first = normalize(cmpMatch[1]), second = normalize(cmpMatch[2]);
          const hit = comparisons.find(item => (item.a.has(first) && item.b.has(second)) || (item.a.has(second) && item.b.has(first)));
          if (hit) found.push(hit.entry.key);
          return;
        }
        const lockMatch = run.texts.map(text => text.match(/Gazete job kilidi:\s*kaynak\s*=\s*["'“]?([^"'”,]+)["'”]?/i)).find(Boolean);
        const sourceKey = normalize(lockMatch ? lockMatch[1] : run.source);
        if (!sourceKey) return;
        const hit = singles.find(item => item.aliases.has(sourceKey));
        if (hit) found.push(hit.entry.key);
      });
      let lastRun = null;
      try { lastRun = (_processLogManager?.listRuns?.() || []).filter(run => run.startedAt >= sinceMs).sort((x, y) => y.startedAt - x.startedAt)[0] || null; } catch (e) { ErrorHandler.silent(e); }
      return { found: [...new Set(found)], lastRun };
    };
    {
      const recovery = recoverDoneFromLogs(entries, progress.resetAt || 0);
      const added = recovery.found.filter(key => !progress.doneKeys.includes(String(key)));
      if (added.length) { progress.doneKeys.push(...added.map(String)); _writePairLoopProgress(progress); }
      addSystemLog(`LOG İNCELEME: önceki süreç loglarında ${recovery.found.length} tamamlanmış adım bulundu${added.length ? ` (${added.length} tanesi ilerleme defterinde yoktu, eklendi)` : ''}.` +
        (recovery.lastRun && recovery.lastRun.status !== 'COMPLETED' ? ` Son kayıtlı süreç "${recovery.lastRun.source || recovery.lastRun.title || 'bilinmiyor'}" durumu=${recovery.lastRun.status}; bu adım baştan çalıştırılacak.` : ''), 'info');
    }
    let runEntries = entries.filter(entry => !progress.doneKeys.includes(String(entry.key)));
    if (!runEntries.length) {
      progress = { date: gazeteDate, doneKeys: [], resetAt: Date.now() }; _writePairLoopProgress(progress);
      runEntries = entries;
      addSystemLog('Önceki döngünün tüm adımları tamamlanmıştı; döngü baştan başlatılıyor.', 'info');
    }
    const loopSkipped = loopTotal - runEntries.length;
    if (loopSkipped > 0) addSystemLog(`KALDIĞI YERDEN DEVAM: ${loopSkipped}/${loopTotal} adım daha önce tamamlanmıştı, atlanıyor. İlk adım: ${runEntries[0].label}.`, 'info');
    setActiveTab('gazete'); setGazeteSelectMode(false); setGazeteSelectedNames([]); setGazeteGalleryView('grid');
    addSystemLog(`ÇİFT DÖNGÜSÜ başladı: ${GAZETE_PAIR_LOOP_PLAN.length} çift (${GAZETE_PAIR_LOOP_PLAN.length * 3} video) + ${loopTotal - GAZETE_PAIR_LOOP_PLAN.length * 3} kalan gazete = ${loopTotal} video; bu koşuda ${runEntries.length} adım çalışacak. Sıra: ${runEntries.map(entry => entry.label).join(' → ')}.`, 'info');
    const finished = await gazeteQueueRef.current.start(runEntries);
    setConfig(prev => ({ ...prev, tip: 'haber' }));
    if (finished) {
      const finalItems = gazeteQueueRef.current.getState().items;
      const failed = finalItems.filter(entry => entry.phase === 'error');
      const doneTotal = loopSkipped + finalItems.length - failed.length;
      if (!failed.length) _writePairLoopProgress({ date: gazeteDate, doneKeys: [], resetAt: Date.now() });
      addSystemLog(failed.length
        ? `ÇİFT DÖNGÜSÜ bitti: ${doneTotal}/${loopTotal} video tamam. Başarısız adımlar: ${failed.map(entry => `${entry.label} (${String(entry.message || '').slice(0, 80)})`).join('; ')}. Döngüyü tekrar başlatırsanız yalnız bu adımlar yeniden denenir.`
        : `ÇİFT DÖNGÜSÜ bitti: ${loopTotal}/${loopTotal} video tamamlandı.`, failed.length ? 'warn' : 'success');
      setActiveTab('gazete');
      setTimeout(() => gazeteGridRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 80);
    }
  };

  // v1.125: Seçilen İKİ gazetenin manşetlerini tek videoda karşılaştır.
  // v1.164: queueId verilirse karşılaştırma seçili gazete kuyruğunun bir adımı olarak çalışır (true/false döner).
  const startGazeteComparison = async (queueId = null, namesOverride = null) => {
    const comparisonNames = Array.isArray(namesOverride) ? namesOverride : gazeteSelectedNames;
    if (comparisonNames.length !== 2) { addSystemLog('Karşılaştırma için tam 2 gazete seçin.', 'warn'); return false; }
    if (gazeteQueueRef.current.getState().active && !(queueId && gazeteQueueRef.current.isCurrent(queueId))) {
      addSystemLog('Gazete sırası çalışıyor; karşılaştırma için önce sırayı iptal edin.', 'warn'); return false;
    }
    if (uiProcessingRef.current || gazeteStartLockRef.current.locked ||
        gazeteAuto0700Ref.current.active || finalMp4BusyRef.current) {
      addSystemLog('Devam eden bir işlem var; bitince karşılaştırmayı tekrar başlatın.', 'warn'); return false;
    }
    const entries = comparisonNames.map(name => {
      const item = gazeteItems.find(g => g.name === name);
      const card = Array.from(gazeteGridRef.current?.querySelectorAll('[data-gazete-name]') || []).find(element => element.getAttribute('data-gazete-name') === name);
      const image = card?.querySelector('img');
      return item ? { item: { ...item }, visibleSrc: image?.currentSrc || image?.src || _gazeteAutoVisibleSource(item) } : null;
    }).filter(Boolean);
    if (entries.length !== 2) { addSystemLog(`Karşılaştırma: ${comparisonNames.join(' × ')} kartlarından biri listede yok.`, 'error'); return false; }
    const token = `karsilastirma_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    const names = entries.map(entry => matchOrFormatGazeteName(entry.item.name) || entry.item.name || 'Gazete');
    gazeteStartLockRef.current = { locked: true, token, name: `${names[0]} × ${names[1]}` };
    uiProcessingRef.current = true;
    let comparisonOk = false;
    try {
      setActiveTab('gazete'); setGazeteSelectMode(false); setGazeteSelectedNames([]); setGazeteGalleryView('grid');
      setConfig(prev => ({ ...prev, tip: 'karsilastirma', outputType: 'video', aspectRatio: '9:16' }));
      setUiState(prev => ({ ...prev, error: '', isProcessing: true, statusText: `${names[0]} × ${names[1]} karşılaştırması hazırlanıyor...` }));
      const images = [];
      for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];
        const collect = (target) => uniqueGazeteUrls([entry.visibleSrc, target?.resolvedThumb, target?.thumbSrc, ...(target?.thumbCandidates || []), target?.resolvedFull, target?.fullSrc, ...(target?.fullCandidates || [])])
          .filter(url => url && url !== target?.placeholder && !String(url).startsWith('data:image/svg+xml'));
        let candidates = collect(entry.item);
        if (!candidates.length) {
          addSystemLog(`${names[i]}: gerçek kapak hazır değil, kaynak bir kez tekrar aranıyor...`, 'warn');
          if (await rescueGazeteItem(names[i])) { await new Promise(r => setTimeout(r, 280)); candidates = collect(gazeteItems.find(g => g.name === entry.item.name) || entry.item); }
        }
        if (!candidates.length) throw new Error(`${names[i]} için gerçek kapak bulunamadı.`);
        images.push(await gazeteImageToDataUrl(candidates, names[i]));
      }
      addSystemLog(`⚔ Karşılaştırma: ${names[0]} × ${names[1]} kapakları hazır; tek istekte analiz edilecek.`, 'success');
      const files = images.map((data, i) => ({ name: `${names[i]}.jpg`, type: 'image/jpeg', data }));
      const completed = await handleExecuteStart(files, 'video', {
        tip: 'karsilastirma', sourceName: `${names[0]} ve ${names[1]}`, customSceneImages: [], videoFormat: 'mp4', aspectRatio: '9:16',
        _karsilastirma: { names, images },
        ...(queueId ? { _gazeteQueueId: queueId } : {})
      });
      if (!completed) throw new Error(workflowRef.current?.state?.error || 'Karşılaştırma videosu tamamlanamadı.');
      comparisonOk = true;
    } catch (e) {
      uiProcessingRef.current = false;
      addSystemLog(`Karşılaştırma hatası: ${e.message}`, 'error');
      setUiState(prev => ({ ...prev, isProcessing: false, error: e.message }));
    } finally {
      if (gazeteStartLockRef.current.token === token) {
        gazeteStartLockRef.current = { locked: false, token: '', name: '' };
        // v1.133: Bir karşılaştırma bittiğinde seçici otomatik yeniden açılır.
        // Kullanıcı Haber/Güzel Söz'e geçip Karşılaştırma'ya geri dönmek zorunda kalmaz.
        setActiveTab('gazete');
        setGazeteGalleryView('grid');
        setGazeteSelectedNames([]);
        if (!queueId) setGazeteSelectMode(true);
        if (!queueId) addSystemLog('Karşılaştırma işlemi sonlandı. Yeni bir karşılaştırma için iki gazeteyi seçip “SEÇİLEN 2/2 GAZETEYİ KARŞILAŞTIR” düğmesine basabilirsiniz.', 'info');
      }
    }
    return comparisonOk;
  };

  const _gazeteAutoVisibleSource = (item) => {
    if (!item) return '';
    const values = [
      item.resolvedThumb,
      item.thumbSrc,
      item.resolvedFull,
      item.fullSrc,
      ...(item.thumbCandidates || []),
      ...(item.fullCandidates || [])
    ];

    return values.find(src =>
      src &&
      src !== item.placeholder &&
      !String(src).startsWith('data:image/svg+xml')
    ) || '';
  };

  const _persistGazeteAutoRun = () => {
    const batch = gazeteAuto0700Ref.current;
    _saveGazeteAuto0700State({
      date: batch.date,
      status: batch.cancelled ? 'cancelled' : (batch.active ? 'running' : 'completed'),
      trigger: batch.trigger,
      queue: batch.queue,
      completed: batch.completed,
      failed: batch.failed,
      timings: batch.timings || [],
      current: batch.current,
      updatedAt: Date.now()
    });
  };

  const startGazeteMorningBatch = async (trigger = 'manual', forceRestart = false) => {
    if (gazeteQueueRef.current.getState().active) return false;
    const todayTR = _getTurkeyDateISO();

    if (gazeteAuto0700Ref.current.active) {
      addSystemLog('07:00 Gazete Otonomu zaten çalışıyor; ikinci başlangıç yok sayıldı.', 'warn');
      return false;
    }

    if (uiProcessingRef.current || gazeteStartLockRef.current.locked || gazeteAutoVideoRef.current.active) {
      addSystemLog('07:00 Gazete Otonomu: başka bir video işi devam ediyor; 60 saniye sonra tekrar denenecek.', 'warn');
      setTimeout(() => {
        if ((gazeteAuto0700Enabled || trigger === 'manual') && !gazeteAuto0700Ref.current.active) {
          startGazeteMorningBatch(trigger, forceRestart);
        }
      }, 60_000);
      return false;
    }

    const saved = _loadGazeteAuto0700State();
    if (
      !forceRestart &&
      saved?.date === todayTR &&
      (saved?.status === 'completed' || saved?.status === 'cancelled')
    ) {
      addSystemLog(`07:00 Gazete Otonomu bugün zaten tamamlandı (${todayTR}).`, 'info');
      return true;
    }

    const batch = {
      active: true,
      date: todayTR,
      queue: [],
      completed:
        !forceRestart && saved?.date === todayTR && Array.isArray(saved?.completed)
          ? [...saved.completed]
          : [],
      failed: [],
      timings:
        !forceRestart && saved?.date === todayTR && Array.isArray(saved?.timings)
          ? [...saved.timings]
          : [],
      current: '',
      trigger
    };

    // v1.173: sabit paylaşım aralıkları ve otomatik Buffer planlaması tamamen kaldırıldı.
    gazeteAuto0700Ref.current = batch;

    setGazeteAuto0700Ui({
      active: true,
      current: '',
      total: 0,
      completed: batch.completed.length,
      failed: 0,
      message: 'Bugünün gazeteleri hazırlanıyor...'
    });

    setActiveTab('gazete');
    setGazeteGalleryView('grid');
    setGazeteDate(todayTR);

    addSystemLog(
      `☀️ FIX CHECKLIST v1.36: 07:00 Gazete Otonomu başladı (${trigger}, ${todayTR}).`,
      'success'
    );

    try {
      // Kaynaklar sabah geç yanıt verirse kısa aralıklarla en fazla 3 kez yenile.
      let items = [];
      for (let attempt = 1; attempt <= 3; attempt++) {
        await fetchGazeteManşetleri(todayTR);

        // React state/ref'in yerleşmesi için kısa bekleme.
        for (let waitStep = 0; waitStep < 12; waitStep++) {
          await new Promise(r => setTimeout(r, 250));
          if (!gazeteLoadingRef.current && gazeteItemsRef.current.length > 0) break;
        }

        items = [...gazeteItemsRef.current];

        const usableCount = items.filter(item => !!_gazeteAutoVisibleSource(item)).length;
        addSystemLog(
          `07:00 Gazete Otonomu: manşet taraması ${attempt}/3 → ${usableCount}/${items.length || 30} işlenebilir kart.`,
          usableCount ? 'info' : 'warn'
        );

        if (usableCount > 0) break;
        if (attempt < 3) await new Promise(r => setTimeout(r, 60_000));
      }

      if (!items.length) {
        throw new Error('Gazete listesi yüklenemedi; otomatik seri başlatılmadı.');
      }

      const completedSet = new Set(batch.completed);
      batch.queue = items
        .map(item => item.name)
        .filter(Boolean)
        .filter(name => forceRestart || !completedSet.has(name));

      _persistGazeteAutoRun();

      setGazeteAuto0700Ui(prev => ({
        ...prev,
        total: batch.queue.length + batch.completed.length,
        completed: batch.completed.length,
        message: `${batch.queue.length} gazete sıraya alındı.`
      }));

      for (let qIndex = 0; qIndex < batch.queue.length; qIndex++) {
        if (!gazeteAuto0700Ref.current.active) break;

        const name = batch.queue[qIndex];
        batch.current = name;
        _persistGazeteAutoRun();

        const currentItems = gazeteItemsRef.current;
        const itemIndex = currentItems.findIndex(item => item.name === name);
        const item = itemIndex >= 0 ? currentItems[itemIndex] : null;

        setGazeteAuto0700Ui(prev => ({
          ...prev,
          current: name,
          message: `${qIndex + 1}/${batch.queue.length}: ${name} videosu hazırlanıyor...`
        }));

        if (!item) {
          batch.failed.push({ name, reason: 'Kart bulunamadı' });
          _persistGazeteAutoRun();
          setGazeteAuto0700Ui(prev => ({ ...prev, failed: batch.failed.length }));
          continue;
        }

        const visibleSrc = _gazeteAutoVisibleSource(item);

        const gazeteStartedAt = Date.now();
        const videoStartedAt = gazeteStartedAt;
        let videoFinishedAt = 0;
        let scheduledDueAt = null;
        let intervalMinutesUsed = 0;

        addSystemLog(
          `☀️ 07:00 Otonom ${qIndex + 1}/${batch.queue.length}: ${name} seçiliyor... (ölçüm başladı)`,
          'info'
        );

        let ok = false;
        try {
          ok = await startGazeteVideoFromCard(item, itemIndex, visibleSrc);
          videoFinishedAt = Date.now();
        } catch (e) {
          ok = false;
          videoFinishedAt = Date.now();
          ErrorHandler.silent(e);
        }

        if (!videoFinishedAt) videoFinishedAt = Date.now();

        if (ok) {
          // MP4 finalizasyonu ve indirme tamamlanır; önizleme bittikten sonra sıradaki gazete başlar.
          const activeJobId = workflowRef.current?.state?.jobId || '';
          const finalization = finalMp4TaskRef.current;
          let localSaveResult = null;
          if (finalization && finalization.jobId === activeJobId) {
            try { localSaveResult = await finalization.promise; }
            catch (finalizeError) { addSystemLog(`${name}: MP4 yerel hazırlık/indirme adımı hata verdi; ayrıntı: ${finalizeError?.message || finalizeError}. Sıra devam edecek.`, 'warn'); }
          }
          if (localSaveResult?.ok !== true || !localSaveResult?.videoUrl) {
            const reason = localSaveResult?.reason || 'MP4 kayıt/indirme veya önizleme URL’si hazır değil.';
            batch.failed.push({ name, reason: `MP4 yerel kaydı/indirmesi başarısız: ${reason}` });
            addSystemLog(`✗ 07:00 Otonom: ${name} için MP4/önizleme hazır değil. Sıradaki gazete başlamayacak; sıra iptal edilene kadar bekliyor.`, 'error');
            const previewResult = await waitForGazetePreviewToFinish('', name, null, reason);
            if (previewResult?.phase === 'cancelled' || !gazeteAuto0700Ref.current.active) break;
          } else {
            if (!batch.completed.includes(name)) batch.completed.push(name);
            addSystemLog(`✓ 07:00 Otonom: ${name} videosu üretildi, seslendirildi ve MP4 indirme adımı tamamlandı. Önizleme sonuna kadar sonraki gazete bekleyecek.`, 'success');
            const previewResult = await waitForGazetePreviewToFinish(localSaveResult.videoUrl, name, null);
            if (previewResult?.phase === 'cancelled' || !gazeteAuto0700Ref.current.active) break;
            addSystemLog(`07:00 Otonom: ${name} önizlemesi tamamlandı; sıradaki gazete başlatılıyor.`, 'success');
          }
        }

        const gazeteFinishedAt = Date.now();
        const videoMs = Math.max(0, videoFinishedAt - videoStartedAt);
        const totalMs = Math.max(0, gazeteFinishedAt - gazeteStartedAt);

        const timingRecord = {
          name,
          startedAt: gazeteStartedAt,
          finishedAt: gazeteFinishedAt,
          videoMs,
          totalMs,
          intervalMinutesUsed,
          dueAt: scheduledDueAt,
          videoOk: !!ok,
        };

        batch.timings.push(timingRecord);

        addSystemLog(
          `⏱ ${name}: toplam ${formatGazeteDuration(totalMs)} | video ${formatGazeteDuration(videoMs)} | ek bekleme ${intervalMinutesUsed}dk.`,
          'info'
        );

        // Sabit paylaşım aralığı kaldırıldı; doğal üretim süresi tek başına ilerler.

        _persistGazeteAutoRun();

        setGazeteAuto0700Ui(prev => ({
          ...prev,
          completed: batch.completed.length,
          failed: batch.failed.length
        }));

        // v1.154: finalizasyon/indirme isteği bittiyse ek yapay bekleme olmadan sonraki gazeteye geç.
      }

      batch.active = false;
      batch.current = '';
      _persistGazeteAutoRun();

      setGazeteAuto0700Ui({
        active: false,
        current: '',
        total: batch.queue.length + batch.completed.length,
        completed: batch.completed.length,
        failed: batch.failed.length,
        message: `Tamamlandı: ${batch.completed.length} başarılı, ${batch.failed.length} hata.`
      });

      setActiveTab('gazete');
      setGazeteGalleryView('grid');

      const timingRows = batch.timings || [];
      const avgTotalMs = timingRows.length
        ? timingRows.reduce((sum, x) => sum + Number(x.totalMs || 0), 0) / timingRows.length
        : 0;
      const maxTiming = timingRows.reduce(
        (best, x) => !best || Number(x.totalMs || 0) > Number(best.totalMs || 0) ? x : best,
        null
      );

      addSystemLog(
        `☀️ 07:00 GAZETE OTONOMU TAMAMLANDI — video başarılı=${batch.completed.length}, video hata=${batch.failed.length}` +
        `` +
        ` | ortalama uçtan uca=${formatGazeteDuration(avgTotalMs)}` +
        ` | en uzun=${maxTiming ? `${maxTiming.name} ${formatGazeteDuration(maxTiming.totalMs)}` : 'yok'}` +
        ` | sabit paylaşım aralığı=0dk` +
        (batch.failed.length ? ` | Video hatalı: ${batch.failed.map(x => x.name).join(', ')}` : '') +
(batch.failed.length) ? 'warn' : 'success'
      );

      for (const row of timingRows) {
        addSystemLog(
          `⏱ SÜRE RAPORU | ${row.name} | toplam=${formatGazeteDuration(row.totalMs)} | video=${formatGazeteDuration(row.videoMs)} | ek_bekleme=${row.intervalMinutesUsed}dk`,
          'info'
        );
      }

      return true;
    } catch (e) {
      batch.active = false;
      batch.current = '';
      _saveGazeteAuto0700State({
        date: todayTR,
        status: 'failed',
        trigger,
        queue: batch.queue,
        completed: batch.completed,
        failed: [...batch.failed, { name: 'OTONOM', reason: e.message }],
        timings: batch.timings || [],
        current: '',
        updatedAt: Date.now()
      });

      setGazeteAuto0700Ui(prev => ({
        ...prev,
        active: false,
        current: '',
        failed: prev.failed + 1,
        message: `Otonom hata: ${e.message}`
      }));

      addSystemLog(`07:00 Gazete Otonomu hata: ${e.message}`, 'error');
      return false;
    }
  };

  // Türkiye saati 07:00-08:30 aralığında sekme açıksa günlük otonomu bir kez başlat.
  useEffect(() => {
    if (!GAZETE_AUTO_0700_SCHEDULER_ENABLED || !gazeteAuto0700Enabled) return;

    let cancelled = false;

    const checkSchedule = () => {
      if (cancelled || gazeteAuto0700Ref.current.active) return;

      const tr = _getTurkeyClockParts();
      if (
        tr.minutesOfDay < GAZETE_AUTO_0700_START_MINUTE ||
        tr.minutesOfDay > GAZETE_AUTO_0700_CATCHUP_END
      ) {
        return;
      }

      const saved = _loadGazeteAuto0700State();
      if (saved?.date === tr.date && (saved?.status === 'completed' || saved?.status === 'cancelled')) return;

      startGazeteMorningBatch('schedule', false);
    };

    const initialTimer = setTimeout(checkSchedule, 1500);
    const interval = setInterval(checkSchedule, 30_000);

    return () => {
      cancelled = true;
      clearTimeout(initialTimer);
      clearInterval(interval);
    };
  }, [gazeteAuto0700Enabled]);

  const addFullImageToMedia = async (src, name) => {
    try {
      setGazeteLoading(true);
      const finalName = matchOrFormatGazeteName(name) || name;
      const dataUrl = await gazeteImageToDataUrl(src, finalName);
      const newFile = { name: finalName + '.jpg', type: 'image/jpeg', data: dataUrl };

      setUiState(prev => ({ ...prev, selectedMediaFiles: [...(prev.selectedMediaFiles || []), newFile] }));
      setConfig(prev => ({ ...prev, sourceName: finalName }));
      await addGazeteToCustomSceneImages(dataUrl, finalName);
      setActiveTab('media');
      addSystemLog(`✓ Tam gazete görseli eklendi, Kaynak otomatik seçildi: ${finalName}`, 'success');
    } catch (e) {
      addSystemLog('Aktarma hatası: ' + e.message, 'error');
    } finally {
      setGazeteLoading(false);
    }
  };
  const [gazeteGalleryView, setGazeteGalleryView] = useState('grid');
  const [gazeteCurrentIdx, setGazeteCurrentIdx] = useState(0);

    const performanceApiCalls = livePerformanceMetrics.apiCalls || [];
  const performanceSteps = livePerformanceMetrics.steps || [];
  const performanceRuns = livePerformanceMetrics.runs || [];
  const performanceCompletedRuns = performanceRuns.filter(r => Number.isFinite(Number(r.productionMs)) && r.productionMs >= 0);
  const performanceAverageProductionMs = performanceCompletedRuns.length ? Math.round(performanceCompletedRuns.reduce((sum, r) => sum + r.productionMs, 0) / performanceCompletedRuns.length) : null;
  const performanceApiUsageCalls = performanceApiCalls.filter(c => c.tokenSource === 'API kullanım üstverisi');
  const performanceActualPromptTokens = performanceApiUsageCalls.reduce((sum, c) => sum + (Number(c.promptTokens) || 0), 0);
  const performanceActualOutputTokens = performanceApiUsageCalls.reduce((sum, c) => sum + (Number(c.outputTokens) || 0), 0);
  const performanceActualTotalTokens = performanceApiUsageCalls.reduce((sum, c) => sum + (Number(c.totalTokens) || 0), 0);
  const performanceEstimatedCalls = performanceApiCalls.filter(c => c.tokenSource !== 'API kullanım üstverisi');
  const performanceEstimatedTextTokens = performanceEstimatedCalls.reduce((sum, c) => sum + (Number(c.estimatedTextTotalTokens) || 0), 0);
  const performanceRunsWithActualTokens = performanceCompletedRuns.map(run => {
    const calls = performanceApiCalls.filter(c => c.runId === run.id && c.tokenSource === 'API kullanım üstverisi');
    return { run, totalTokens: calls.reduce((sum, c) => sum + (Number(c.totalTokens) || 0), 0), calls: calls.length };
  }).filter(x => x.calls > 0);
  const performanceAverageActualTokensPerRun = performanceRunsWithActualTokens.length ? Math.round(performanceRunsWithActualTokens.reduce((sum, x) => sum + x.totalTokens, 0) / performanceRunsWithActualTokens.length) : null;
  const performanceTokensByCategory = Object.values(performanceApiCalls.reduce((acc, call) => {
    const key = call.category || 'Diğer';
    if (!acc[key]) acc[key] = { key, count: 0, actualTotal: 0, actualCalls: 0, estimatedTotal: 0, estimatedCalls: 0, durationMs: 0 };
    const row = acc[key]; row.count += 1; row.durationMs += Number(call.durationMs) || 0;
    if (call.tokenSource === 'API kullanım üstverisi') { row.actualCalls += 1; row.actualTotal += Number(call.totalTokens) || 0; }
    else { row.estimatedCalls += 1; row.estimatedTotal += Number(call.estimatedTextTotalTokens) || 0; }
    return acc;
  }, {})).sort((a, b) => (b.actualTotal + b.estimatedTotal) - (a.actualTotal + a.estimatedTotal));
  const performanceActiveStages = livePerformanceMetrics.activeStages || [];
  const livePerfDuration = ms => {
    if (!Number.isFinite(Number(ms)) || ms < 0) return '—';
    const sec = Math.round(Number(ms) / 1000);
    if (sec < 60) return `${sec} sn`;
    const min = Math.floor(sec / 60); const rem = sec % 60;
    if (min < 60) return `${min} dk ${String(rem).padStart(2, '0')} sn`;
    return `${Math.floor(min / 60)} sa ${String(min % 60).padStart(2, '0')} dk`;
  };
  const livePerfNumber = value => Number.isFinite(Number(value)) ? Number(value).toLocaleString('tr-TR') : '—';
  const performanceStepSummaries = Object.values(performanceSteps.reduce((acc, step) => {
    const key = step.stageId || step.label;
    if (!acc[key]) acc[key] = { key, label: step.label, count: 0, totalMs: 0, lastMs: 0 };
    acc[key].count += 1; acc[key].totalMs += Number(step.durationMs) || 0; acc[key].lastMs = Number(step.durationMs) || 0;
    return acc;
  }, {})).map(x => ({ ...x, averageMs: x.count ? Math.round(x.totalMs / x.count) : 0 })).sort((a, b) => b.totalMs - a.totalMs);
  const liveMonitorLogs = (sysLogs || []).filter(log => {
    if (liveMonitorFilter === 'errors') return log.type === 'warn' || log.type === 'error' || /(hata|error|failed|redded|limit|rate.limit|başarısız|basarisiz)/i.test(String(log?.text || ''));
    return true;
  }).slice(-140);
  const liveMonitorFmt = value => value && Number.isFinite(Number(value)) ? new Date(Number(value)).toLocaleString('tr-TR') : '—';
  const handleLiveMonitorPointerMove = event => {
    const drag = liveMonitorDragRef.current;
    if (!drag) return;
    const width = Math.min(560, Math.max(280, window.innerWidth - 24));
    const height = Math.min(620, Math.max(250, window.innerHeight - 24));
    const left = Math.max(8, Math.min(window.innerWidth - width - 8, drag.left + event.clientX - drag.startX));
    const top = Math.max(8, Math.min(window.innerHeight - height - 8, drag.top + event.clientY - drag.startY));
    setLiveMonitorPosition({ left, top });
  };
  const handleLiveMonitorPointerUp = () => {
    liveMonitorDragRef.current = null;
    try { SafeStorage.setItem('ns_liveMonitorPosition', JSON.stringify(liveMonitorPosition)); } catch (_) {}
  };
  const copyLiveMonitorLogs = () => {
    // v1.183: Panoya kopyalanan logun ilk satırı sürüm taşır — kullanıcı kayıtları
    // sürüm doğrulamasına hemen elverişli olur (SÜREÇ TXT zaten Sürüm satırı alıyordu).
    const txt = `${APP_VERSION.toString()} — canlı izleme logları (${new Date().toLocaleString('tr-TR')})\n` + buildTimestampedLogText(liveMonitorLogs);
    const fallbackCopy = () => {
      const ta = document.createElement('textarea'); ta.value = txt; ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); addSystemLog('Canlı izleme logları panoya kopyalandı.', 'success'); }
      catch (_) { addSystemLog('Log kopyalanamadı; tarayıcı izinlerini kontrol edin.', 'warn'); }
      finally { document.body.removeChild(ta); }
    };
    if (navigator.clipboard?.writeText) navigator.clipboard.writeText(txt).then(() => addSystemLog('Canlı izleme logları panoya kopyalandı.', 'success')).catch(fallbackCopy);
    else fallbackCopy();
  };

